INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_348e6eb1d913130632bfe139', 'zh-CN', 'Saarthi Guide：蒂鲁帕蒂朝圣出行指南', '整合蒂鲁帕蒂与蒂鲁马拉朝圣的达显信息、寺庙时间、路线与出行指引的一站式指南', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_348e6eb1d913130632bfe139', 'en', 'Saarthi Guide', 'Hi Product Hunt! 👋 I started building Saarthi to solve a problem I noticed around pilgrimage travel in Tirupati and Tirumala.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_083d0fb0f54dfd4d811d4c6f', 'zh-CN', 'ONE eSIM 旅行预付 eSIM 套餐', '覆盖200多个目的地的预付旅行 eSIM 流量套餐，出发前安装，落地启用，无需换卡或担心漫游费。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_083d0fb0f54dfd4d811d4c6f', 'en', 'ONE eSIM', 'Prepaid travel eSIM data plans for 200+ destinations. Install before you fly, switch on when you land. No roaming bills, no SIM swap.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0780e99cffbd4b813fd3f583', 'zh-CN', 'DocPixelKB：精确调整护照照片的 KB、像素和 DPI', '在本地把护照照片、签名或拇指印裁剪并调整到官方门户要求的精确像素、KB 大小和 DPI，文件不会上传服务器。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0780e99cffbd4b813fd3f583', 'en', 'DocPixelKB- Resize exact KB,pixels & DPI', 'Crop and resize your passport photo, signature, or thumb impression to the exact pixel dimensions, KB size, and DPI required by official portals. Your files stay on your device and are never uploaded to any server.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82db9d3bf7f654183992eead', 'zh-CN', 'Holiday Mitra 印度旅行套餐与朝圣游', '面向孟买和浦那的印度旅行套餐、精选酒店、目的地指引与朝圣游服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82db9d3bf7f654183992eead', 'en', 'Holiday Mitra', 'Trusted travel agency for tour packages from Mumbai & Pune. Curated hotel stays, destination guidance & pilgrimage tours across India.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_85086c016f50d7687b30133e', 'zh-CN', 'RoveLogics：智能排程与业务运营软件', '面向移动、固定及混合服务商的智能排程与业务运营软件，支持路线感知排程和日历智能预约。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_85086c016f50d7687b30133e', 'en', 'RoveLogics', 'Smart scheduling and business operations software for mobile, fixed-location, and hybrid service providers, with route-aware scheduling for travel and gap-aware Calendar Smart Booking for studio work.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd6b562e2dec38d8561459d6', 'zh-CN', 'Singari Tour & Travels 租车服务', '提供勒克瑙豪华轿车、Tempo Traveller 与巴士租赁预订，让旅途更舒适。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd6b562e2dec38d8561459d6', 'en', 'Singari Tour & Travels', 'Luxury car, Tempo Traveller, bus rental in Lucknow. Book now for comfortable journeys.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e5a4766b9062368faa388cb4', 'zh-CN', 'TripMazer：AI 旅行管家', 'AI 旅行管家，规划行程、监控航班、自动值机、酒店沟通与超支预警。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e5a4766b9062368faa388cb4', 'en', 'TripMazer', 'TripMazer is a travel OS, and Mazer is the AI agent that runs it. Tell it the trip, and it plans it, then keeps working: it checks you in on 32 airlines, watches your flights and replans the day, calls the hotel in their language, makes th…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1812f3331c061bbb47e3ae83', 'zh-CN', 'British Airways 航班改名政策指南', '介绍 British Airways 航班改名的规则、办理流程与相关费用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1812f3331c061bbb47e3ae83', 'en', 'airline-updates.com', 'Find out how to change your name on a flight, including the rules, process, and fees involved in British Airways name change policy.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f9a9a8a6d047283bea22d2f1', 'zh-CN', 'Plurel：社交分账与共享账单应用', 'Plurel 是社交分账应用，可扫描收据并按人分配项目，自动算清税费、小费与欠款，支持室友、旅行和聚餐群组余额及虚拟借记卡。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f9a9a8a6d047283bea22d2f1', 'en', 'Plurel', 'Plurel is a social finance app for splitting bills and receipts with friends, roommates and travel groups, so nobody has to front the whole tab.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3273a3e837be30e88b27b6ac', 'zh-CN', 'Travia：拼车与包裹捎带平台', '连接出行者的拼车与包裹配送平台，可共享行程、顺路携带物品', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3273a3e837be30e88b27b6ac', 'en', 'Travia: Rides, Parcels & More', '𝗧𝗿𝗮𝘃𝗶𝗮: 𝗥𝗶𝗱𝗲𝘀, 𝗣𝗮𝗿𝗰𝗲𝗹𝘀 & 𝗠𝗼𝗿𝗲 Travel • Trade • Repeat Looking for a carpooling app, affordable ride-sharing options, or a convenient way to send parcels?', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bc76bfa66ca4e79d499f8db5', 'zh-CN', 'MINERVA 教育机构 ERP', '面向学校与院校的一体化 ERP，覆盖招生到校友、考勤课表、考试收费、薪资图书交通宿舍及 NAAC 记录，含学生家长教职工应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bc76bfa66ca4e79d499f8db5', 'en', 'MINERVA ERP', 'MINERVA is an all-in-one ERP for schools, colleges, polytechnics and ITIs, built by Beebasoft in Chennai.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_55baa60d22b7ea0150c831ab', 'zh-CN', 'Hashsync：按接收端文件索引去重 SSH 数据流', '通过 SSH 运行命令时，将输出、输入与接收端文件索引比对去重，减少传输数据量。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_55baa60d22b7ea0150c831ab', 'en', 'Show HN: Hashsync – Deduplicate SSH streams against the receiver''s files', 'On a recent trip, while stuck on spotty hotel Wi-Fi and roaming 5G, I got fed up with how much bandwidth commands like rsync and nix-copy-closure waste. rsync&#x27;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60452e4aaca48fcac9f5d7ac', 'zh-CN', 'TheTripsites：旅行比价与 AI 行程规划', '聚合 500+ 供应商的机票、酒店、套餐与邮轮比价，提供 84 国目的地指南及 AI 行程规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60452e4aaca48fcac9f5d7ac', 'en', 'TheTripsites', 'TheTripsites: compare flights, hotels, packages & cruises from 500+ providers. 297 expert destination guides across 84 countries. AI trip planner included.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_44b1dee395ead2abea535449', 'zh-CN', 'Flymatch：多人多城航班路线匹配', 'Flymatch 帮你和好友选择出发机场，匹配可共同前往的直飞共享目的地。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_44b1dee395ead2abea535449', 'en', 'Flymatch', 'Multi-city group flight route matcher. Select departure airports for you and your friends, discover direct flights and shared destinations where everyone can travel together.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_75b40f44f82ed96ef301199d', 'zh-CN', 'TIMLAR：个人安全位置共享应用', '个人安全应用：外出、旅行或见陌生人时开启会话，信任的人通过链接实时查看你的位置，无需安装应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_75b40f44f82ed96ef301199d', 'en', 'TIMLAR', 'TIMLAR is a personal safety app. Start a session when you walk home, travel or meet someone new, and the people you trust follow along from a secure link. They don''t need an app. Your location is shared only while the session is open.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7f9d5cc3a7940d9752a48733', 'zh-CN', 'Radhika Holidays：德里出发3日金三角之旅', 'Radhika Holidays 提供从德里出发的3日金三角旅行套餐，游览德里、阿格拉和斋浦尔。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7f9d5cc3a7940d9752a48733', 'en', 'Radhika Holidays', 'India is a country filled with rich history, magnificent architecture, vibrant cultures, and unforgettable travel experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_903c0cea59e7a9300f542904', 'zh-CN', 'Pixshop：一张自拍生成 AI 头像', '只需一张手机自拍，一分钟内生成 LinkedIn、约会、创作者与旅行头像，基于 Gemini，免费试用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_903c0cea59e7a9300f542904', 'en', 'Pixshop', 'Most AI headshot tools need 10–20 photos and 30 minutes. Pixshop needs one selfie and under a minute. Get LinkedIn headshots, dating photos, creator content, travel portraits — all from a single phone selfie. Built on Gemini.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fe0622ed7a65659812eafd5f', 'zh-CN', '[开源自荐] Muralume：轻巧精致的 Mac 视频播放器与动态桌面', '免费开源的原生 Mac 视频播放器与动态桌面应用。可直接添加已有视频和文件夹，基于 AVFoundation 播放，界面以画面为中心，播放控制与可搜索媒体库以半透明面板呈现；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fe0622ed7a65659812eafd5f', 'en', 'Muralume: Lightweight Native Mac Video Player & Live Wallpaper', 'Free, open-source Mac video player and live wallpaper app. Add your own videos and folders; AVFoundation playback, translucent controls, searchable library, per-display sync, and auto-pause on battery. Apple silicon, macOS 14+.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a372d1f57596a166a6518635', 'zh-CN', 'AllWays：iPhone 一站式旅行规划应用', 'iPhone 一站式旅行规划应用，可制定逐日行程、记录预算支出、离线管理航班火车与预订文件并地图标记想去地点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a372d1f57596a166a6518635', 'en', 'AllWays', 'AllWays is the all-in-one travel planner app for iPhone. Build a day-by-day trip itinerary, track your travel budget and expenses, organize flights, trains and booking documents offline, and map every place you want to visit.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a54909650776faca09600877', 'zh-CN', 'NEXORA Tools：隐私优先的免费浏览器工具箱', 'NEXORA Tools 提供50+款浏览器内免费工具，涵盖视频压缩、文本转语音、测速、PDF、图片与护照照片制作，无需注册、无广告水印。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a54909650776faca09600877', 'en', 'NEXORA Tools', 'Tired of tool websites with 10 popups, email required & watermarks? I built NEXORA Tools - 50+ free tools that run 100% in your browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a594f7324be87a5bd3d7122c', 'zh-CN', 'Bean Stuff：按品质评分发现好咖啡店', '为每家咖啡店给出咖啡品质评分 Snob Score，可按品质筛选并过滤多数连锁店，帮你在旅途中随时找到值得一喝的咖啡。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a594f7324be87a5bd3d7122c', 'en', 'Bean Stuff', 'Bean Stuff helps you find quality coffee that is worth your time. It gives each coffee shop a Snob Score that reflects how good its coffee is, and you can filter by the quality you want.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_97e14e112f1e7bf558beb24f', 'zh-CN', 'Compi 旅行规划与协作', '借助 ChatGPT 或 Claude 规划旅行，在 Compi 管理每日行程、住宿、地图、打包清单和共享开支，可邀请同伴并离线查看。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_97e14e112f1e7bf558beb24f', 'en', 'Compi', 'Plan with ChatGPT or Claude, then take your trip along in Compi: daily plans, stays, maps, packing lists and shared expenses. Invite travel companions and read a loaded trip offline. Free drafts; full trip access is paid.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d717eab795c48406b4be3f1a', 'zh-CN', 'NearMiss Travel：附近地点提醒', '收藏餐厅或地点，当你再次路过附近时收到提醒，免费支持10个地点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d717eab795c48406b4be3f1a', 'en', 'NearMiss: Travel', 'Read about a great restaurant, then drove past it three times without remembering? NearMiss fixes that. Save any place - by name, address, or map pin - and get notified the next time you’re actually nearby. Free for 10 places;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ef7331c0a099ae18d9d7b512', 'zh-CN', 'Skip FM：全球直播电台', '按心情或自定义描述一键跳转到全球各地直播电台，免费免注册，支持4种语言。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ef7331c0a099ae18d9d7b512', 'en', 'Skip FM', 'Skip FM plays live radio from around the world. Tap a vibe (party, work, sleep, road trip…) or type your own, like “late night drive through tokyo”, then hit skip to land on a live station in another country.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc0d8a2397637445cf326d16', 'zh-CN', 'eSIM Grab：旅行 eSIM 套餐比价', '比较旅行 eSIM 套餐总价、每 GB 价格、流量与有效期，筛选套餐限制并估算多国行程流量需求；免费使用，结算在供应商处完成。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc0d8a2397637445cf326d16', 'en', 'eSIM Grab', 'Compare travel eSIM plans by total price, price per GB, data and validity. Filter plan restrictions, estimate your data needs and compare options for a multi-country trip. Free to use; checkout happens directly with the provider.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
