INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_dafb6da6709e86e258ca0721', 'zh-CN', 'Voltey：全球 eSIM 与 AI 旅行管家', '面向旅行者的全球 eSIM 服务，集成 AI 旅行管家与安全 VPN。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dafb6da6709e86e258ca0721', 'en', 'voltey.com', 'Global eSIM with AI Travel Concierge and Secure VPN Technology.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5869b8f73c511687cdf990db', 'zh-CN', 'GroupTripGo：皇家航空马拉喀什团体机票预订', 'GroupTripGo 支持最多 9 人团体预订皇家航空摩洛哥航空航班，并提供票价、行李与出行建议。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5869b8f73c511687cdf990db', 'en', 'Grouptripgo', 'Royal Air Maroc Group Travel lets you book flights for up to 9 passengers with ease. Get fare deals, baggage & travel tips with GroupTripGo.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3cff27e9ba079f257c978ecd', 'zh-CN', 'BeeSim 旅行 eSIM', '面向出境旅行者的 eSIM，覆盖 200+ 目的地，一分钟安装并接入当地 4G/5G 网络，避免漫游费。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3cff27e9ba079f257c978ecd', 'en', 'BeeSim', 'Mobile data abroad without roaming bills. Buy a travel eSIM for 200+ destinations, install it in a minute and get online on local 4G/5G networks.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a12eea643ffb5cc82fcb074', 'zh-CN', 'Romairo：AI 旅行规划助手', 'Romairo 是智能虚拟旅行伙伴，帮助更聪明地探索全球目的地、发现体验并轻松规划旅行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a12eea643ffb5cc82fcb074', 'en', 'Romairo: AI Travel Planner', '# Romairo – Your Virtual Travel Friend 🌍✈️ Travel isn’t just about reaching destinations — it’s about discovering experiences, creating memories, and exploring the world your way.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7fdf7da13ff87dc11b3bedc9', 'zh-CN', 'Yaitro：按预算与兴趣规划旅行行程', '按预算、日期和兴趣规划旅行，将推荐路线、住宿、餐饮和每日活动整合为带估算标注的行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7fdf7da13ff87dc11b3bedc9', 'en', 'Yaitro', 'Plan your trip around your budget, dates and interests. Bring suggested routes, stays, meals and daily activities into one itinerary, with clearly labelled estimates.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7d12da1304ebab859b768c43', 'zh-CN', 'FredSpeak：英语口语练习', 'AI 英语学习工具，提供发音反馈、听力、语法练习与进度跟踪。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7d12da1304ebab859b768c43', 'en', 'FredSpeak - Speak English', 'You know the English rule. Now put it into practice. 👋 FredSpeak helps you build confidence with: 🎙️ AI-powered pronunciation feedback 🎧 Listening exercises with transcripts 🧩 Short grammar lessons and quizzes 🌍 English for travel, wo…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_813e6f4dda33bb3f4d2c514d', 'zh-CN', '免费抽奖：赢取1000美元随心花', '面向7个国家读者的免费抽奖活动，中奖者可获1000美元礼品卡，购物、旅行、就餐或储蓄用途自选。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_813e6f4dda33bb3f4d2c514d', 'en', 'Win $1,000 to Spend Your Way: Free', 'Shop, travel, eat out or save it. The winner chooses how to use the $1,000 gift card. Free to enter for readers in 7 countries.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_84aac79a6a32118510560a0b', 'zh-CN', 'Wander Around World：发现身边好去处', '一键发现身边景点、美食、公园和拍照点，附照片、地图与地点故事。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_84aac79a6a32118510560a0b', 'en', 'Wander Around World', 'Travelling somewhere new? Tap once to see the sights, food, parks and photo spots around you, with photos, a map and the story behind each place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8a4eefe67a47e2af7eab30cf', 'zh-CN', '圣地亚哥超跑租赁', '圣地亚哥提供法拉利、兰博基尼、劳斯莱斯及保时捷租赁，可当日送至酒店或机场，750美元/天起。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8a4eefe67a47e2af7eab30cf', 'en', 'Exotic Car Rental San Diego', 'Rent a Ferrari, Lamborghini, Rolls-Royce, or Porsche in San Diego. Same-day delivery to your hotel or SAN Airport. From $750/day — call now.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a80e82b387a49f54a91a8360', 'zh-CN', 'winrooms：孟加拉酒店预订平台', '面向孟加拉国的在线酒店预订平台，提供透明房价、精选住宿和快捷预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a80e82b387a49f54a91a8360', 'en', 'winrooms', 'Planning a staycation or travel in Bangladesh? winrooms is an online hotel booking platform designed to simplify how you find and book accommodations across the country.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df8780a51de79eb0131ee9ab', 'zh-CN', 'PingDial：智能拨号与通话状态', '智能拨号应用，通话前先 Ping 对方查看当前通话状态与可联系时间，减少盲目来电。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df8780a51de79eb0131ee9ab', 'en', 'PingDial: Smart Dialer', 'PingDial – Smart Dialer & Call Status PingDianetl is a smart dialer and calling app that helps you communicate at the right time. Before making a call, check a person''s current call status, Ping them first, and then decide whether to call.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f8eeb5996c32f42093c4ea19', 'zh-CN', '免费照片拼图生成器', '用任意照片在浏览器中生成拼图，可调难度、计时并记录最佳成绩，免费免注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f8eeb5996c32f42093c4ea19', 'en', 'Free Jigsaw Puzzle Creator: Any Photo', 'Turn your own photos into jigsaw puzzles, right in your browser. Upload any image, like a family photo, a pet or a travel shot, or pick a sample image. Set the difficulty and start.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_022c47cd4c2d5e6a6b338687', 'zh-CN', 'UbidTours：个性化旅行套餐与游览', '提供个性化旅行套餐和短途游览，帮助发现独特旅行体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_022c47cd4c2d5e6a6b338687', 'en', 'UbidTours', 'Discover unique travel experiences with personalized packages and excursions', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ac75048622e061a76db635c', 'zh-CN', 'TAXİNİ 同向拼出租车', '同向乘客拼乘正规出租车并分摊车费，支持性别筛选、境外模式、评分聊天和预约行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ac75048622e061a76db635c', 'en', 'taxini', 'TAXİNİ matches passengers traveling in the same direction to share a licensed taxi and split the fare. You''re already taking a taxi — TAXİNİ finds someone going the same way. No surge pricing.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0c8764eac85a6723a5da85e4', 'zh-CN', 'Places To Try：值得一试的地点', '发现共享地图、美食与旅行挑战，以及值得一试的地点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0c8764eac85a6723a5da85e4', 'en', 'Places To Try', 'Discover shared maps, food and travel challenges, and places worth trying.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f9c22e6db2c92da19bb927e5', 'zh-CN', 'Comitiva：朋友群组旅行规划器', '面向朋友的群组旅行规划工具，集中共享行程与预订，支持分账及 UPI 确认结算。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f9c22e6db2c92da19bb927e5', 'en', 'Comitiva', 'Group trip planner for friends: shared itinerary, bookings in one place, and expenses split to the paisa with UPI settle-ups confirmed by the recipient.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_14da040685729b6b2a3378d0', 'zh-CN', 'PointsGPT 积分机票搜索', '输入想乘坐的航班，搜索支持的航司奖励机票，并用你持有的 Amex、Chase、Capital One、Citi 或 Bilt 积分显示票价。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_14da040685729b6b2a3378d0', 'en', 'PointsGPT', 'Ask for the flight you want. We search supported airline award programs and show fares in the Amex, Chase, Capital One, Citi, or Bilt points you hold.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_18afa8a567744176350037de', 'zh-CN', 'Sooperfare：机票与酒店比价预订平台', '一站式比价并预订机票与酒店，覆盖商务、休闲及家庭出行需求。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_18afa8a567744176350037de', 'en', 'Sooperfare', 'Sooperfare helps travellers compare and book flights and hotels at competitive prices. Find travel options for your next trip through one convenient booking platform, whether you''re travelling for business, leisure or a family holiday.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_69b818b551b447f02be5c3e2', 'zh-CN', 'circubAwd：旅行本地价格助手', '旅行中查询本地真实价格，含 AI 扫描、问本地人、本地指南与行程预算规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_69b818b551b447f02be5c3e2', 'en', 'circubAwd', 'Know what things actually cost while you travel, from the locals. Real local prices, an AI price scanner, ask-a-local messaging, local guides, and a trip budget planner. Free, no app store needed.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_43503660a0fbb6373ae4e918', 'zh-CN', 'Outrouted：一站式国际旅行规划地图', '在一张地图上规划国际旅行，自动排序目的地、分配住宿晚数、计算行程与预估费用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_43503660a0fbb6373ae4e918', 'en', 'Outrouted', 'Plan an international trip on one map. Outrouted orders your destinations, splits the nights, works out the travel between them and estimates the cost.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c7de8a79648f285d098800b', 'zh-CN', '免费抽奖赢900美元礼品卡', '免费参与，赢取900美元礼品卡，可自由用于购物、旅行、餐饮或储蓄；活动截止2026年10月31日。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c7de8a79648f285d098800b', 'en', 'Win $900 to Spend Your Way: Free 7', 'Shop, travel, eat out or save it. The winner chooses how to use the $900 gift card. Free to enter. Ends October 31, 2026.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3198a59f27bf14a8d67f2f22', 'zh-CN', 'Venus 酒店管理软件', '面向酒店和短租的一体化管理系统，可在网页端管理运营，并通过移动端查看收入、报表、预订和提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3198a59f27bf14a8d67f2f22', 'en', 'Venus Hotel Management Software', 'Venus Hotel Management Software is an all-in-one solution for hotels and shortlets. Manage operations from the web and monitor revenue, reports, reservations, and alerts with the Venus Hotel Owner mobile app.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_821beaac322beb406c8fdff0', 'zh-CN', 'FlightCompensations：航班赔偿查询与代索赔', '查询延误、取消或超售航班是否符合 EU261 等赔偿规则，并代为向航司索赔，成功后才收 39 欧元。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_821beaac322beb406c8fdff0', 'en', 'FlightCompensations', 'Check any delayed, cancelled or overbooked flight in seconds and see if you''re owed compensation under EU261, UK261, Israel''s Aviation Services Law or Canada''s APPR. If you are, we file and run the claim with the airline for you.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a7d1e2cf47db497692558c96', 'zh-CN', 'Wherewhen：自动调整行程的旅行规划应用', 'Wherewhen 旅行规划应用支持设定停留时长、预约等约束，自动调整每日行程及各地点出发和到达时间，并计入交通耗时。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a7d1e2cf47db497692558c96', 'en', 'Show HN: I got tired of travel spreadsheets so I made a travel planner app', 'Hey everyone! I couldn&#x27;t find an app to organize trips that gave me all the info I wanted to schedule each stop per day, with travel times, leeway, etc, so I made Wherewhen.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a65ce75d28cdd80473368ff', 'zh-CN', 'AirlineAirportGuide 航空公司办事处指南', '全球航空公司办事处地址、联系方式与服务查询工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a65ce75d28cdd80473368ff', 'en', 'AirlineAirportGuide', 'Looking for an airline office? Search airline locations worldwide for office addresses, contact details, services, and other useful information.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
