INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_91ae527832cc8d74473972a7', 'zh-CN', 'ToolsRift 免费浏览器工具集', '1100+ 免费浏览器工具，PDF 与图片本地处理不上传，护照、签证和考试照片按官方规则生成，免注册无水印。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_91ae527832cc8d74473972a7', 'en', 'ToolsRift', 'ToolsRift is 1,100+ free browser tools. PDF and image tools run on your device, so files are never uploaded. Passport, visa and exam photo makers follow each government''s published rules, with sources. No sign-up, no watermark.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b8df718c1b88547553a041b4', 'zh-CN', '护照签证照片转换器', '在浏览器内制作符合各国规格的护照、签证与证件照，自动识别裁剪、替换背景并支持打印排版。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b8df718c1b88547553a041b4', 'en', 'Passport Size Photo Converter', 'Make passport, visa and ID photos that meet official size rules, for free. Pick a country and document, upload a phone photo, and it finds your face, crops to the exact spec and replaces the background.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_edc02f748d9b9e27745b51ee', 'zh-CN', 'SayLingo AI：AI 语言口语练习伙伴', '基于真实对话的 AI 语言口语练习平台，覆盖30种语言，实时反馈发音、语法与流利度。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_edc02f748d9b9e27745b51ee', 'en', 'SayLingo AI - Language Speaking Partner', 'SayLingo is an AI language learning platform built around real speaking practice. Practice conversations with AI tutors in 30 languages and regional varieties, receive instant feedback on pronunciation, grammar, and natural phrasing, and t…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2abc7e72eee0e62762c419a8', 'zh-CN', 'Lost Traveller：北印度豪华别墅与度假住宿', 'Lost Traveller 提供北印度豪华别墅与度假住宿，覆盖喜马偕尔邦、北阿坎德邦、克什米尔等风景地区。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2abc7e72eee0e62762c419a8', 'en', 'Luxury Villas & Stays in North India', 'Discover luxury villas and holiday stays across North India with Lost Traveller. Explore beautiful destinations in Himachal Pradesh, Uttarakhand, Kashmir, and other scenic regions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fc93fc0f5108a4a578f149d8', 'zh-CN', 'PrimeGuest：AI 原生酒店 PMS 平台', '面向独立酒店与度假租赁运营商的 AI 原生云端一体化 PMS，整合智能定价、预订引擎、渠道管理、GST 开票与客人应用', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fc93fc0f5108a4a578f149d8', 'en', 'PrimeGuest', 'Helping hotels automate routine work & run their operations seamlessly, optimize revenue & deliver a better guest experience through a single intelligent platform instead of several disconnected tools.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0eb1158d2e2fc62c5e1a4e04', 'zh-CN', 'Trvlrr：汇集你所有旅行的行程管理应用', '汇集所有旅行的应用：转发机票、火车、酒店等预订邮件即可归档到对应行程；保留历史行程并统计真实记录；照片按行程归档并支持内容搜索；可通过 MCP 让 AI 查询或添加行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0eb1158d2e2fc62c5e1a4e04', 'en', 'Show HN: I built Trvlrr, home for all your travels', 'Hi HN, I&#x27;m Sanjay. I&#x27;ve been travelling since I moved from Pakistan to Stockholm in 2008; I live in Sydney now.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2d4646d768067b74cdba2b79', 'zh-CN', 'Wheels Up 航班追踪器', 'Android 航班追踪器，覆盖全程：登机口变更、延误、换机提醒，前序航班晚点预警、中转评分及家人落地通知。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2d4646d768067b74cdba2b79', 'en', 'Wheels Up', 'A flight tracker for Android that watches your whole trip. Get alerts for gate changes, delays and plane swaps, a heads-up when the plane flying in is running late, layover ratings, and a ping when family land.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34d8b07d693b14b05d04b952', 'zh-CN', 'PreMed Toolkit：医学院申请工具集', '免费免注册的医学院申请规划工具集，覆盖申请费用、MCAT、面试出行、时间线与文书安排。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34d8b07d693b14b05d04b952', 'en', 'PreMed Toolkit', 'PreMed Toolkit is a set of free, no-account tools for students applying to medical school: a cost-to-apply calculator built on the published AMCAS, AACOMAS and TMDSAS fees (every fee shows its source and date), an AAMC Fee Assistance Progr…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_33fc4249cc3a27acf24cbaa6', 'zh-CN', 'JourneyCities：实用旅行决策平台', '独立无广告的旅行决策平台，可按月份、体感温度和旅行风格查气候地图、对比城市、查看街区指南，并生成可分享或打印的逐小时行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_33fc4249cc3a27acf24cbaa6', 'en', 'JourneyCities', 'Independent, ad-free travel platform built around practical decisions. Pick a month, temperature feel and trip style on our interactive When to Go climate map, compare up to three cities side by side, explore neighbourhood guides with tran…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_377c5469d2804296923714d5', 'zh-CN', 'Wait or Fly：医疗等待与海外治疗比价', '英国、加拿大、爱尔兰和美国的免费医疗比价工具：对比官方等待时间、本地自费价格与海外治疗价格，并计入机票和酒店预算。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_377c5469d2804296923714d5', 'en', 'Wait or Fly', 'A free comparison tool for readers in the UK, Canada, Ireland and US. Put official waiting-time figures and local self-pay prices beside published treatment prices abroad, then add your flight and hotel budget.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4fb17704bd1919d9c6d5073d', 'zh-CN', 'Trvlrr：私人旅行日记与行程规划', '面向 iPhone 与网页的私人旅行日记和行程规划工具，转发预订即可自动生成行程，并可按描述查找照片、回顾到访国家城市。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4fb17704bd1919d9c6d5073d', 'en', 'Trvlrr', 'Trvlrr is a private travel journal and trip planner for iPhone and the web. Forward a booking and the itinerary builds itself, on the right day in local time.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60718bb843965bbd55c08542', 'zh-CN', 'Ridalo：普吉岛旅行服务预订平台', '普吉岛踏板车租赁、机场接送、包车及当地游的在线比价与预订平台', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60718bb843965bbd55c08542', 'en', 'Ridalo', 'Ridalo is an online booking marketplace for scooter rentals, airport transfers, private drivers, tours and excursions in Phuket, Thailand. Compare scooter rental prices, explore local providers, and book your scooter online in Phuket.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f35a9071ddfd32003adb039', 'zh-CN', 'Points Frog：积分奖励与理财计算器', '比较奖励计划与积分估值、查找转点奖励，并提供旅行、房贷、退休及日常理财计算器。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f35a9071ddfd32003adb039', 'en', 'Points Frog', 'Explore rewards programs, compare points valuations, find transfer bonuses, and use free calculators for travel, mortgages, retirement, and everyday money decisions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_735ef6d8ab3e20abfcf89138', 'zh-CN', 'Lost Traveller：拉贾斯坦邦豪华别墅住宿', 'Lost Traveller 帮助旅客发现拉贾斯坦邦的豪华别墅与度假住宿，适合家庭、团体和休闲出行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_735ef6d8ab3e20abfcf89138', 'en', 'Luxury Villa Stays in Rajasthan', 'Lost Traveller helps travellers discover luxury villas and holiday stays across Rajasthan. Explore accommodation options for family vacations, group getaways, and relaxing escapes, with property details to help you plan your trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5725f2e4f0953f864ce02cf1', 'zh-CN', 'Laminate：乐队巡演管理平台', '面向乐队的巡演管理工具，把日程单、场地方对接、嘉宾名单、住宿、交通、周边与账务集中在一处，乐队、工作人员和场地方各看所需，全程在浏览器中运行并支持离线使用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5725f2e4f0953f864ce02cf1', 'en', 'Laminate', 'Tour management your band will actually open. Laminate keeps a tour in one place: day sheets, advances, guest lists, hotels, travel, merch and the money.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_75b683177d9a244db5023edf', 'zh-CN', 'ZipVoya 旅行规划助手', '一站式旅行规划应用，可管理每日行程、航班、预算、开支与旅行回忆，并与好友共享计划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_75b683177d9a244db5023edf', 'en', 'ZipVoya', 'Plan trips in one app: daily itineraries, flights, budgets, expenses, memories, and shared plans with friends. Free travel organizer for iOS and Android.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a94717e2b09078e5d4837947', 'zh-CN', 'CarbonTracker：隐私优先的健身碳足迹追踪应用', '开源隐私优先健身应用，记录步行、跑步、骑行路线，估算相较汽车和公交节省的碳排放。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a94717e2b09078e5d4837947', 'en', 'CarbonTracker', 'CarbonTracker is an open-source, privacy-first fitness app that helps you see the environmental impact of walking, running, and cycling.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_92ceb66e996519f0b316d7ef', 'zh-CN', 'GoMobility-Passenger 叫车应用', 'GoMobility-Passenger 提供摩托、自动三轮和出租车即时叫车，认证司机、行程分享与一键 SOS。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_92ceb66e996519f0b316d7ef', 'en', 'Go Mobility', 'GoMobility-Passenger - Your Reliable Ride, Anytime Anywhere Book a bike, auto, or cab in seconds and reach your destination safely and comfortably.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_68c12508dfee4b484c18e4bd', 'zh-CN', '赢取450美元任意消费抽奖', '参与抽奖赢取450美元礼品卡，可用于购物、餐饮、旅行或储蓄，面向7个国家，截止2026年10月31日。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_68c12508dfee4b484c18e4bd', 'en', 'Win $450 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner chooses how to spend the $450 gift card. Open to 7 countries. Ends October 31, 2026.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b077ba4bd4bdb544d4fd56ae', 'zh-CN', 'Trove：可搜索的链接收藏库', '把社交媒体与网页链接存入可搜索的收藏库，内置小程序让收藏用于健身记录、食谱烹饪与地点标注。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b077ba4bd4bdb544d4fd56ae', 'en', 'Trove', 'Save links from social media and the web in one searchable library. Trove’s built-in applets help you use what you save: follow and log workouts in Forge, cook from saved recipes, and put places on a map with PinPath.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d28e9fb89d57a78c8fade001', 'zh-CN', 'Global Travel Dashboard：全球旅行仪表盘', '汇集全球各国20类旅行信息、3D地球、AI与主题小游戏的旅行探索网站。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d28e9fb89d57a78c8fade001', 'en', 'Global Travel Dashboard', 'I built a website dedicated to professional world travel. The site contains every country in the world with 20 categories for each country, a 3D globe, integrated AI, themed mini-games, and much more, The project is still under heavy devel…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d5a8897bd67672735463c1cc', 'zh-CN', 'Maxesimo：全球 eSIM 与旅行数据计算器', '即时购买覆盖189+国家/地区的 eSIM，提供流量计算器与本地旅行指南，助你落地前选好套餐并避开游客罚款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d5a8897bd67672735463c1cc', 'en', 'Maxesimo', 'Buy eSIM for 189+ countries instantly. Maxesimo features an interactive Data Calculator to find your perfect plan size and deep-dive local travel guides to help you avoid tourist fines before you land.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e652a67a54bbc2c0c4e98063', 'zh-CN', 'FocusTrek 时间旅行番茄钟', '番茄专注计时器，每次完成专注即解锁一段历史事件、地理发现或未来展望，把深度学习变成探索之旅。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e652a67a54bbc2c0c4e98063', 'en', 'FocusTrek', 'Travel through time. One focus at a time. FocusTrek is not just another Pomodoro timer—it’s your personal time machine. Say goodbye to boring countdowns.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_057b07107573b4400a566b07', 'zh-CN', 'Locy：像本地人一样探索城市的旅行应用', '以本地人视角探索城市的旅行应用，提供海量图文指南、AI 生成的逐日行程、地图导览与同城旅友社交。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_057b07107573b4400a566b07', 'en', 'Locy', 'Locy is a travel app and website for seeing a city like a local. Browse photo-first guides for 11,000+ destinations, get a day-by-day AI plan built only from real places, follow it on the map on the day, and meet the travellers and locals…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee97a8bd07849069c1c8ee63', 'zh-CN', 'Pilely：用自带 AI 生成可上线的 Web 应用', '用你自带的 AI 描述需求，即可生成带登录、数据库、邮件和 Stripe 支付的可用 Web 应用并上线。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee97a8bd07849069c1c8ee63', 'en', 'Pilely', 'Bring your own AI. No coding needed: just describe the app you want to ChatGPT, Claude or any AI you already use, and it builds a real web app anyone can open at its own link.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
