DELETE FROM product_content WHERE product_id IN ('prd_0adc2fa58b06e3be506ca7aa','prd_e9b22e0db03b86cbbba8e808','prd_256ae672f136352897d7bd91','prd_16ed6abb958cc34fefef44e0','prd_65defa9325368fb3ba0fa25e','prd_82e3720144e1b2ccab3ac3df','prd_810231effd447d7d300e085c','prd_27cb8f97f60f151a7a85f8ca','prd_8509997bd592436a61a0b802','prd_962bc06afbb31f8b39b9283b','prd_9d14a7bd1bb018274e2bccb7','prd_49ba4be7d2f8e5ebb5451415','prd_a10f3434d89d51fdee2bce20','prd_9597a4d41710c90db69e4e1a','prd_a9b0092f882c17388a57e7df','prd_a1b7015dc0f000a4dd898b3d','prd_b7084220d8ca247306bf7ab8','prd_a27ee222681975187b776ed0','prd_c716f09f8b1eaa14d517755c','prd_cbd6d3ffb1444552174b7dfb','prd_cd3473658934d59eb8233fc1','prd_d4fa041d2d248bc7a634c310','prd_d7f46fd90ba089c970138357','prd_df2e6e2cfd71094656079961','prd_d3f58cc2c528a46c9890e8d4') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_0adc2fa58b06e3be506ca7aa', 'zh-CN', 'Bilbo：AI 旅行规划器', '输入目的地即可生成可按天编辑、贴合地图与营业时间的行程，并支持门票预订和旅行印章。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0adc2fa58b06e3be506ca7aa', 'en', 'Bilbo: The AI trip planner', 'Type a destination and Bilbo builds a complete day-by-day itinerary in minutes: sights, food, and hidden gems, arranged into days that actually make sense on a map and respect real opening hours, so you never show up to a closed museum.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e9b22e0db03b86cbbba8e808', 'zh-CN', 'GPS Map Camera：无广告地理标记相机', '无广告 GPS 相机，为照片添加坐标、实时地图、地址与时间戳，支持专业模板和 PDF 报告。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e9b22e0db03b86cbbba8e808', 'en', 'GPS Map Camera: Geotag & Stamp', 'A GPS camera with no ads, ever. Stamps GPS coordinates, a live map, address and timestamp on every photo. Built for site inspections, deliveries, real estate, field work and travel, with pro templates and PDF reports. iOS & Android.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_256ae672f136352897d7bd91', 'zh-CN', 'TailSpotter 飞机观察记录应用', '拍摄飞机并标记注册号发布，自动补充机型和航司，生成观察日志，查看头顶航班与飞机资料页。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_256ae672f136352897d7bd91', 'en', 'TailSpotter', 'Snap a plane, tag its registration and post it. TailSpotter fills in the aircraft type and airline, builds your logbook, shows what is flying overhead, and gives every tail and aircraft type its own page with photos, specs and sightings.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_16ed6abb958cc34fefef44e0', 'zh-CN', 'CapMoney 拍照 OCR 记账工具', '用手机拍摄收据、账单或手写记录，OCR 自动记账，支持照片附件、历史搜索及日常、旅行和商务支出统计。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_16ed6abb958cc34fefef44e0', 'en', 'CapMoney', 'CapMoney turns your camera into an expense tracker. Snap a receipt, bill or handwritten note, and OCR logs it for you. Attach photos to every entry, search your history, and track daily, travel or business spending. iOS & Android.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_65defa9325368fb3ba0fa25e', 'zh-CN', 'NovaRadix 浏览器工具集', '浏览器内免费处理 PDF、图片、发票、税务与贷款计算、二维码及 JSON 格式化，无需注册，文件不上传。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_65defa9325368fb3ba0fa25e', 'en', 'NovaRadix Technology', '101 free tools that run in your browser: merge, split and compress PDFs, resize photos and passport pictures, make GST invoices and salary slips, calculate EMI, SIP and income tax, create QR codes, and format JSON.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82e3720144e1b2ccab3ac3df', 'zh-CN', 'DaliCircle 宠物护理应用', '在一个地方集中管理宠物疫苗、用药和就诊提醒，保存健康档案与日记照片，数据存于本地', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82e3720144e1b2ccab3ac3df', 'en', 'DaliCircle', 'DaliCircle is a pet care app that keeps everything about your pets in one place. Track vaccinations, medications and vet visits with reminders, store health records and documents like insurance and adoption papers, and keep a journal and p…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_810231effd447d7d300e085c', 'zh-CN', 'Verda Cloud｜AI Infra 组内直招 Senior Devops', 'Verda Cloud AI Infra 团队直招 Senior DevOps，工作地点可在 EU 或 UK，支持远程，赫尔辛基 onsite 最佳，可提供芬兰专家签证；有字节、谷歌等大厂经验优先。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_810231effd447d7d300e085c', 'en', 'Verda Cloud AI Infra Hiring Senior DevOps', 'Verda Cloud''s AI Infra team is hiring a Senior DevOps engineer. Based in the EU or UK, remote work supported, Helsinki onsite preferred; Finnish specialist visa sponsorship available. Big-tech experience preferred.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_27cb8f97f60f151a7a85f8ca', 'zh-CN', 'JSK Photo Studio 护照照片制作工具', '按毫米规格制作护照照片，内置21国32种尺寸，可裁切、矫正扫描、调整KB并打印，本地处理不上传。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_27cb8f97f60f151a7a85f8ca', 'en', 'JSK Photo Studio', 'The passport photo spec is in millimetres, your printer works in pixels, and most tools hand back something that looks correct on screen and prints 2-3mm out — the one thing that gets an application rejected.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8509997bd592436a61a0b802', 'zh-CN', '【自荐】Paxa：泰语、英语、中文语音合成 API，附泰文票据 OCR 和中译泰', '自荐一个我们做的语音和语言 API：Paxa，来自曼谷的 Paxa Labs。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8509997bd592436a61a0b802', 'en', 'Paxa: Thai, English and Chinese TTS API with Thai Receipt OCR and Chinese-to-Thai Translation', 'Paxa Labs offers speech and language APIs with Thai, English and Chinese text-to-speech, plus Thai receipt OCR and Chinese-to-Thai translation.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_962bc06afbb31f8b39b9283b', 'zh-CN', 'Erase Background：本地 AI 一键抠图', '本地 AI 秒抠人物、宠物和商品，可换背景、制作证件照与商品图，支持批量处理，免费无水印。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_962bc06afbb31f8b39b9283b', 'en', 'Erase Background', 'Cut out people, pets and products in seconds – with no upload and no account. The AI runs on your own device, so it''s fast and private.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9d14a7bd1bb018274e2bccb7', 'zh-CN', 'MyPassPrint 在线护照照片制作工具', '在浏览器本地制作护照照片，自动人脸对齐、替换背景并排版成 300 DPI 4x6 英寸打印页。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9d14a7bd1bb018274e2bccb7', 'en', 'MyPassPrint Online Passport Photo Maker', 'CVS & Walgreens charge $21.99 for passport photos. MyPassPrint lets you do it for just $0.35! Automatic ICAO biometric face alignment & background replacement Instantly layouts photos into a 300 DPI 4x6" print sheet with cut lines 100% cli…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49ba4be7d2f8e5ebb5451415', 'zh-CN', 'resaw：把收藏内容变成行动', '将 Instagram、YouTube 等平台的收藏帖转为食谱清单、地图标记、观看指引与带提醒的训练计划，并支持聊天搜索。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49ba4be7d2f8e5ebb5451415', 'en', 'resaw: Organize Saved Posts', 'Turn saved posts into things you actually do. Stop hoarding saves you never open. Share any post, video or link to resaw from Instagram, YouTube, Facebook, WhatsApp, Telegram or the web.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a10f3434d89d51fdee2bce20', 'zh-CN', 'Vibes Plan Trip Planner：氛围旅行规划器', '按环境心理学挑选18种旅行氛围，依据光线、空间与人群生成疗愈行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a10f3434d89d51fdee2bce20', 'en', 'Vibes Plan Trip Planner', 'We don''t sell places. We sell vibes you can wear for a day. Vibes Plan is a trip planner that heals. 18 trending vibes curated with environmental psychology - light, space, crowd. Slow vibes for your soul. Fresh trends for your feed.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9597a4d41710c90db69e4e1a', 'zh-CN', 'Pastelinkers：资源发现与收藏', '多语言移动网页，发现旅行、烹饪与免费课程资源，查看公开推荐并私密保存链接。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9597a4d41710c90db69e4e1a', 'en', 'Pastelinkers', 'Rebuilt for mobile web: explore reviewed resources for travel, cooking and free courses, read public titles and recommendations in your language, and save useful links privately. Browse in English, Korean, Japanese and Simplified Chinese.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a9b0092f882c17388a57e7df', 'zh-CN', 'V-Visa：AI 在线签证申请平台', 'AI 驱动的在线签证申请平台，支持阿联酋、加拿大、德国、新加坡等 50 多个国家的签证办理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a9b0092f882c17388a57e7df', 'en', 'V-Visa', 'India''s AI-powered visa application platform. Apply for UAE, Canada, Germany, Singapore & 50+ country visas online.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a1b7015dc0f000a4dd898b3d', 'zh-CN', 'ELK Connect 通信应用', '面向非洲、侨民和旅客的通信应用，可快速获取加拿大、美国、英国等真实号码，按分钟通话、应用内收验证码并购买旅行 eSIM，用移动钱包或加密货币充值。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a1b7015dc0f000a4dd898b3d', 'en', 'ELK Connect', 'ELK Connect is a telecom app for Africa, the diaspora and travellers. Get a real number in Canada, the US, the UK and more in seconds, call any phone by the minute with the rate shown before it rings, receive verification SMS in the app, a…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b7084220d8ca247306bf7ab8', 'zh-CN', 'eltravo：免费 AI 旅行规划器', '免费 AI 旅行规划器，生成含地图、费用和可预订项目的个性化逐日行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b7084220d8ca247306bf7ab8', 'en', 'eltravo', 'Free AI travel planner that builds a personalised day-by-day itinerary with maps, costs and bookable tours.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a27ee222681975187b776ed0', 'zh-CN', 'Staylist World：酒店差评速查', '免费查询酒店近24个月1–2星差评占比与主要投诉点，也可接入ChatGPT或Claude直接提问。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a27ee222681975187b776ed0', 'en', 'Staylist World', 'Free hotel bad-review checker for you and your AI. Type any hotel to see how many of its reviews from the last 24 months were 1–2 star and what guests complain about most. Or set up ChatGPT or Claude once and just ask about any hotel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c716f09f8b1eaa14d517755c', 'zh-CN', 'Fizzzo Travel：用自然语言找酒店', '用自然语言描述出行需求，AI 按体验匹配酒店，并显示含税总价与免费取消标签。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c716f09f8b1eaa14d517755c', 'en', 'Fizzzo Travel', 'Hotel sites make you tick 30 filter boxes and still miss what you actually want. Fizzzo flips it: describe your trip in plain words ("quiet beach hotel in Portugal, great breakfast, under €150") and AI matches rooms to the feeling, not jus…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cbd6d3ffb1444552174b7dfb', 'zh-CN', 'The Luxury Cab：纽瓦克机场豪华轿车接送指南', '介绍纽瓦克机场A、B、C航站楼的豪华轿车下客、接客区域及机场通行贴士。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cbd6d3ffb1444552174b7dfb', 'en', 'The Luxury Cab', 'Plan your limo service to Newark Airport with this guide to Terminal A, B and C drop-offs, pickup areas, airport access and travel tips.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cd3473658934d59eb8233fc1', 'zh-CN', 'ChronoSpeak：沉浸式历史角色扮演语言学习', '通过历史角色扮演学语言，在唐长安、宋汴京、明苏州及镰仓、京都、江户与当地人真实对话。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cd3473658934d59eb8233fc1', 'en', 'ChronoSpeak', 'ChronoSpeak is immersive historical role-play language learning. Travel to Tang Chang''an, Song Bianjing and Ming Suzhou, or to Kamakura, Kyoto and Edo, and hold a real conversation with the people who lived there.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d4fa041d2d248bc7a634c310', 'zh-CN', 'LowKey 免费语言练习社区', '免费语言练习社区，浏览器内即可加入 30 多种语言的实时语音视频房间，按话题和水平筛选，无需下载注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d4fa041d2d248bc7a634c310', 'en', 'LowKey', 'LowKey is a free language practice community. Join live voice & video rooms in 30+ languages, filtered by topic and level, right in your browser — no downloads, no fees, no signup needed to join a public room as a guest.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7f46fd90ba089c970138357', 'zh-CN', 'TuFit：AI拍照识别营养标签的iOS卡路里追踪器', 'iOS卡路里追踪应用，可拍照识别任意营养标签并由AI读取热量、蛋白质、碳水和脂肪，支持条码扫描、Apple Health同步与购物清单。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7f46fd90ba089c970138357', 'en', 'TuFit', 'TuFit is the iOS calorie tracker that finally ends the “barcode not found” problem. Take a photo of any nutrition label - even in foreign languages. The AI instantly reads the calories, protein, carbohydrates and fat. No manual entry.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df2e6e2cfd71094656079961', 'zh-CN', '飞飞掼蛋', '飞飞掼蛋是一款免费的网页版掼蛋牌桌游戏，支持一至四人开局，缺位由电脑补齐。可提前缓存离线资源，在飞机、地下室等无网环境游玩；有网时扫码加入在线对局，或连同一 Wi-Fi 使用「附近离线」。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df2e6e2cfd71094656079961', 'en', 'Feifei Guandan', 'Feifei Guandan is a free browser-based Guandan card game for 1-4 players, with AI fill-ins, cached offline play, online or same-Wi-Fi multiplayer, tribute rules, hints, voice prompts, and 8-32 player team tournaments.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d3f58cc2c528a46c9890e8d4', 'zh-CN', 'TripYara：离线旅行规划与行程整理', 'TripYara 是面向印度公路旅行和周末出游的行程规划应用，可整理逐日行程与旅行细节。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d3f58cc2c528a46c9890e8d4', 'en', 'TripYara–Plan, Travel, Offline', 'Plan smarter, travel better with TripYara — your travel planning app for road trips, weekend getaways, and adventures across India.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
