DELETE FROM product_content WHERE product_id IN ('prd_1d36061b8d93ca1925d96bfa','prd_f0956997d737d871fb425b94','prd_0e11a6e8cf0808de4d850a9c','prd_5b10a2d1b2ff46888e81fb99','prd_afb3d175c73291cd37eb6d6d','prd_ae318ffc9f79ab3089ee11e2','prd_c135cd8729568f3eab8a8b55','prd_c18b7e2cad5aa07a5ee11a5f','prd_b942d1ac0c87eee275e2c306','prd_c30c54775803c9feb2478986','prd_d2703b6d6c27c4909e5d41b4','prd_cbc42d9e98a5a7f15fcedb28','prd_e1d0d76af2154edb50a10e4e','prd_d952b01652070d3a94be25fe','prd_e43edad68f8a2a56d8151075','prd_ee0c1f6ed44c156db04834ec','prd_26a3e6cb35906284ed1c2e77','prd_1baa3debfee3d10ef57c5d21','prd_e2993b2217e0293178bc417a','prd_55548b888606c0f9ea9efbe5','prd_a90dfda304d209f6da659c5e','prd_af36ef2bb78d5c76b1455837','prd_2cdabb785a89de6c1897f626','prd_ca15f15d7968461a212c0594','prd_d52db6bfeec0b1207aa31938') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_1d36061b8d93ca1925d96bfa', 'zh-CN', 'Guidese：真实旅行指南', '提供70多个国家的真实每日预算、门票和最佳旅行时间，并配有免费行程规划工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1d36061b8d93ca1925d96bfa', 'en', 'Guidese', 'Plan real trips with confidence. Short description (160 chars): Honest travel guides with real daily budgets, entrance fees and best times to visit for 70+ countries. Free trip planner, no guesswork.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0956997d737d871fb425b94', 'zh-CN', 'FlipTrip 旅行规划', '分享链接收集朋友推荐的地点，结合自己的想法，在地图上整理成可分享的逐日行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0956997d737d871fb425b94', 'en', 'FlipTrip', 'Planning a trip? Share a link for friends to recommend places. Combine their tips with your own ideas and discover more spots, then organize everything into a day-by-day itinerary on a map you can share.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0e11a6e8cf0808de4d850a9c', 'zh-CN', 'SLEX 通行费计算器', '查询 SLEX 通行费、探索路线并预估出行成本的工具，帮助司机出发前规划更省心的行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0e11a6e8cf0808de4d850a9c', 'en', 'SLEX Toll Fee Calculator', 'SlexTollFee helps drivers check toll fees, explore routes, and estimate travel costs before starting their journey. Plan smarter trips with useful toll and route information in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5b10a2d1b2ff46888e81fb99', 'zh-CN', '免费赢取 350 美元通用礼品卡抽奖', '免费参与抽奖，赢家可获得 350 美元礼品卡，购物、餐饮、旅行或储蓄均可自由支配，10 月 31 日截止。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5b10a2d1b2ff46888e81fb99', 'en', 'Win $350 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner decides how to spend the $350 gift card. Enter free before the giveaway ends October 31.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_afb3d175c73291cd37eb6d6d', 'zh-CN', 'Wonderlist 旅行预订平台', '巴基斯坦旅行市场，可比较 Umrah 及 Hunza、Skardu 等地行程与真实人均价格，发布定制需求并与旅行社沟通预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_afb3d175c73291cd37eb6d6d', 'en', 'Wonderlist', 'Wonderlist is a travel marketplace for Pakistan. Compare Umrah packages and tours to Hunza, Skardu, Naran and abroad from verified local travel agencies, each with hotels, a day-by-day itinerary and the real price per person.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae318ffc9f79ab3089ee11e2', 'zh-CN', 'Red Sea Portal：红海旅行指南', '面向埃及红海的旅行软件，可探索地点、比较酒店并获取一日游灵感，提供网站和移动应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae318ffc9f79ab3089ee11e2', 'en', 'Red Sea Portal', 'Red Sea Portal is travel software for Egypt’s Red Sea. Explore places, compare hotels, and browse ideas for a day out. Try the live website or mobile apps, whether you’re planning a trip or just curious.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c135cd8729568f3eab8a8b55', 'zh-CN', 'Globebug：一体化旅行规划平台', 'Globebug 是一体化旅行平台，可收藏旅行灵感、规划多目的地行程与预算，用 Trip Pulse 掌握节奏；桌面规划、iOS 导航，照片按行程自动整理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c135cd8729568f3eab8a8b55', 'en', 'Globebug', 'Globebug is a connected travel platform that brings the entire journey into one place. Save travel inspirations, build detailed multi-destination itineraries, organize activities, routes and budgets, and understand your trip''s pacing with…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c18b7e2cad5aa07a5ee11a5f', 'zh-CN', 'BoaVoyage.ai：社区自驾游行程规划', '免费规划自驾游，基于社区分享的行程自定义停靠点、旅行建议和住宿，并展示在路线地图上。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c18b7e2cad5aa07a5ee11a5f', 'en', 'BoaVoyage.ai', 'Plan your road trip for free and customize itineraries shared by the community: stops, traveller tips and accommodation on a route map.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b942d1ac0c87eee275e2c306', 'zh-CN', 'Magula 航班追踪器', '实时动态航班追踪，展示航班飞行轨迹与动画。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b942d1ac0c87eee275e2c306', 'en', 'Magula Flight Tracker', 'Real-time animated flight tracking built with Django and Solid.js. Have questions, feedback, or custom inquiries? Send a message below!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c30c54775803c9feb2478986', 'zh-CN', 'HOSCover 酒店增收与客人互动平台', '面向酒店的增收与客人互动平台，识别升级销售机会、推送适时优惠并追踪转化，将会员关系变为可衡量收入。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c30c54775803c9feb2478986', 'en', 'Hoscover', 'Hospitality revenue and guest-engagement platform for hotels, developed by Jurya Technologies Limited. HOSCover helps hotels identify upselling opportunities, send timely guest offers, and track which offers turn into sales.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d2703b6d6c27c4909e5d41b4', 'zh-CN', 'Travel Game：旅行足迹世界', '记录每次旅行中的美食、文化、自然与观光，并生成含国家、地区、地图、评分和回忆的专属旅行世界。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d2703b6d6c27c4909e5d41b4', 'en', 'Travel Game', 'Travel Game helps you collect what you actually did on each trip — food, culture, nature, sightseeing and more — then turn it into your own Travel World with countries, regions, maps, scores and memories.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cbc42d9e98a5a7f15fcedb28', 'zh-CN', 'Discover Guinea：探索几内亚', '免费在线游戏，用互动地图、GuineaGuessr、测验和拼图了解几内亚的10个大区、44个省、文化与历史旅游。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cbc42d9e98a5a7f15fcedb28', 'en', 'Discover Guinea', 'Free online games to discover Guinea, West Africa: interactive map, GuineaGuessr, quizzes and puzzles on its 10 regions, 44 prefectures, culture, history and tourism. For students, teachers, the diaspora and anyone curious about Africa.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e1d0d76af2154edb50a10e4e', 'zh-CN', 'YEON：首尔与釜山本地人指南', '面向游客的首尔与釜山免费指南，推荐韩国人常去的餐厅，并提供厕所、展览快闪和营业时间信息。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e1d0d76af2154edb50a10e4e', 'en', 'YEON', 'I''m a Korean developer and I built this alone. YEON is a free guide to Seoul and Busan built around the places Koreans actually go to eat, not the usual tourist lists.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d952b01652070d3a94be25fe', 'zh-CN', 'HoldFree 旅行押金虚拟卡', '为旅行押金生成安全虚拟 Visa 卡，商户可正常预授权，且不影响真实现金与信用卡额度。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d952b01652070d3a94be25fe', 'en', 'HoldFree', 'HoldFree generates a secure virtual Visa card for travel deposits. Keep your real cash and credit card limits completely untouched while merchants authorize holds normally.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e43edad68f8a2a56d8151075', 'zh-CN', 'SHREE JI TRAVELS：印度 Tempo Traveller 租车预订', '印度各地 Tempo Traveller 在线租赁预订，提供 7–26 座及 Force Urbania 车型与认证司机。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e43edad68f8a2a56d8151075', 'en', 'SHREE JI TRAVELS', 'Tempo Traveller on Rent, Hire & Online Booking across India starting @ ₹28/KM. Luxury 7 to 26 Seater & Force Urbania with verified chauffeurs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee0c1f6ed44c156db04834ec', 'zh-CN', 'Tripminder 智能旅行伴侣', '智能旅行伴侣，提供行程检测、物品提醒、实时共享与旅行日志。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee0c1f6ed44c156db04834ec', 'en', 'Tripminder', 'Tripminder is an smartphone travel companion for planned trips, commutes and everyday journeys. It combines smart trip detection, essential-item reminders, live sharing and trip journals in one calm place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_26a3e6cb35906284ed1c2e77', 'zh-CN', 'Turvia：土耳其旅行路线指南', 'Turvia 是土耳其数字旅行指南，为游客和家庭提供精选路线与旅行建议。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_26a3e6cb35906284ed1c2e77', 'en', 'Turvia: Travel, Route & Tour', 'Turvia: Your Travel Assistant in Turkey Ready to explore the unique beauties of Turkey? Turvia is your next-generation digital travel guide, designed to turn your trip into an unforgettable experience.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1baa3debfee3d10ef57c5d21', 'zh-CN', 'TripoWay：签证旅行记录生成工具', '将旧登机牌、订票邮件和护照印章整理成签证申请可用的旅行记录 PDF，并支持申根 90/180 天停留计算。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1baa3debfee3d10ef57c5d21', 'en', 'TripoWay', 'TripoWay turns old boarding passes, booking emails, and passport stamps into embassy-ready travel logs. Snap a photo or upload a pass—our AI extracts flight dates, ports, and duration of stay.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2993b2217e0293178bc417a', 'zh-CN', 'SMRTROOM 小型酒店管理软件', '面向小型酒店和民宿的房态日历与预订管理，防超订，含发票、清洁、报表及 MCP 接口。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2993b2217e0293178bc417a', 'en', 'SMRTROOM', 'Hotel software for small hotels, guesthouses and apartments. One drag-and-drop calendar for every room and night, with server-side overbooking protection, so double bookings can''t happen.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_55548b888606c0f9ea9efbe5', 'zh-CN', 'London Tourist Map：伦敦旅游互动地图', '免费互动地图，汇集伦敦400多个景点和38个小众去处，可按心情筛选并查看开放时间、票价、游览时长及步行路线。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_55548b888606c0f9ea9efbe5', 'en', 'London Tourist Map', 'London Tourist Map puts 400+ London attractions and 38 hand-picked hidden gems on one free, interactive map.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a90dfda304d209f6da659c5e', 'zh-CN', 'Wingmates：飞行员成长一站式平台', '汇集飞行员培训指南、DGCA模拟考试、航校数据、飞行天气分析与航司选拔经验的一站式平台。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a90dfda304d209f6da659c5e', 'en', 'Wingmates', 'Wingmates brings the pilot journey into one place: verified aviation guides, DGCA mock tests, flying-school data, 10-year flying-weather analysis, pilot answers, stories and real airline selection debriefs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_af36ef2bb78d5c76b1455837', 'zh-CN', 'onesim：多国通用旅行 eSIM', '一款可重复使用的旅行 eSIM 应用，覆盖195+目的地，行前选购套餐即可使用，无需每次重装或扫码，支持购买、设置、用量查询和充值。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_af36ef2bb78d5c76b1455837', 'en', 'onesim', 'onesim is a mobile app that gives you one eSIM for every destination. Install it once and keep it: before each trip, pick a package for any of 195+ destinations and it goes onto the same eSIM, so there''s no new install or QR code every tim…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2cdabb785a89de6c1897f626', 'zh-CN', '赢取500美元自由消费礼品卡抽奖', '免费参与，赢取500美元礼品卡，可用于购物、餐饮、旅行或储蓄，10月31日截止。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2cdabb785a89de6c1897f626', 'en', 'Win $500 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner decides how to spend the $500 gift card. Enter free before the giveaway ends October 31.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ca15f15d7968461a212c0594', 'zh-CN', 'Wanderfox AI 旅行行程规划', '一句话生成按天排程的真实地点旅行行程，支持好友投票改行程、分摊费用，并可比较目的地或套用创作者行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ca15f15d7968461a212c0594', 'en', 'Wanderfox AI', 'Describe a trip in one sentence and get a day-by-day itinerary of real places, mapped and timed. Plan with friends: propose changes, vote and split costs. Compare destinations, or start from a creator''s ready-made itinerary. Free to start.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d52db6bfeec0b1207aa31938', 'zh-CN', 'Tripvenir：旅行照片地图册', '点选去过的地区并配上照片，填充该地真实轮廓，构建覆盖230个国家的照片地图，还能生成旅行书并分享；照片仅存本机。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d52db6bfeec0b1207aa31938', 'en', 'tripvenir', 'Tap a region you''ve been to, pick a photo, and it fills the real outline of that place. Build a photo map across 230 countries (106 with region maps), turn each country into a travel book, and share it. Photos stay on your phone.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
