DELETE FROM product_content WHERE product_id IN ('prd_d56d874d54172ad0ce2c171d','prd_dc3e62c8a3d24be32f7a65a5','prd_f579fb2a0c051bf70e78c70b','prd_dcfdb9843a75bcda2f6f3bb9','prd_d0bba827cb5653dec1c116c4','prd_360838956d2750427e9d7707','prd_3b9f701fc0023398a80e3e99','prd_3f9ad2c0d14d1c1cdb995883','prd_31b30a0b891a3bc29ac64eff','prd_6a6e324090887cae7057b040','prd_846e865239c26bfbd403de87','prd_9a3ca60140630a7e1daf36a5','prd_9a4ea393743c2dacd471f61f','prd_a69bace99ae40058fd120954','prd_17c45355e2590f15dc2bfb12','prd_653175ec6041fe3a316bcfd3','prd_9e2458c2d25663d4293726c1','prd_8143883ed126d3cea136d64d','prd_8c5c5f6781e8ecd63724e14a','prd_fd012fcafff52a7a4cf00c71','prd_fbef685b74d026febc48e026','prd_7e97996205f2583dfd4aa0e4','prd_6d8e93d6fc395c824663f532','prd_2cd73474d435fcf9b51f6f7b','prd_a547f8eb7e66f87012d3600e') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_d56d874d54172ad0ce2c171d', 'zh-CN', 'NothingMaps：极简地图与地点探索', '基于 Kotlin 的极简地图与位置探索应用，可发现地点、路线和附近兴趣点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d56d874d54172ad0ce2c171d', 'en', 'NothingMaps', 'A minimalist Kotlin-based map and location explorer for discovering places, routes, and nearby points of interest. #Kotlin #Android #Maps #Navigation #Location #Travel #OpenSource - SutharShantanu/...', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc3e62c8a3d24be32f7a65a5', 'zh-CN', '班加罗尔 Mr n Mrs Pet 狗狗寄养旅馆', '班加罗尔狗狗寄养服务，提供每日喂食、如厕、梳毛、基础看护和舒适床铺，起价₹599。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc3e62c8a3d24be32f7a65a5', 'en', 'Dog Hostel in Bangalore', 'Book Trusted Dog Hostel in Bangalore with Mr n Mrs Pet! We offer safe and homely care for your furry friend at the starting price of ₹599. It includes daily feeding, potty breaks, brushing, basic supervision, and cozy bedding.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f579fb2a0c051bf70e78c70b', 'zh-CN', 'TripSignal：加拿大全包旅行降价提醒', '监控加拿大全包旅行网站价格，设置机场、目的地、日期和预算，匹配套餐降价时邮件提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f579fb2a0c051bf70e78c70b', 'en', 'TripSignal', 'TripSignal watches Canadian all-inclusive travel sites so you don''t have to. Set your airports, destinations, dates, and budget once - we track live pricing and email you when a matching package drops in price.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dcfdb9843a75bcda2f6f3bb9', 'zh-CN', 'Selected Türkiye 旅行指南', '探索 Çeşme 和 Alaçatı 的餐厅、酒店、海滩与游玩项目，按区域和类别浏览地图及实用旅行指南。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dcfdb9843a75bcda2f6f3bb9', 'en', 'Selected Türkiye', 'Discover restaurants, hotels, beaches and things to do in Çeşme and Alaçatı. Browse places by area and category, explore them on a map and read practical travel guides.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d0bba827cb5653dec1c116c4', 'zh-CN', 'BinaSmart：埃塞俄比亚本地生活服务应用', '面向埃塞俄比亚的一站式阿姆哈拉语应用，提供打车、酒店、电视影视、招标招聘及证件税务指南，并内置 AI 助手 Bini。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d0bba827cb5653dec1c116c4', 'en', 'BinaSmart', 'BinaSmart puts everyday Ethiopian services in one Amharic-first app: fixed-price rides and airport transfers in Addis Ababa, commission-free hotel booking, live Ethiopian TV and films, open tenders and jobs, and step-by-step guides for pas…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_360838956d2750427e9d7707', 'zh-CN', 'Business Empire：温馨3D经营游戏', '一款无需下载注册的温馨3D经营游戏，在浏览器中经营咖啡馆、停车场和酒店。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_360838956d2750427e9d7707', 'en', 'Business Empire', 'A cozy 3D tycoon game that runs right in your browser – no download, no sign-up. Open a small neighborhood café, hire baristas and waiters, keep the shelves stocked and serve the morning rush.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3b9f701fc0023398a80e3e99', 'zh-CN', 'Herwave：女性专属旅行社交应用', '印度女性专属应用，认证女性可找旅伴、拼车及参加女性聚会，Android 免费。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3b9f701fc0023398a80e3e99', 'en', 'Herwave - Women Only Travel', 'Herwave is a women-only app in India where every member is a verified woman. Find travel buddies near you, share women-only carpools on your commute and join women-only house parties and meetups. Free on Android.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3f9ad2c0d14d1c1cdb995883', 'zh-CN', 'Stayelier 酒店运营与预订系统', '面向酒店运营的物业管理系统，并提供酒店品牌化的客人预订体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3f9ad2c0d14d1c1cdb995883', 'en', 'Stayelier', 'A property management system for hotel operations and a hotel-branded guest booking experience.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_31b30a0b891a3bc29ac64eff', 'zh-CN', 'LibvTalk：离线 P2P 网状通信应用', '离线 P2P 网状通信应用，支持语音通话、即时消息和应急连接，无需蜂窝网络或互联网。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_31b30a0b891a3bc29ac64eff', 'en', 'LibvTalk', 'LibvTalk is an advanced offline Peer-to-Peer (P2P) mesh communication application designed for seamless voice calls, instant messaging, and emergency connectivity without needing cellular coverage or an active internet connection.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a6e324090887cae7057b040', 'zh-CN', 'Holiday Package 旅行套餐', '提供适合各种预算的国际旅行套餐，并附签证协助和护照更新服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a6e324090887cae7057b040', 'en', 'Holiday Package', 'Holiday Packages is a team of travel enthusiasts who make international travel convenient with affordable travel packages for every budget.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_846e865239c26bfbd403de87', 'zh-CN', 'eSIM Indexer：旅行 eSIM 比价引擎', '免费旅行 eSIM 比价引擎，聚合多家供应商套餐，用筛选与最佳匹配快速比较价格、流量、有效期和覆盖。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_846e865239c26bfbd403de87', 'en', 'eSIM Indexer', 'eSIM Indexer is a free travel eSIM comparison enginethat helps travellers find the right plan faster. Copare thousands of eSIM offers from multiple provider using advanced filters, Best Match rankings and cler network information.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a3ca60140630a7e1daf36a5', 'zh-CN', 'PassPose：美国护照签证照片合规检查', '在浏览器免费检查美国护照、签证和绿卡照片是否符合官方规定，付费可下载合规尺寸文件及4×6打印页。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a3ca60140630a7e1daf36a5', 'en', 'PassPose', 'PassPose checks a US passport, visa, or green card photo against the official rules: head size, eye height, background, light, and expression. The check is free and needs no account. It runs in your browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a4ea393743c2dacd471f61f', 'zh-CN', 'Travel Terminus：B2B 航班预订门户', '快速上线 B2B 航班预订门户，提供现成平台、实时票价与快速出票，可立即开售航班。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a4ea393743c2dacd471f61f', 'en', 'Travel Terminus', 'Launch your B2B flight booking portal instantly with Travel Terminus. Get a ready platform, real-time fares, and fast ticketing to start selling flights today.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a69bace99ae40058fd120954', 'zh-CN', '赢取 400 美元通用礼品卡抽奖', '免费参与抽奖，有机会赢取 400 美元礼品卡，可用于购物、餐饮、旅行或储蓄，10 月 31 日截止。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a69bace99ae40058fd120954', 'en', 'Win $400 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner decides how to spend the $400 gift card. Enter free before the giveaway ends October 31.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_17c45355e2590f15dc2bfb12', 'zh-CN', 'Tripboard', '并排查看行程与地图，一键添加地点、查看车程，管理航班酒店清单并邀请好友协作规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_17c45355e2590f15dc2bfb12', 'en', 'Tripboard', 'Tripboard puts your itinerary and map side by side. Search any place, add it to a day in one click, and see driving times between stops.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_653175ec6041fe3a316bcfd3', 'zh-CN', '赢取 480 美元自由消费抽奖', '面向 7 个国家读者的免费抽奖，中奖者可自选 480 美元礼品卡用途。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_653175ec6041fe3a316bcfd3', 'en', 'Win $480 to Spend Your Way Free Giveaway', 'Shop, travel, eat out or save it. The winner chooses how to use the $480 gift card. Free to enter for readers in 7 countries.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9e2458c2d25663d4293726c1', 'zh-CN', 'Travelnigga 旅行目的地指南', '帮助旅行者挑选理想目的地、获得更佳体验的深度博客。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9e2458c2d25663d4293726c1', 'en', 'Travelnigga', 'Travelnigga is a well-researched and detailed informative blog that helps travelers choose the best destination for their desired travel spot, offering the best experience.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8143883ed126d3cea136d64d', 'zh-CN', 'Paylo Travel', '提供平价航班预订与出行服务', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8143883ed126d3cea136d64d', 'en', 'Paylo Travel', 'Providing Access to Affordable Flights', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8c5c5f6781e8ecd63724e14a', 'zh-CN', '【自荐】TripMate：面向家庭出游的 AI 行程规划工具（Windows / 安卓 / 网页）', 'TripMate 是面向家庭出游、尤其是带父母旅行的 AI 行程规划工具，把景点攻略整理成可编辑、可分享的每日行程，并安排路线、休息时间、交通和费用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8c5c5f6781e8ecd63724e14a', 'en', 'TripMate: AI Itinerary Planner for Family Travel (Windows / Android / Web)', 'TripMate is an AI itinerary planner for family trips, especially with parents. It turns travel ideas into editable, shareable daily plans covering routes, rest breaks, transport, and costs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd012fcafff52a7a4cf00c71', 'zh-CN', 'Freedom Fone：多号码网络通话应用', '在 iOS 和 Android 上使用额外号码和网络通话，将工作、旅行与个人通话分开，号码和用量通过预付费余额支付。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd012fcafff52a7a4cf00c71', 'en', 'Freedom Fone', 'Keep work, travel and personal calls separate with extra numbers and internet calling on iOS and Android. Use prepaid credit: numbers and usage are paid. Messaging depends on number capabilities and service activation.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fbef685b74d026febc48e026', 'zh-CN', 'Deep in China：中国行程预算规划', '按团队总预算、出发城市、天数和兴趣规划中国行程，比较路线、查看每日站点、换算货币并保存或打印行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fbef685b74d026febc48e026', 'en', 'Deep in China', 'Plan a China trip around your total group budget, departure city, days and interests. Compare modeled routes, review daily stops, convert currencies, and print or save your itinerary for free. Prices are planning estimates;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e97996205f2583dfd4aa0e4', 'zh-CN', '赢取420美元通用礼品卡抽奖', '抽奖赢420美元礼品卡，可在购物、餐饮、旅行或储蓄中自由使用，限美加德，10月31日截止。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e97996205f2583dfd4aa0e4', 'en', 'Win $420 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner chooses how to spend the $420 gift card. Open to the USA, Canada and Germany. Ends October 31.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6d8e93d6fc395c824663f532', 'zh-CN', 'Enviaje：委内瑞拉城际拼车与寄件平台', '连接委内瑞拉城际出行与寄件需求的平台，司机顺路接单、Pago Móvil 直接付款、PIN 确认交付。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6d8e93d6fc395c824663f532', 'en', 'Enviaje', 'Enviaje connects people and businesses in Venezuela who need to send a package or travel between cities with independent drivers who are already making that trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2cd73474d435fcf9b51f6f7b', 'zh-CN', 'Tori：旅行帮带购物赚佣金', '连接想购买当地买不到商品的买家与前往当地的旅行者，旅行者带回商品并自定费用，双方确认后放款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2cd73474d435fcf9b51f6f7b', 'en', 'Tori - Earn While You Travel', 'Tori connects buyers who want items that aren''t sold where they live with travelers already heading there. Request it with a link and budget, a traveler brings it back, and funds are released once you both confirm.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a547f8eb7e66f87012d3600e', 'zh-CN', 'FlightIQ：看清机票真实价值', '揭示机票总成本与航司信息，覆盖行程规划、预订及售后变更支持。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a547f8eb7e66f87012d3600e', 'en', 'FlightIQ', 'FlightIQ reveals the real value behind every ticket — total cost, airline intelligence, and support across your whole trip, from planning and booking through post-booking changes.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
