DELETE FROM product_content WHERE product_id IN ('prd_b41033af51d7f923dac5fac9','prd_cdbdf081b3e48009207d8cf8','prd_d7497c1740f3bec000e9d760','prd_da7e090354b6359c4a0fb429','prd_ee0e7deabdb2c83f207d82bc','prd_fcd18f0716cc5dc2e7ef9598','prd_0a05ea991f3c0f21ef6a9c6c','prd_19cb164cc2a22898c6eb2ce4','prd_332856e448e57372486ae760','prd_e7f0b1a589ae50ba842df94d','prd_47e59355728e811dbc131949','prd_d3c986da54bd41989c17ec37','prd_6ee4aa7f1f72866671efebd4','prd_8867424c95969b25d43afc4a','prd_54769ec59b7ae622222e184a','prd_9065e3cb6ad46390737e379c','prd_8ad369690bcdefb7cf08d9cc','prd_42ab15e475407d4972b50569','prd_90c832f473737736d18e46b1','prd_9776a28e1886c8085d95e87c','prd_d5bdb3a55918b5948181fd74','prd_dfd380caebb7ae0f84faa7a5','prd_d7e7febdc1baf373f35293ac','prd_0b0153b3d5c055b4529faca4','prd_f6b6bc4f464b451fa8d12ac4') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_b41033af51d7f923dac5fac9', 'zh-CN', 'Charted 旅行地图与日志', '个人旅行地图与日志，记录到访地点、日期、笔记和照片，管理心愿清单并查看旅行统计。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b41033af51d7f923dac5fac9', 'en', 'Charted', 'Charted is a personal travel map and journal for iPhone, iPad, Mac, Android and Apple Vision Pro. Mark where you have been, record visits with dates, notes and photos, and keep a wishlist for future journeys.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cdbdf081b3e48009207d8cf8', 'zh-CN', 'flightsSALE 实时机票优惠情报引擎', '实时追踪航司官方促销码、闪购与权益，提供简短优惠简报、直达链接及10种语言即时翻译。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cdbdf081b3e48009207d8cf8', 'en', 'flightsSALE', 'flightsSALE is a real-time flight deal and promo intelligence engine under the eToolKing ecosystem.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7497c1740f3bec000e9d760', 'zh-CN', 'Universities Page 留学咨询服务', '巴基斯坦留学咨询机构，提供英、意、法等国学生签证申请与升学指导服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7497c1740f3bec000e9d760', 'en', 'Universities Page', 'Universities Page is a Pakistan-based international education services company and trusted study abroad consultants in Lahore, Karachi, Faisalabad, and Islamabad.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_da7e090354b6359c4a0fb429', 'zh-CN', 'Merakk 薄荷补水口气喷雾', '便携无糖薄荷口腔喷雾，含木糖醇、甘油和薄荷醇，清新口气并缓解口干。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_da7e090354b6359c4a0fb429', 'en', 'Merakk', 'Experience refreshing oral care with Merakk Hydrating Breath Spray – Mint (10ml). This portable, sugar-free mouth spray is designed to freshen breath and help relieve dry mouth.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee0e7deabdb2c83f207d82bc', 'zh-CN', 'Scene：旅行规划与社交发现平台', '集旅行规划、本地发现与社交于一体，可创建行程、邀请好友、浏览活动并分享动态。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee0e7deabdb2c83f207d82bc', 'en', 'Scene', 'Scene brings trip planning, local discovery, and social connection together in one place. Discover trips, events, activities, and experiences that match your interests.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fcd18f0716cc5dc2e7ef9598', 'zh-CN', 'LingoRove：免持音频语言学习', 'LingoRove 将旅行和空闲时间变成语言练习，支持 iPhone、Apple Watch 与 CarPlay 免持音频学习，可自定学习包。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fcd18f0716cc5dc2e7ef9598', 'en', 'LingoRove', 'LingoRove turns everyday travel and downtime into language practice. Learn hands-free with audio lessons on iPhone, Apple Watch and CarPlay.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a05ea991f3c0f21ef6a9c6c', 'zh-CN', 'AE Car Lift Service：阿联酋汽车接送服务', '在迪拜、阿布扎比及阿联酋提供可靠汽车接送，含日常通勤与机场接送。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a05ea991f3c0f21ef6a9c6c', 'en', 'AE Car Lift Service', 'At AE car lift service We provide reliable car lift services in Dubai, Abu Dhabi, and across the UAE.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19cb164cc2a22898c6eb2ce4', 'zh-CN', 'TripTribe', '团队旅行规划应用：创建行程、邀请好友投票选目的地、共建日程并整理旅行开支', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19cb164cc2a22898c6eb2ce4', 'en', 'TripTribe', 'TripTribe brings group travel planning into one shared space. Create a trip, invite your friends, vote on destinations, decide on activities, build a shared itinerary, and organize trip expenses.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_332856e448e57372486ae760', 'zh-CN', 'TripAgent', '整合忠诚度积分并估算现金价值，AI 推荐行程，按日管理航班酒店确认单并监控票价与航班变动。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_332856e448e57372486ae760', 'en', 'TripAgent', 'TripAgent helps you: - Track every loyalty balance in one dashboard with live cash value estimates - Generate AI-curated trip ideas matched to your specific points, budget, and travel style - Organize full itineraries day-by-day with fligh…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e7f0b1a589ae50ba842df94d', 'zh-CN', 'Turkeyy App：土耳其居留、购房与公司注册助手', '为在土耳其生活的外国人提供居留许可、购房、公司注册咨询，并配有 AI 助手和免费咨询。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e7f0b1a589ae50ba842df94d', 'en', 'Turkeyy App', 'Your legal, tourism and real estate partner in Turkey – wherever you live: residence permit (Ikamet), property purchase (Tapu), company formation, with an AI assistant and a free inquiry.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_47e59355728e811dbc131949', 'zh-CN', '印度旅游套餐', '探索拉贾斯坦邦、金三角及皇家堡垒与文化目的地的印度旅游套餐，找到适合行程的旅行方案。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_47e59355728e811dbc131949', 'en', 'India Tour Packages', 'Explore India tour packages covering Rajasthan, the Golden Triangle, royal forts and cultural destinations. Find a trip that suits your travel plans.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d3c986da54bd41989c17ec37', 'zh-CN', 'SettleG：轻松分摊团体开销', 'SettleG 帮助朋友、家人、室友和旅行团体创建群组、分摊账单并追踪欠款，支持语音和快速记账。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d3c986da54bd41989c17ec37', 'en', 'SettleG', 'SettleG makes sharing expenses simple with friends, family, roommates, and travel groups. Create groups, split bills, and track who owes whom in one place. Add expenses by voice or use Quick Add to record multiple small expenses at once.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6ee4aa7f1f72866671efebd4', 'zh-CN', 'InstiKit 学校 ERP 管理平台', '面向学校、学院和培训机构的综合 ERP，统一管理招生、考勤、考试、收费、薪资、沟通、交通、宿舍和图书馆等事务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6ee4aa7f1f72866671efebd4', 'en', 'InstiKit School ERP', 'InstiKit is a comprehensive School ERP that helps educational institutions manage admissions, attendance, examinations, fee collection, payroll, communication, transport, hostel, library, inventory, and more from one platform.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8867424c95969b25d43afc4a', 'zh-CN', 'Roamify 旅行 eSIM', '扫描二维码安装旅行 eSIM，按天数和流量选套餐，落地即联网，免买本地卡和漫游费，可在 App 管理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8867424c95969b25d43afc4a', 'en', 'Roamify', 'Roamify sells travel eSIMs you install by scanning a QR code, so you can get online when you land without buying a local SIM card or paying roaming fees.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_54769ec59b7ae622222e184a', 'zh-CN', '票匣AI · 专属收票邮箱,发票自动归集成报销包', '票匣 AI 为每位用户提供专属收票邮箱（手机号@piaoxiaai.com），在京东、携程、12306、美团、滴滴开票时填入即可自动收取发票；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_54769ec59b7ae622222e184a', 'en', 'PiaoXia AI · Dedicated Invoice Inbox with Auto-Generated Reimbursement Packs', 'Dedicated invoice inbox (phone@piaoxiaai.com) collects e-invoices from JD, Ctrip, 12306, Meituan and Didi, then parses, classifies, de-duplicates and exports per-company reimbursement packs with Excel ledger, ZIP originals and PDF cover.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9065e3cb6ad46390737e379c', 'zh-CN', 'Tripeaz：群聊变共享行程', '把群聊讨论转化为共享行程，投票选点并按日排入地图，支持 iPhone 应用与 MCP 规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9065e3cb6ad46390737e379c', 'en', 'Tripeaz', 'Tripeaz turns group chat chaos into one shared itinerary. Your group suggests places, votes, and adds the winner to the day. Every stop stays on a map, in order, on everyone''s phone.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ad369690bcdefb7cf08d9cc', 'zh-CN', '斋浦尔至Khatu Shyam出租车服务', '提供斋浦尔至Khatu Shyam Ji的出租车服务，支持单程与往返，车型含Dzire、Ertiga、Innova和Tempo，起价₹2200。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ad369690bcdefb7cf08d9cc', 'en', 'Jaipur to Khatu Shyam Taxi', 'Book Jaipur to Khatu Shyam Ji taxi service @ ₹2200. Call +919785648036 for Dev Tourist Company. Affordable one-way & round-trip cabs, Dzire, Ertiga, Innova & Tempo.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_42ab15e475407d4972b50569', 'zh-CN', 'DocPro：浏览器端 PDF 与扫描工具箱', 'DocPro 是浏览器内运行的 PDF、扫描、图片与护照照片工具箱，含 38 个本地处理工具，并提供带拍照扫描的无广告 Android 应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_42ab15e475407d4972b50569', 'en', 'DocPro', 'DocPro is a PDF, scanner, image and passport-photo toolbox. The web app has 38 tools that run entirely in your browser, so your files never leave your device. There''s also an ad-free Android app with camera scanning.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_90c832f473737736d18e46b1', 'zh-CN', 'Battery Orbit 电池充电管理', '为 MacBook 设定充电上下限并循环充放电，显示每日区间时长，可暂停恢复常规充电。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_90c832f473737736d18e46b1', 'en', 'Battery Orbit', 'Battery Orbit keeps a plugged-in MacBook between limits you choose (20–90% by default): it charges to the top, runs on battery to the bottom with the cable still in, and repeats.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9776a28e1886c8085d95e87c', 'zh-CN', 'Ultimate Thumbnail Maker：安卓视频缩略图制作工具', '面向安卓视频创作者的缩略图设计工具，内置16:9模板与本地抠图。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9776a28e1886c8085d95e87c', 'en', 'Ultimate Thumbnail Maker', 'Ultimate Thumbnail Maker is a lightweight Android graphic design utility built for mobile video creators and streamers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d5bdb3a55918b5948181fd74', 'zh-CN', 'Traveler Map：全球自然与文化景点互动地图', '通过互动地图发现全球自然奇观与文化遗产，规划旅行路线与行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d5bdb3a55918b5948181fd74', 'en', 'Traveler Map', 'Traveler Map helps you discover natural wonders and cultural heritage sites around the world through interactive maps.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dfd380caebb7ae0f84faa7a5', 'zh-CN', 'Triptime AI 旅行规划器', 'Triptime AI 是新一代旅行规划工具，可规划路线并探索目的地。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dfd380caebb7ae0f84faa7a5', 'en', 'Triptime AI', 'Triptime AI is a new generation trip planner helping users plan trips by creating routes and exploring places.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7e7febdc1baf373f35293ac', 'zh-CN', 'Nomad Fly 全球旅行 eSIM', '面向数字游民和旅行者的旅行 eSIM，覆盖 200+ 国家，即买即用，无需实体 SIM，提供低价 4G/5G 数据套餐。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7e7febdc1baf373f35293ac', 'en', 'Nomad Fly', 'Buy eSIM for travel in 200+ countries. Instant activation, no physical SIM. Cheap data plans for digital nomads and travelers. 4G/5G worldwide.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b0153b3d5c055b4529faca4', 'zh-CN', 'somewhere.party：家庭度假目的地决策与行程规划', '帮助家庭用共享清单和积分投票选出度假目的地，并提供行程、费用、打包清单和旅行记录。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b0153b3d5c055b4529faca4', 'en', 'somewhere.party', 'somewhere🎉 helps families decide where to go on holiday. Everyone adds ideas to a shared Next list and gives them points, then a split-flap departures board draws the winner.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f6b6bc4f464b451fa8d12ac4', 'zh-CN', 'Tool Baba Store：证件照与图片压缩工具', '提供按考试和求职表单要求精确压缩图片、证件照与签名合并、OCR、文字转手写及 AI 放大等图像处理工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f6b6bc4f464b451fa8d12ac4', 'en', 'Tool Baba Store', 'What Makes It Stand Out: • Exact Target Compression: Compress images to precise sizes (e.g., under 20KB or 50KB) required for official exam and job forms.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
