INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_1760d404447266e943bbf525', 'zh-CN', 'RUST+ GPUI 海量图片管理', '基于 Rust + GPUI 的本地海量图片管理工具，不改动原图即可流畅浏览与整理数十万张照片；本机模型索引支持一句话找图、识别图中文字、按人脸找人、相似图自动归组与并排精细对比，图片不上传；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1760d404447266e943bbf525', 'en', 'Rust + GPUI Local Image Manager with On-Device AI Search', 'A local bulk image manager built with Rust and GPUI that browses and organizes hundreds of thousands of photos without altering originals.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_251b7366b08b06dd6dc76fd2', 'zh-CN', 'Isochrone.ch 瑞士公共交通可达时间地图', '将瑞士公共交通时刻表变成交互式出行时间地图，设定起点、出发时间和时限即可查看可达范围。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_251b7366b08b06dd6dc76fd2', 'en', 'Isochrone.ch', 'Isochrone.ch turns Swiss public transport timetables into an interactive travel-time map. Choose a starting point, departure time and time limit to see where you can go. Free, no signup, with fast routing directly in your browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e6e54ed501f4ac0dfe457d88', 'zh-CN', 'VeroMaps：3D地图探索与打卡', 'VeroMaps 用 3D 地图发现废弃城堡、隐秘酒吧和安静观景点，可标注验证地点、赚 XP 与成就、群聊或运营付费群、写旅行日志、停车与离线使用，支持 22 种语言。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e6e54ed501f4ac0dfe457d88', 'en', 'VeroMaps', 'Find abandoned castles, secret bars and quiet viewpoints on a 3D map. Add and verify spots, earn XP and achievements, chat in explorer groups or run your own paid group, keep a travel journal, park your car, go offline. 22 languages.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2a43012bf8e2c7b9a2f3d8d3', 'zh-CN', 'GoPlanly', 'AI旅行行程规划工具，提供逐日计划、地图、交通时间与预算跟踪。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2a43012bf8e2c7b9a2f3d8d3', 'en', 'GoPlanly', 'AI travel itinerary planner with day-by-day plans, maps, travel times and budget tracking.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_384d0ff91823d5777593ae8d', 'zh-CN', 'Lidolovets：Telegram 购买意向监控工具', 'Lidolovets 按关键词监控 Telegram 公开聊天，用模型识别真实购买意向，并在仪表盘展示消息与作者，便于销售回复。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_384d0ff91823d5777593ae8d', 'en', 'Lidolovets', 'Lidolovets watches open Telegram chats by keyword and uses a model to tell a real purchase request apart from ordinary discussion.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_31ce9d5302e830fea41797fa', 'zh-CN', 'MotionGuard：手机被移动即报警', '出门前开启 MotionGuard，手机被移动即触发本地报警；Pro 版支持拔充电器提醒与 Wear OS 腕部提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_31ce9d5302e830fea41797fa', 'en', 'MotionGuard', 'Arm MotionGuard before leaving your phone on a desk, charger or hotel nightstand, and it sounds a local alarm if the phone is moved. Free includes Normal sensitivity, a settle delay, a sensitivity test and local trigger history.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3890dc3243b186fc24bbb086', 'zh-CN', 'PamsBeyond：开源旅行规划工作台', '开源旅行规划工作台，本地运行，支持离线签证查询、专家文档审核、多币种预算和PDF行程导出。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3890dc3243b186fc24bbb086', 'en', 'Pamsbeyond', 'PamsBeyond is an open-source travel workspace built with Streamlit. It runs 100% API-free on local engines to stop the chaos of multi-tab trip planning. 🚀 Key Features: • Instant Visa Hub: Check worldwide entry rules offline.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_46164bdab98d8cef4f14bd60', 'zh-CN', 'SafeDummyTicket 签证机票酒店预订单', '为签证申请和国际旅行提供可验证的机票 PNR、PDF 行程单及酒店预订确认。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_46164bdab98d8cef4f14bd60', 'en', 'SafeDummyTicket', 'SafeDummyTicket helps travelers arrange flight and hotel reservations for visa applications and international travel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3fbfc7dc76476fb80d50268b', 'zh-CN', 'VeriSec Labs', '统一 KYC、证件与 NFC 护照核验、人脸活体、AML 筛查、支票 MICR 与银行卡识别 API，并为每位申请人返回 Trust Seal。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3fbfc7dc76476fb80d50268b', 'en', 'VeriSec Labs', 'VeriSec Labs unifies KYC, document verification, NFC/ePassport, face biometrics, liveness detection, AML screening, bank cheque (MICR) reading, payment card capture and BVeriSec Labs unifies KYC, document verification, NFC/ePassport, face…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_57d15fcf07c808e396e96c9d', 'zh-CN', 'FareRelay 低价国际航班搜索', '通过智能中转路线、低成本航空和替代机票组合查找低价国际航班。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_57d15fcf07c808e396e96c9d', 'en', 'FareRelay', 'Find cheap international flights with smarter gateway routes, low-cost carriers, and alternative airfare combinations.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3a3e1227af12162f3fcef177', 'zh-CN', 'Digital Time Machine：本地优先的个人时光机', '本地优先的笔记、照片与文件版本时光机，可回溯恢复并回顾每日与全年记忆。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3a3e1227af12162f3fcef177', 'en', 'Digital Time Machine', 'Digital Time Machine — Your private, local-first time machine for notes, photos & files.Create or import content. Every version is saved. Travel back anytime, restore old versions, replay your day, and see a full year on the Memory Map.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8b2d48fd58fe1c6f2f8260ce', 'zh-CN', 'TrailZ：把旅行视频变成真实行程', '将热门旅行视频转化为可执行行程，提供透明价格与实用贴士。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8b2d48fd58fe1c6f2f8260ce', 'en', 'TrailZ', 'Saw it on a Reel? Go live. ✈️ TrailZ turns viral travel videos into real trips with transparent pricing, insider tips, and plans you can actually follow. Less scrolling, more exploring. 🌍🔥', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_92a8137889d6e1b9117fb0b1', 'zh-CN', 'Travel Datings 旅行约会', '按城市和日期匹配同程旅行者的约会应用，支持33种语言翻译聊天及语音视频通话。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_92a8137889d6e1b9117fb0b1', 'en', 'Travel Datings', 'Going somewhere? Someone else is going there too. Travel Datings matches travelers (18+) heading to the same city on the same dates.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9019b84af5bee1e706f02e37', 'zh-CN', 'Viasimo：预付旅行 eSIM', '面向 202 个国家与 22 个地区的预付旅行 eSIM，按天计价，落地自动连当地网络，无需换卡或漫游。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9019b84af5bee1e706f02e37', 'en', 'Viasimo', 'Viasimo sells prepaid travel eSIMs for 202 countries and 22 regions, from $1.29. Pick a plan before your trip, get a QR code by email within minutes, and your phone connects to a local network when you land.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b18324fb7d65f9e3b91d6b36', 'zh-CN', 'Visaboards', '全球签证移民平台，提供留学、工作、移居路径、国际职位、国家对比及资格与积分计算工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b18324fb7d65f9e3b91d6b36', 'en', 'Visaboards', 'VisaBoards is a global platform for people exploring opportunities to study, work, and relocate abroad.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9cbd50c59a225e8df8be4c5d', 'zh-CN', 'PolarTourist 南极旅行费用计算器', '免费南极旅行预算计算器，汇总邮轮、机票、住宿、装备、保险、附加项和小费，支持调整人数、舱位与季节比较预算，估算为美元。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9cbd50c59a225e8df8be4c5d', 'en', 'Antarctica Trip Cost Calculator', 'A free planning calculator that puts cruise fare, flights, hotel buffer nights, gear, insurance, add-ons and tips in one budget. Change traveller count, cabin tier, season and extras to compare scenarios.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b3ff4cea240da45f117e9578', 'zh-CN', 'SlickTrip MCP：聊天内查机票酒店并监控降价', '在 ChatGPT 或 Claude 聊天中用自然语言查询机票、酒店和座位，并在聊天结束后继续监控价格与余票，降价或有票时通过邮件、短信或推送提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b3ff4cea240da45f117e9578', 'en', 'SlickTrip MCP', 'Ask ChatGPT or Claude for flights, hotels or seats in plain words, and real prices come back as cards right in the chat.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bab526f4e82f2a133fd92418', 'zh-CN', 'GoPromotional 定制旅行杯', '英国 GoPromotional 提供可印 logo 的定制旅行杯，含塑料、不锈钢、铜真空杯及 Stanley、Contigo 等品牌，支持丝印、全彩和激光雕刻，10 件起订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bab526f4e82f2a133fd92418', 'en', 'GoPromotional Travel Mugs', 'Custom travel mugs from GoPromotional in the UK: plastic travel mugs, stainless steel and copper vacuum-insulated tumblers, reusable coffee cups, enamel mugs and big-name brands such as Stanley and Contigo, all printed or engraved with you…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bbf7e6ff58e30368cbe4daec', 'zh-CN', 'Waydo 公路旅行规划器', 'Waydo 按天规划公路旅行，添加停靠点、计算每段距离与驾驶时间，推荐沿途酒店和景点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bbf7e6ff58e30368cbe4daec', 'en', 'Waydo', 'Plan a road trip day by day: add stops, get distance and drive time for each leg, hotels near every overnight stop and attractions along the way. Free for trips up to 3 days.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d03916b0b643bd326c546e82', 'zh-CN', 'Allworld：真实城市人生模拟游戏', '免费浏览器人生模拟游戏，在真实城市创建角色、3D探索、工作旅行安家并与朋友游玩。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d03916b0b643bd326c546e82', 'en', 'Allworld', 'Allworld is a free browser life-simulation game set in real cities around the world. Create a character, explore in 3D, work, travel, build a home and play games with friends. People and clearly labelled AI characters share the world.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0c11f5efb48dda77d6316596', 'zh-CN', 'GasSplit', '按人分摊自驾游油费的估算工具，可输入里程、选择付款人并计入过路费和停车费，生成清晰账单，无需注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0c11f5efb48dda77d6316596', 'en', 'GasSplit', 'Estimate road trip gas costs per person. Enter distance or odometer readings, choose who pays, add tolls and parking, and share a clear bill. No sign-up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_96e779ae1c53c86d45a681c4', 'zh-CN', 'Yuki：个人生活 AI 助手', '整合邮件、日历、任务、订阅与旅行计划，提供洞察并主动代为处理日常事务的个人 AI 助手。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_96e779ae1c53c86d45a681c4', 'en', 'Yuki', 'Meet Yuki, your personal AI assistant for everyday life. Your emails, calendars, tasks, subscriptions, travel plans, and responsibilities are scattered across dozens of apps.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_157d71cbd131da5b619a4ae2', 'zh-CN', 'Voyafolio：旅行日志与证件保险箱', 'iPhone 私密旅行日志与证件保险箱，可在地图记录行程，并用 Face ID 保护护照票据、提供到期提醒，无需账号或云同步。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_157d71cbd131da5b619a4ae2', 'en', 'Voyafolio: Trips & Safebox', 'Voyafolio is a private travel journal and document vault for iPhone. Log every trip on a map with stays, notes and photos – and keep passports, IDs and tickets in a Face ID–protected Safebox with expiry reminders.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2e9248e9606f98d832d6d671', 'zh-CN', 'TableFlow 餐厅桌台与点单管理', '餐厅桌台平面图与点单管理原型，支持搜索桌台、菜单和厨房状态。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2e9248e9606f98d832d6d671', 'en', 'TableFlow', 'TableFlow is a free prototype inspired by my experience working in hotel food service. Finding the right table among nearly 100 tables and recording orders on paper was challenging. I built TableFlow to make that process simpler.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1794adb57213793c81d79200', 'zh-CN', 'iOS 旅行货币换算与税费估算应用', '一款 iOS 旅行货币换算应用，结合定位和地区自动估算含税价格，并提供小费习俗与退税信息。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1794adb57213793c81d79200', 'en', 'Show HN: iOS location based traveler''s currency conversion with tax estimations', 'I&#x27;ve made this app a while ago and now updated it with responsive UI and nice widgets. Why did I make it? During my travels to the US and Canada, I wanted to see prices in my currency.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
