DELETE FROM product_content WHERE product_id IN ('prd_3a9c060177b7bbc53258c9a9','prd_32f87d1358e61d5bc7fc2c4b','prd_3c9b3eced78a6f5ca5d6fa68','prd_44f6835bdfc6c62c8a7f4d73','prd_42e57a562f6bfc729dc92dcb','prd_40ba18a39a308a79afeb388b','prd_4d0bca070578711af5d0687a','prd_561d2ec5ff613032619c0a65','prd_4814c68e8b86852a82e26a46','prd_5d5617958bd09ce5eae41ce7','prd_5e6010500d925032e264071a','prd_5a033014a12245d113066d48','prd_746f52490809de95c1f880eb','prd_86ad832898bcb42c8d9fae41','prd_a067e080a034ec07b5a88ee1','prd_5f4725c869ea7015adbfb02f','prd_a74eae892e864e375b437c28','prd_af775da916335e5e0fd01d4e','prd_edb98c671f6b79ba9e0d2ba5','prd_bb7351eae8401d73d8ce92fd','prd_e79aab8e9909ff3fbb38ee4f','prd_0bef24e0fceca14928c62c6f','prd_f77139a67e058ea9da483ea5','prd_f0bf92a9f70903e8f45fc7bf','prd_2f700f4c8783ff59897596a8') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_3a9c060177b7bbc53258c9a9', 'zh-CN', 'Mubboo Flights：一站式旅行比价平台', '整合航班、酒店、租车、旅行团和景点门票的旅行比价平台，提供目的地指南与虚拟导览，免费且无需账户。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3a9c060177b7bbc53258c9a9', 'en', 'Mubboo Flights', 'Plan your trip with less searching and fewer tabs. Mubboo Flights brings flights, hotels, car rentals, tours and attraction tickets into one easy-to-use travel comparison platform.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32f87d1358e61d5bc7fc2c4b', 'zh-CN', 'ETA Coach：为时间盲区人群倒推日程', '面向时间感弱人群的规划应用，按到达时间倒推任务，自动加入路程与缓冲，并用语音教练实时引导。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32f87d1358e61d5bc7fc2c4b', 'en', 'ETA Time Blindness', 'ETA Coach is the app for everyone who''s terrible with time. You set one thing — when you need to arrive.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3c9b3eced78a6f5ca5d6fa68', 'zh-CN', 'StageAI 客服知识协作平台', '整合服务知识、对话与跟进流程的客户支持平台，并为 TripTok 和 eSIMoa 提供旅行及 eSIM 指引。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3c9b3eced78a6f5ca5d6fa68', 'en', 'StageAI', 'StageAI brings service knowledge, conversations and follow-up workflows together for customer support, including travel and eSIM guidance for TripTok and eSIMoa. Integration scope is agreed per service.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_44f6835bdfc6c62c8a7f4d73', 'zh-CN', 'TransLemon：iOS 旅行翻译器', 'iOS 旅行翻译应用，可拍照翻译手写菜单和标牌，点选菜品查看图文介绍，并支持一键对话翻译。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_44f6835bdfc6c62c8a7f4d73', 'en', 'TransLemon', 'TransLemon is a simple travel translator for iOS. Snap a photo to translate handwritten menus and signs, tap a dish to see what it is with matching photos, or start a conversation translation with one tap.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_42e57a562f6bfc729dc92dcb', 'zh-CN', 'Pugali Digital 高质量外链平台', '提供经人工审核、月访问量至少1000的多领域网站高质量外链。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_42e57a562f6bfc729dc92dcb', 'en', 'Pugali Digital', 'Get high-quality backlinks from websites across multiple niches, including tech, finance, health, travel, business, and more, all in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_40ba18a39a308a79afeb388b', 'zh-CN', 'StageVPN 连接加密工具', '为公共 Wi-Fi、旅行和远程办公场景加密设备连接，使用前需核对平台与套餐支持。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_40ba18a39a308a79afeb388b', 'en', 'StageVPN', 'StageVPN helps encrypt device connections when using public Wi-Fi, traveling or working remotely. Available platform support, server coverage and plan terms should be checked before use.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d0bca070578711af5d0687a', 'zh-CN', 'Avago：酒店预订转售与竞价平台', '全球酒店预订二级市场，可折价转售不可退款客房，并支持用户直接出价订房。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d0bca070578711af5d0687a', 'en', 'Avago', 'Every year, millions of travelers lose money on non-refundable hotel rooms they can''t use. Avago solves this by creating the first global secondary market for hotel bookings.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_561d2ec5ff613032619c0a65', 'zh-CN', 'OSIRIS 全球实时情报平台', '将开源数据汇聚到交互地图，实时查看航班、船舶、卫星、CCTV、天气与网络威胁。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_561d2ec5ff613032619c0a65', 'en', 'OSIRIS', 'OSIRIS is a real-time global intelligence platform that brings open-source data together on an interactive map. Explore live flight tracking, maritime activity, satellites, CCTV, weather, and cyber threats.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4814c68e8b86852a82e26a46', 'zh-CN', 'Claude 内一键预订机票', 'BonBook 的 MCP 让用户在 Claude 中用少量或详细条件搜索实时航班并直接完成预订，无需填表，积分与会员状态照常保留，约 35 秒完成。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4814c68e8b86852a82e26a46', 'en', 'Show HN: One click flight booking in Claude', 'tldr; Travelers wanted to find and book flights super fast in Claude, so we built this. -- BonBook started as flights via email because I was flying once a week in &#x27;24 and the UX got to me. Since then we&#x27;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d5617958bd09ce5eae41ce7', 'zh-CN', 'Solis Nature：自然住宿预订', '精选全球自然住宿，可预订特色酒店、度假村、别墅与独特旅行体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d5617958bd09ce5eae41ce7', 'en', 'Solis Nature', 'Discover handpicked nature stays across the world with Solis Nature. Book curated hotels, resorts, villas and unique escapes for meaningful travel experiences', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5e6010500d925032e264071a', 'zh-CN', '【网站自荐】Notebook Generator：免费在线生成可打印的笔记本、手帐 PDF', '免费的浏览器工具，用于设计纸质笔记本：从 100 多种内页模板（点阵、横线、方格、周计划、月历、习惯追踪、康奈尔笔记、五线谱等）中选择，设置纸张尺寸（A4、A5、Letter、旅行者手帐、护照本或自…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5e6010500d925032e264071a', 'en', 'Notebook Generator: Free Printable Notebook and Planner PDF Maker', 'Free browser tool for designing paper notebooks: pick from 100+ page templates (dot grid, ruled, graph, weekly and monthly planners, habit tracker, Cornell, manuscript, music staff), choose a paper size (A4, A5, Letter, Traveler''s, Passpor…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5a033014a12245d113066d48', 'zh-CN', 'Show HN：隐瞒20年后，我公开了重罪犯身份', 'Eventbrite 早期工程师、Reforge 创始工程师回顾隐瞒20年的重罪犯身份，从无家可归到退休写自传。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5a033014a12245d113066d48', 'en', 'Show HN: I told people I''m a convicted felon after 20 years of hiding it', 'Hi there. I was engineer number 3 at Eventbrite and founding engineer at Reforge. I&#x27;ve created a dozen or so startups myself and have worked in many others, like Instacart. All this time, no one knew that I was a convicted felon.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_746f52490809de95c1f880eb', 'zh-CN', 'Unlost：基于真实旅行经验的行程规划', '基于真实旅行者经验生成有来源依据的行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_746f52490809de95c1f880eb', 'en', 'Unlost', 'Source-backed itineraries built from real traveler experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86ad832898bcb42c8d9fae41', 'zh-CN', 'TravelBoost：旅行社 AI 一体化运营系统', '面向旅行社与旅游运营商的 AI 平台，整合 CRM、报价、预订、供应商、开票与财务等业务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86ad832898bcb42c8d9fae41', 'en', 'TravelBoost', 'Meet TravelBoost, the AI-powered operating system built for travel agencies and tour operators. Replace disconnected tools with one platform to manage leads, CRM, travel proposals, bookings, suppliers, invoicing, finance, tours, Hajj & Umr…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a067e080a034ec07b5a88ee1', 'zh-CN', 'Inbounder Pro：航班追踪（macOS）', '把 Mac 变成个人空域雷达，实时追踪头顶航班并回放历史飞行轨迹。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a067e080a034ec07b5a88ee1', 'en', 'Inbounder Pro: Flight Tracking (macOS)', 'Ever heard a low rumble above your home or office and wondered, "What flight just flew overhead?" Inbounder Pro 2.0 turns your Mac into a precision personal airspace radar and historical flight replay station.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5f4725c869ea7015adbfb02f', 'zh-CN', '【开源自荐】Open Doubao Phone：豆包手机的开源版，让 AI 自己操作手机里的应用，提供基于 Android 17 的定制操作系统也可以独立运行应用', 'Open Doubao 是豆包手机的开源版：说出任务，AI 便自行操作手机应用。含基于 Android 17 的定制系统（适配 Pixel 6 Pro），支持电源键/唤醒词、独立虚拟屏执行查询任务，…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5f4725c869ea7015adbfb02f', 'en', 'Open Doubao Phone: an open-source AI phone that operates your Android apps', 'Open-source take on a Doubao phone: state a task and the AI operates your Android apps itself. Includes an Android 17-based OS for Pixel 6 Pro (power-button or wake-word, background virtual-screen queries), plus a standalone Android 11+ ap…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a74eae892e864e375b437c28', 'zh-CN', 'Good Tourist：旅行碳足迹与自然保护', '计算旅行碳排放并可视化，提供行动建议及目的地自然保护组织信息，免费免注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a74eae892e864e375b437c28', 'en', 'Good Tourist', 'Calcule le CO2 de ton trajet, choisis comment agir, et trouve une asso qui protège la nature là où tu pars.Enter your trip and watch it cross the globe as the CO2 adds up, using public ADEME data.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_af775da916335e5e0fd01d4e', 'zh-CN', 'Local Point 台湾本地服务市场', '台湾本地服务市场，按区浏览餐饮、购物、旅行与日常服务，支持即时预订、预约或到店自取，商家可上架商品并管理订单。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_af775da916335e5e0fd01d4e', 'en', 'local-point', 'ocal Point is a Taiwan-focused local services marketplace. Pick your district, browse categories (food, shopping, travel, daily services), and order with instant booking, reservations, or pickup—cash at store by default.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_edb98c671f6b79ba9e0d2ba5', 'zh-CN', 'Cabin Mode', '旅行 eSIM 应用：出发前购买并安装流量套餐，落地即联网，无需更换实体 SIM 卡，原号码保持不变。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_edb98c671f6b79ba9e0d2ba5', 'en', 'Cabin Mode', 'Cabin Mode is a travel eSIM app that gets you online the moment you land, without a physical SIM swap. Buy a data plan before you fly, install it while you still have Wi-Fi, and switch it on when you land.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bb7351eae8401d73d8ce92fd', 'zh-CN', 'Roamly：AI 微旅行与行程规划', 'AI 根据目的地、节奏和兴趣生成逐日行程、本地美食与导航时间线，适合周末微度假。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bb7351eae8401d73d8ce92fd', 'en', 'Roamly: AI Micro Trip & Rota', 'Roamly transforms weekend escapes and micro-vacations with AI-powered personalized itinerary planning.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e79aab8e9909ff3fbb38ee4f', 'zh-CN', 'TicketGlide 旅行比价平台', '聚合景点门票、旅行团、一日游与指南的旅行比价平台，支持四语网页，并提供只读 MCP 接口供 AI 助手搜索指南和生成旅行搜索链接。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e79aab8e9909ff3fbb38ee4f', 'en', 'TicketGlide', 'TicketGlide brings attraction tickets, tours, day trips and practical guides into one easy-to-use travel comparison platform. Explore in four languages on desktop or mobile, with no app to install.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0bef24e0fceca14928c62c6f', 'zh-CN', 'Hellohood：附近线下小计划社交地图', 'Hellohood 用地图展示附近咖啡、跑步、徒步等线下小计划，点击可加入群聊或发布自己的计划，连接同城用户与旅行者，非约会。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0bef24e0fceca14928c62c6f', 'en', 'Hellohood', 'Hellohood is a map of small real-life plans near you: coffee, a run, pickup football, a hike, a language exchange, a day trip. Tap to join and a group chat opens, or post your own plan in one sentence.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f77139a67e058ea9da483ea5', 'zh-CN', 'All Travel Memories：旅行照片日记', '把 iPhone 旅行照片按行程与地点整理到地图，并可补充笔记、同伴与花费，支持导出备份。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f77139a67e058ea9da483ea5', 'en', 'All Travel Memories: Journal', 'Organize your iPhone travel photos into trips, places and memories on a map. Use available photo GPS and timestamps, add notes, companions and expenses, then revisit your journey or share a photo video or long image.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0bf92a9f70903e8f45fc7bf', 'zh-CN', 'Calcus：全能计算器与日常工具', '集科学计算、财务规划、旅行成本、油价与汇率换算及语音输入于一体的计算器应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0bf92a9f70903e8f45fc7bf', 'en', 'Calcus', '# Calcus – More Than a Calculator Meet **Calcus**, your all-in-one calculator and everyday utility companion.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f700f4c8783ff59897596a8', 'zh-CN', 'SoloSquare 旅行地图', '免费旅行地图：标记已到访与心愿城市，统计城市和国家数量，可自定义样式并导出图片或离线 HTML。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f700f4c8783ff59897596a8', 'en', 'SoloSquare Travel Map', 'New in SoloSquare: a free map of your travel life. Pin visited and wishlist cities, count cities and countries, and turn your map into something worth sharing. Mix five layouts, three map graphics and five palettes.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
