DELETE FROM product_content WHERE product_id IN ('prd_0ea5d3fa6e3a7262b5eab611','prd_1290933afc9448968ded7126','prd_310b10087fa49b9b2aabc17f','prd_59c6c258a10d0a01cd8ca4d0','prd_5fec7600bce7419d66b55ad9','prd_1b5f87a23e94021715b78898','prd_61d71015b28377f75115ee70','prd_62a060b761f853d59464e5ff','prd_714ce1c8594822e57e12d4e2','prd_7098ae6331063e4a1e6bb82c','prd_a351f72aacd39e6b2656c278','prd_7af0c4be91ca55f5ef461d7f','prd_b532e1c4f7e37bf18f3a5023','prd_60049fb5953291be86aeb609','prd_bcb009262d7ab91d7ddcfd49','prd_9076b3048cefc58c097890ec','prd_b59c0b6477218a5a2d958c93','prd_dc7b042f51503b89df8e74a7','prd_d759f4252be7747308c835d2','prd_e2a7778ae91c442c79654b3a','prd_e528ef854688eaae0a3a2922','prd_d0c558545ffdb177464bfc98','prd_e8c35ea1dc998257591c8a8e','prd_f0867c373e1b7f9f0bcaa82b','prd_3d70a12b251571fa42130d60') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_0ea5d3fa6e3a7262b5eab611', 'zh-CN', 'Travora：旅行社交探索地图', '在地图上标记到访城市，发布动态与故事，与同地旅行者实时聊天，并获取旅行灵感。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ea5d3fa6e3a7262b5eab611', 'en', 'Travora', 'Travora turns travel into a social exploration. Mark the cities you visit on a world map, share your memories through posts and stories, and chat in real-time with other travelers in the same location.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1290933afc9448968ded7126', 'zh-CN', 'True America：本地旅行探索与打卡应用', '连接旅行者与本地真实地点和房东的跨平台旅行应用，含州钓鱼/公园通行证、50州打卡与社区匹配。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1290933afc9448968ded7126', 'en', 'True America', 'A cross-platform travel app connecting explorers with authentic local spots and hosts. Stands out with integrated state fishing/park pass portals, gamified 50-state footprint tracking, and community matchmaking designed for real local disc…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_310b10087fa49b9b2aabc17f', 'zh-CN', 'Smart China Trip：中国旅行规划指南', '面向国际游客的中国旅行规划工具，可按天浏览城市、路线与景点，查看时间费用估算，并获取入境、支付、网络、交通、住宿及文化指南。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_310b10087fa49b9b2aabc17f', 'en', 'Smart China Trip', 'Smart China Trip helps international visitors explore China destinations and plan sightseeing by day. Browse cities and suggested routes, organize sights, and review displayed time and cost estimates.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_59c6c258a10d0a01cd8ca4d0', 'zh-CN', 'TagX 网络数据采集服务', 'TagX 提供托管式网络数据采集，覆盖电商、旅行、房地产等来源，输出 JSON、CSV、XML 或 Parquet，并经 API、云存储、Sheets 或 SFTP 交付。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_59c6c258a10d0a01cd8ca4d0', 'en', 'TagX', 'TagX is a web data provider trusted by 500+ companies across the United States. Our data collection services cover any source at any scale, and we build, run, and maintain every scraper so your engineering team never has to.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5fec7600bce7419d66b55ad9', 'zh-CN', 'GlobeNow.tv：旋转地球看全球直播', '旋转3D地球，浏览各国新闻视频、旅行影像、实时摄像头和官方YouTube直播频道。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5fec7600bce7419d66b55ad9', 'en', 'GlobeNow.tv', 'Spin a 3D globe and watch what is happening there: the last 24 hours of news video from trusted outlets, travel films and live webcams, and 647 official YouTube live TV channels from 64 countries.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1b5f87a23e94021715b78898', 'zh-CN', 'Tunnelprobe：VPN 泄漏检测工具', '面向数字游民和远程工作者的免费住宅 VPN 泄漏检测，覆盖 IPv4、IPv6、DNS、WebRTC 与代理，并提供修复提示。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1b5f87a23e94021715b78898', 'en', 'Tunnelprobe', 'Free residential VPN check for digital nomads and remote workers. It tests for IPv4, IPv6, DNS, WebRTC and proxy leaks, spots travel routers like GL.iNet and gives you hints on how to fix every issue. Runs in your browser. No sign-up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_61d71015b28377f75115ee70', 'zh-CN', 'TripWatch', '在灵活日期内比较航班和酒店，保存 Watch 并获取自动价格检查与邮件提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_61d71015b28377f75115ee70', 'en', 'TripWatch', 'Plan ahead with flexible dates. TripWatch compares flight and hotel options within your travel window, then lets you save a Watch. Activate a 30-Day Watch Pass for €4.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_62a060b761f853d59464e5ff', 'zh-CN', 'SKYLARK 奢华酒店预订平台', '奢华酒店预订平台，覆盖4000+精选酒店，提供升级、双人早餐等会员礼遇，并有人工顾问支持。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_62a060b761f853d59464e5ff', 'en', 'SKYLARK', 'SKYLARK is a luxury hotel booking platform with perks like upgrades, daily breakfast for two, property credits, and rate discounts at 4,000+ hand-picked hotels worldwide. Every booking is backed by real human advisors.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_714ce1c8594822e57e12d4e2', 'zh-CN', 'Brijjo：面向国际游客的中国旅行 iOS 应用', '面向国际游客的中国旅行 iOS 应用，提供多语言景点指南、语音徒步导览、英文友好餐厅、私人行程地图与实用旅行工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_714ce1c8594822e57e12d4e2', 'en', 'Brijjo', 'Brijjo is an iOS China travel app for international visitors, with multilingual attraction guides, audio walking tours, English-friendly restaurants, private itinerary maps, and practical travel tools.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7098ae6331063e4a1e6bb82c', 'zh-CN', 'Unlocked：旅行地标打卡护照', 'Unlocked 是免费旅行护照，可在 24 个目的地的 168 个地标验证到访、收集插画徽章，并生成 AI 旅行肖像。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7098ae6331063e4a1e6bb82c', 'en', 'Unlocked', 'Unlocked is a free travel passport for places you actually visit. Verify your arrival at 168 landmarks across 24 destinations, collect an illustrated badge for each, and optionally turn visits into AI travel portraits.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a351f72aacd39e6b2656c278', 'zh-CN', 'Wingman Airwave', '通过互动3D地球探索108国播客，按地点发现节目并保存喜爱', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a351f72aacd39e6b2656c278', 'en', 'Wingman Airwave', 'Wingman Airwave turns podcast discovery into a visual journey. Explore 15,833 shows across 108 countries on an interactive 3D globe, choose a place, discover new voices, listen to available episodes, and save your favorites.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7af0c4be91ca55f5ef461d7f', 'zh-CN', '伦敦出发 3 星 7 晚乌姆拉套餐', '从伦敦出发的 7 晚 3 星乌姆拉套餐，含机票、酒店和英国本地服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7af0c4be91ca55f5ef461d7f', 'en', '3 star umrah From Lond', 'Cheap Umrah Deals – 7 Nights 3 Star Umrah Package from London with hajjumrah4u flights, hotel & trusted UK service for a smooth journey.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b532e1c4f7e37bf18f3a5023', 'zh-CN', 'TatilMate：AI 旅行伴侣与向导', 'AI旅行伴侣，生成每日行程、提供音频导览与智能地图推荐', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b532e1c4f7e37bf18f3a5023', 'en', 'TatilMate – AI Travel Companion & Guide', 'TatilMate is your ultimate AI-powered travel companion designed to make trip planning effortless. Key Features: • 🤖 AI Itinerary Generator: Get custom, day-by-day travel routes in seconds.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60049fb5953291be86aeb609', 'zh-CN', 'MuftTools 免费在线工具集', '提供50款免注册、免费的浏览器在线工具，涵盖计算器、转换器、图片、PDF、二维码和护照照片制作，文件仅在设备本地处理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_60049fb5953291be86aeb609', 'en', 'MuftTools', 'MuftTools is a free collection of 50 online tools that work right in your browser — no sign-up, no fees, no installs. Calculators, converters, image tools, PDF tools, QR generator, passport photo maker and more.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bcb009262d7ab91d7ddcfd49', 'zh-CN', 'Curiworld 好奇心探索站', '汇聚科学、技术、心理、文化与旅行的趣味故事和互动测验，为好奇心提供探索平台。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bcb009262d7ab91d7ddcfd49', 'en', 'Curiworld', 'Curiworld is an online destination for curious minds. Explore fascinating stories, surprising facts, science, technology, psychology, culture, travel, and everyday mysteries.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9076b3048cefc58c097890ec', 'zh-CN', 'OrangeVacay：独行旅客机票优惠与同行连接', '面向独自旅行者，发现低价机票并连接前往同一目的地的旅伴，组建旅行圈子。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9076b3048cefc58c097890ec', 'en', 'OrangeVacay', 'Traveling Solo? Discover Cheap Flight Deals and Connect With Fellow Travelers Heading to the Same Destination. Your Next Adventure Could Start With a Travel Circle of Your Choice.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b59c0b6477218a5a2d958c93', 'zh-CN', 'Sawari 企业员工拼车平台', '面向企业的拼车平台，帮助员工找到同路同事共享通勤。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b59c0b6477218a5a2d958c93', 'en', 'Sawari', 'Sawari is a corporate carpooling platform designed to help employees discover shared rides with colleagues travelling in a similar direction. We believe the daily office commute deserves a better experience.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc7b042f51503b89df8e74a7', 'zh-CN', '赢取 700 美元自由消费礼品卡', '免费参与抽奖，赢取 700 美元礼品卡，可用于购物、餐饮、旅行或存起来，10 月 31 日截止。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc7b042f51503b89df8e74a7', 'en', 'Win $700 to Spend Anywhere Free Giveaway', 'Shop, eat, travel or save it. The winner decides how to spend the $700 gift card. Enter free before the giveaway ends October 31.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d759f4252be7747308c835d2', 'zh-CN', 'TripRai：AI 定制行程与预算规划', '免费 AI 旅行规划器，按预算、节奏和饮食需求生成逐日行程与费用估算，覆盖 13 国，无需注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d759f4252be7747308c835d2', 'en', 'TripRai', 'TripRai is a free AI trip planner that builds personalised day-by-day itineraries with estimated costs for flights, hotels, food, transport and attractions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2a7778ae91c442c79654b3a', 'zh-CN', 'Ask Dahab：埃及达哈布旅行指南', '由长期居民打造的埃及达哈布独立旅行目录，提供餐厅、潜水中心、住宿及户外活动等真实地址、价格和营业时间。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2a7778ae91c442c79654b3a', 'en', 'Ask Dahab', 'Ask Dahab is an independent travel directory for Dahab, Egypt built by long-stay residents, not tourists who visited once. Every listing has real addresses, verified prices, and actual opening hours.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e528ef854688eaae0a3a2922', 'zh-CN', 'Confessit.lol：印度校园匿名告白社区', '无需注册的印度校园匿名告白社区，可浏览校园动态、互动回复。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e528ef854688eaae0a3a2922', 'en', 'Confessit.lol', 'Every college has stories students won''t share under their real names. Confessit.lol lets adults across Indian campuses post confessions, hostel stories, exam rants and placement experiences without signing up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d0c558545ffdb177464bfc98', 'zh-CN', 'Maktek Photo AI：保留本人面孔的职业头像生成', '上传一张自拍并选择风格，约20秒生成保留本人面容、肤色和发型的职业头像，可下载高清图。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d0c558545ffdb177464bfc98', 'en', 'Maktek Photo AI', 'Most AI headshot tools change your face. Maktek keeps it. Upload one selfie, pick a look (LinkedIn, studio, corporate, creative, travel and more) and get a professional photo in about 20 seconds.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e8c35ea1dc998257591c8a8e', 'zh-CN', 'Tripps.io：不替你规划行程的旅行计划工具', '可分享链接的旅行行程规划器，无需账号或应用，由用户自行安排行程，自动提示缺失交通或未预订住宿，并支持邮件或图片智能导入。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e8c35ea1dc998257591c8a8e', 'en', 'Show HN: Tripps.io – A trip planner that doesn''t plan your trip for you', 'I made a trip planner that you can share with one link, no account or app needed. It leaves the itinerary to you instead of AI, and points out the gaps, like a missing train or an unbooked night.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0867c373e1b7f9f0bcaa82b', 'zh-CN', 'Slids：大画布一键拆分 Instagram 轮播图', '在 iPhone 上将大画布无缝拆分为 Instagram 轮播图，支持全景分割和模板，照片仅留在本机。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0867c373e1b7f9f0bcaa82b', 'en', 'Slids', 'Slids turns one big canvas into a seamless Instagram carousel. Drop photos across slide borders, split panoramas into equal slides, or start from 6,900+ templates (photo dump, travel, birthday). Everything runs on your iPhone;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d70a12b251571fa42130d60', 'zh-CN', 'Weather Forecast - Live Weather 实时天气', 'Android 天气应用，可查看实时天气与预报，帮助规划出行和户外活动。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d70a12b251571fa42130d60', 'en', 'Weather Forecast - Live Weather', 'Weather and Forecast – Live Weather helps you stay informed and plan your day with confidence. Check weather conditions and forecasts before heading out, travelling, or planning outdoor activities.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
