INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_f61a386e592cacc5986422df', 'zh-CN', 'PicPassed：美国护照/签证照片合规校验', '按官方规则校验美国护照、绿卡或签证照片，本地处理不上传、不修图，一次性付费 9.99 美元。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f61a386e592cacc5986422df', 'en', 'PicPassed', 'PicPassed checks your U.S. passport, green card or visa photo against the official rules before you pay. Never edited, never uploaded. $9.99 once.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_550a6bc8c0f67b588f27770b', 'zh-CN', 'MyTripLog 旅行记录与回忆应用', '记录旅行途经点、日期、笔记和照片，以地图、时间线或故事重温并分享旅程，支持云盘存储原图。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_550a6bc8c0f67b588f27770b', 'en', 'MyTripLog', 'MyTripLog turns your travels into a lasting story. Record Waypoints with places, dates, notes and photos, then revisit the journey as a map, timeline or story. Your original photos stay in your own Google Drive, Dropbox or OneDrive.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e12ab1abe0962462707821fc', 'zh-CN', 'SoloSquare Jet Lag Planner 时差调整规划器', '输入航班与日常作息，生成当地时间睡眠、咖啡因截止与光照窗口建议的免费时差调整计划，可离线保存、加入日历或分享', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e12ab1abe0962462707821fc', 'en', 'SoloSquare Jet Lag Planner', 'New in SoloSquare: a free jet lag planner for your next trip. Enter your flight and usual sleep times to get local-time sleep opportunities, caffeine cutoffs and estimated light windows where suitable.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac0daed615aaf96755350e09', 'zh-CN', 'ToolGrid AI：375 款免费在线工具集', '汇集 375 款免费在线工具，含 285 个预算、烹饪、家居、旅行、日期与文本处理等日常助手，并提供实用指南与常见问题。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac0daed615aaf96755350e09', 'en', 'ToolGrid AI', 'Explore 375 free online tools, including 285 everyday helpers for budgets, cooking, home projects, travel, dates and text. Practical guides and FAQs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d347a806497af7d40dd7d8a', 'zh-CN', 'DLNA 镜流 V1.1 电脑通过 DLNA 投屏', 'Windows 桌面工具，可将电脑屏幕和音频实时推流为 HTTP-TS，并自动发现局域网内 DLNA 播放器进行屏幕镜像。推流延迟约 3–4 秒，适合播放电影；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d347a806497af7d40dd7d8a', 'en', 'DLNA Mirror Stream V1.1: Cast Your PC Screen via DLNA', 'Windows desktop app that streams your PC screen and audio as HTTP-TS and discovers DLNA players on the LAN for screen mirroring.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a94fbd9ece8b44692d23f99', 'zh-CN', 'HospiCore PMS 酒店管理系统', '面向酒店的云端物业管理系统，涵盖预订、计费、夜审、报表、员工、客房清洁与库存管理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a94fbd9ece8b44692d23f99', 'en', 'HospiCore PMS - Hotel Management System', 'HospiCore PMS is cloud-based hotel and property management software (SaaS) for Windows, Android and web. Reservations, billing, night audit, reports, staff, housekeeping and inventory. Monthly subscription from $15.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0bb955241133ab328509956f', 'zh-CN', 'Lufthaven：航班追踪', 'iPhone 航班追踪应用，可查看安检等待、执飞飞机、登机口、延误与到达预估，并通过实时活动在锁屏关注航班。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0bb955241133ab328509956f', 'en', 'Lufthaven: Flight Tracker', 'Lufthaven brings your airport day into one flight tracker for iPhone. Check security waits, find your incoming aircraft, and follow gates, delays and arrival estimates.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6702d9628fdf0c65cb9c6c39', 'zh-CN', 'TicTravelDesk 旅行规划', '发现精选目的地与旅行体验，轻松规划并预订完美假期。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6702d9628fdf0c65cb9c6c39', 'en', 'TicTravelDesk', 'Discover breathtaking destinations, curated experiences, and stress-free travel planning. Book your perfect getaway today.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32c8bef1895f62031b084273', 'zh-CN', 'GmailClass：用 AI 为 Gmail 邮件自动打标签', '按自定义分类，用 AI 为 Gmail 邮件自动添加彩色标签，不移动、归档或删除邮件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32c8bef1895f62031b084273', 'en', 'GmailClass - Gmail Email Classifier', 'Your inbox, labeled in your own words! GmailClass uses Jev AI to match emails to categories you describe, then adds colorful labels right inside Gmail. Spot invoices, travel updates, newsletters, or whatever matters to you at a glance!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_83096c12ee0a7acab617164c', 'zh-CN', 'Weather Trip', '按未来天气筛选旅行目的地的工具站，支持按温度、降雨、湿度等条件查找全球城市，通过天气地图比较城市预报，提供中英文界面 - GitHub 仓库', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_83096c12ee0a7acab617164c', 'en', 'Weather Trip', 'Weather Trip is a web tool for finding travel destinations by future weather: filter global cities by temperature, rainfall and humidity, compare forecasts on a weather map, with Chinese and English interfaces.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a3327ca3ca86def998ce5e7', 'zh-CN', 'VIMANA 印度实时航班追踪', '印度实时航班追踪地图，支持航线、时刻、进度与3D跟随，提供航班搜索、起降提醒和机场休息室指南，免费免登录。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a3327ca3ca86def998ce5e7', 'en', 'VIMANA', 'VIMANA is a live flight tracker built for India. See aircraft over Indian skies on a live map, open any flight for its route, timings and progress, or follow it in a 3D chase view.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8f3887c82dcb7dbc17b306bb', 'zh-CN', 'Dubai Dune Safaris 迪拜沙漠之旅', '迪拜红沙丘持牌沙漠之旅预订，含晨间游、VIP 晚间 BBQ、四轮摩托和私人沙丘车。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8f3887c82dcb7dbc17b306bb', 'en', 'Dubai Dune Safaris', 'Experience Dubai''s breathtaking red dunes with licensed desert safari packages. Pick from thrilling morning safaris, VIP evening BBQ dinners, adrenaline-pumping quad biking, and private dune buggy tours.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_01a79abc3c163ca04ee128ef', 'zh-CN', 'Rafiky', '面向全球旅游业的AI平台，整合本地体验预订市场、商家运营软件与AI智能体。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_01a79abc3c163ca04ee128ef', 'en', 'Rafiky', 'Rafiky is an AI-powered intelligence platform for global tourism, combining a travel marketplace, specialized business software, AI agents, and data-driven insights.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_04b36f787d5b2205405210f4', 'zh-CN', 'Born in Japan：如果出生在日本', '基于日本官方统计的免费浏览器人生模拟游戏，逐年体验学校、工作、爱情与意外转折。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_04b36f787d5b2205405210f4', 'en', 'Born in Japan', 'What if you were born in Japan? Live a whole life, year by year, through school, work, love and unexpected turns. A free browser game grounded in official Japanese statistics, with assumptions labeled.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1735fb94526a249f1e7d5c91', 'zh-CN', 'MomentRescue：AI 修复照片闭眼', 'AI 修复合照中闭眼的人物，上传照片并选择人物即可，可添加睁眼参考图，无需 Photoshop。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1735fb94526a249f1e7d5c91', 'en', 'MomentRescue', 'Ever taken a perfect group photo, only to realize someone blinked? MomentRescue uses AI to fix closed eyes in photos while preserving the moment.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb512406ef98ac445ab7e53d', 'zh-CN', '【工具推荐】VoiceBridge：YouTube 外语视频翻译配音与双语字幕对照', 'VoiceBridge 是一款 Chrome 扩展，可将 YouTube 视频中可读取的原字幕翻译成所选语言并配音，同时对照显示原文与译文，便于边听边核对；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb512406ef98ac445ab7e53d', 'en', 'VoiceBridge: YouTube Subtitle Translation, Dubbing & Bilingual Subtitles', 'VoiceBridge is a Chrome extension that translates a YouTube video''s readable source subtitles into a chosen language, dubs them, and shows original and translated text side by side for easy cross-checking while listening.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6f9c73bd737ffabdc739a7bc', 'zh-CN', 'Midnight Jukebox 复古音乐探索', '复古磁带风互动音乐发现体验，按心情和年代探索精选歌单并标记回忆', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6f9c73bd737ffabdc739a7bc', 'en', 'Midnight Jukebox', 'Midnight Jukebox is a nostalgic, interactive music discovery experience inspired by the era of cassettes, mixtapes and late-night listening.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4e66ca58a73783eaae27c6d4', 'zh-CN', 'Nizen Japan 单份抹茶浓缩液', 'Nizen Japan 推出的单份装宇治抹茶浓缩液，可兑水或牛奶冷热饮用，面向分销商、咖啡馆、酒店、航空与零售渠道。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4e66ca58a73783eaae27c6d4', 'en', 'Matcha Portion Cup', 'Discover Japanese matcha concentrate from Nizen Japan, a convenient single-serve liquid format designed to bring Uji Japanese matcha into different beverage applications.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_635a2e504abd1caea7245628', 'zh-CN', 'Fingerpost：AI 旅行行程规划与共享', '10分钟问答生成带来源的逐日旅行计划，含每站时间与费用，可通过链接共享；提供AI旅行伴侣June，按行程付费，$9.50起。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_635a2e504abd1caea7245628', 'en', 'Fingerpost', 'Answer an interview of about 10 minutes and get a day-by-day plan with sources: each stop with its time, cost and where it came from. Everyone going opens it from one link. Add June, an AI travel companion, for the trip. Pay once per trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7905bfce7360b28ea8957a0a', 'zh-CN', 'OKstays：酒店舒适度评分与排名', '依据安静、床品、淋浴、WiFi 等67项舒适信号为3万多家酒店打分排序，可按旅行风格或自选条件筛选出候选清单。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7905bfce7360b28ea8957a0a', 'en', 'OKstays', 'Tired of noisy rooms, broken AC and uncomfy beds? OKstays scores 30,000+ hotels in 199 destinations on 67 comfort signals, like quiet, beds, shower, WiFi and AC, and ranks them by one Comfort Score.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7571940432cc7ae2e4c178ab', 'zh-CN', 'Stroemi：AI 自拍写真与短视频生成', '上传6–10张日常自拍，即可生成34种风格的个人写真，并制作可编辑短视频；按次付费9.99美元起，无订阅。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7571940432cc7ae2e4c178ab', 'en', 'Stroemi', 'Upload 6–10 everyday selfies once, then create photos that actually look like you in 34 styles: LinkedIn headshots, dating, travel, fitness, holidays, or describe your own scene.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e27a81a5a114b8f85eb574f', 'zh-CN', 'MindTheClub 加密私密通讯应用', '无需手机号或邮箱的 Android 端到端加密通讯应用，消息点对点直传，开源且不依赖 Google 服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e27a81a5a114b8f85eb574f', 'en', 'MindTheClub', 'MindTheClub is a private messenger for Android that never asks for your phone number or email. Messages and calls travel directly between devices, encrypted end to end, and are never stored on our servers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a55089150ad45f4dfa0540c2', 'zh-CN', 'Trassa VPN', '跨设备 VPN 服务，支持订阅与设备管理，可在 Android、Windows 及 Apple 设备连接。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a55089150ad45f4dfa0540c2', 'en', 'Trassa VPN', 'Trassa VPN makes secure internet access simple across your devices. Choose a subscription, manage your plan and registered devices from your account, and connect with the Trassa app on Android or Windows.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae214d753762f303e28d2c9a', 'zh-CN', 'NanaZip Rev - NanaZip 社区分支，新增主题切换与代码页切换', 'Windows 10/11 上 NanaZip 的非官方社区分支，跟随上游同步并保留全部功能，新增主题切换（跟随系统/浅色/深色实时生效）、按归档记忆的文件名代码页切换、IEC 文件大小单位、界面语…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae214d753762f303e28d2c9a', 'en', 'NanaZip Rev - Community Fork of NanaZip with Theme and Code Page Switching', 'NanaZip Rev is an unofficial NanaZip fork for Windows 10/11 (x64/ARM64) that keeps upstream features and adds live light/dark theme switching, per-archive filename code page switching, IEC size units, UI language options and Ctrl+W window…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d2a2c8df7a4816a95b0e40ea', 'zh-CN', 'PrimeReviews', 'PrimeReviews 通过二维码让顾客扫码直达 Google 评价页，无需 App 或注册，并在仪表盘追踪扫码与评价。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d2a2c8df7a4816a95b0e40ea', 'en', 'PrimeReviews', 'Most happy customers never leave a Google review because it takes five steps. PrimeReviews gives your cafe, restaurant, hotel or clinic a QR code that opens your Google review screen in one scan. No app, no sign-up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
