DELETE FROM product_content WHERE product_id IN ('prd_bc9e644c44d1fc8fcd9bad11','prd_c38b739e0ac6b37ffef20505','prd_deef2aba70f4e2d0e0e15b44','prd_f46bd4a7ce76d1975986ca75','prd_e28260ccdb6c575ccf45ccab','prd_0b15fd69dfdfd0b41f79abe0','prd_089b1bd9912baf9820043621','prd_1f5610aae5223d534669c723','prd_1f41bf4685a4259bfb6e4164','prd_24656c977988f441c0bae0be','prd_737c7d5b80e1972373793dc9','prd_79478dae52c32eeca5e961b4','prd_0ba2c7f46a80f14f4c57a9ff','prd_8f968f10dac44685ab872e73','prd_8673c35b99db9c273e544ef2','prd_ae08d982cd711d991cda10c7','prd_c838b48b9d013e375708ebd5','prd_dd8807510b9b3393367c4bec','prd_ecaf73924a23d1ac729d1b8e','prd_00150d4b30f5bbd5f2fe8504','prd_423683e7908474c7550764f7','prd_369d2cf0e7a29037dd9c8bb1','prd_4c200c14219c10ecc1ea3f25','prd_23545d577079275e9fda1551','prd_8ee1da2c78489cf8597af3de') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_bc9e644c44d1fc8fcd9bad11', 'zh-CN', 'ClockPick 预约时间规划', '围绕预约前的准备时间规划任务，提供时间轴、计时器和准备清单，避免预约占满整天。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bc9e644c44d1fc8fcd9bad11', 'en', 'ClockPick™', 'ClockPick helps keep an appointment from taking your whole day. Add the appointment, preparation and travel buffers, then see what can safely fit and when to stop and get ready.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c38b739e0ac6b37ffef20505', 'zh-CN', '为帐篷规划全天理想遮阳', '拍摄露营布置并预测全天阴影变化，帮助调整遮阳篷到最佳角度。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c38b739e0ac6b37ffef20505', 'en', 'Show HN: Pitch your tent for perfect shade', 'I recently moved to Australia and have been on a bit of a Roadtrip recently. Getting shade in the middle of the day is the only way to survive without becoming a lobster.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_deef2aba70f4e2d0e0e15b44', 'zh-CN', 'PLAYUS：玩游戏兑换旅行 eSIM 流量', '将休闲浏览器游戏奖励兑换为韩国及海外 eSIM 流量券。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_deef2aba70f4e2d0e0e15b44', 'en', 'PLAYUS', 'PLAYUS turns short browser-game sessions into travel data rewards. Explore casual puzzles, arcade and board games, collect rewards in one wallet, and exchange 100MB or more for a coupon redeemable in Triptok for eSIM data in Korea or abroa…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f46bd4a7ce76d1975986ca75', 'zh-CN', 'Manifest 旅行规划器', '在 3D 地球上规划行程的旅行应用，集中管理航班、自驾路线与旅行记忆。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f46bd4a7ce76d1975986ca75', 'en', 'Manifest - Travel Planner', 'Your trips deserve better than a dozen tabs, a notes app, and a screenshot folder. Manifest is a travel planner handcrafted by one person, obsessed with making planning a trip feel as good as taking one. No team, no bloat, no ads.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e28260ccdb6c575ccf45ccab', 'zh-CN', 'WonderKit 旅行行程协作规划', 'WonderKit 可快速生成逐日行程，用实时 Google Maps 数据核验地点，并支持分享链接让同伴投票活动与住宿。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e28260ccdb6c575ccf45ccab', 'en', 'WonderKit', 'Group trips die in the group chat. WonderKit drafts day-by-day itineraries in seconds. Open any place in your plan and it''s checked against live Google Maps data, marked Verified when it matches.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b15fd69dfdfd0b41f79abe0', 'zh-CN', 'Camping Classics：免费露营规划工具', '免费露营规划工具，提供打包清单、指南、游戏和行程规划功能。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b15fd69dfdfd0b41f79abe0', 'en', 'Camping Classics', 'A free camping planner with packing lists, guides, games, and trip planning tools.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_089b1bd9912baf9820043621', 'zh-CN', '白俄罗斯旅游景点', '探索白俄罗斯最佳旅行地，涵盖历史城堡、活力城市、宁静湖泊森林与文化景点。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_089b1bd9912baf9820043621', 'en', 'Belarus Tourist Attractions', 'Discover the Best Places to Visit in Belarus, from historic castles and vibrant cities to peaceful lakes, forests and cultural attractions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f5610aae5223d534669c723', 'zh-CN', 'Cursor Teleporter 2', 'Mac 光标快捷键工具，可跨屏幕或保存位置跳转，新增边缘传送与高亮', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f5610aae5223d534669c723', 'en', 'Cursor Teleporter 2', 'Less mouse travel on your Mac. Jump between displays or saved cursor positions with a keyboard shortcut. Version 2 adds edge teleporting, cursor highlighting, and Apple Shortcuts and AppleScript support. Free 30-day trial.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f41bf4685a4259bfb6e4164', 'zh-CN', 'Ask TripPilot：AI 旅行规划器', '免费 AI 旅行规划工具，输入行程即可生成地图上的逐日行程，并提供真实机票价格与酒店推荐。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1f41bf4685a4259bfb6e4164', 'en', 'Ask TripPilot', 'Ask TripPilot is a free AI trip planner. Describe your trip and get a day-by-day itinerary on a map, with real flight prices and hotel picks.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_24656c977988f441c0bae0be', 'zh-CN', 'Kings Charter Bus USA 乐队校园包车服务', '为学校活动和乐队音乐节提供包车接送、乐器存放与可靠司机服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_24656c977988f441c0bae0be', 'en', 'Music Group School Bus Rental For Band', 'Make your school event memorable with a bus rental! Transport students safely and conveniently to yoMake every performance memorable with a music group school bus rental for band festivals.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_737c7d5b80e1972373793dc9', 'zh-CN', 'OCI 持有者印度电子入境卡指南', '介绍 OCI 卡持有者赴印需提交的电子入境卡、72 小时申请窗口、所需信息与官方办理步骤。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_737c7d5b80e1972373793dc9', 'en', 'E-Arrival Card for OCI Holders', 'Traveling to India with an OCI card in 2026? Learn about the mandatory e-Arrival Card, the 72-hour submission window, required details, application steps, and official government portal.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_79478dae52c32eeca5e961b4', 'zh-CN', 'Sticta：照片人物贴纸与 Mac 壁纸', '从照片中抠出人物制成贴纸，钉在旅行地图、冰箱门或软木板上，并设为 Mac 壁纸。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_79478dae52c32eeca5e961b4', 'en', 'Sticta', 'Sticta cuts people out of your photos, turns them into stickers and pins them to a travel map, a fridge door or a corkboard — then sets it all as your Mac''s wallpaper.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ba2c7f46a80f14f4c57a9ff', 'zh-CN', '【工具自荐】打码鸭：给图片和视频中的人脸、车牌、文字自动打码', '打码鸭是网页版工具，可自动识别图片和视频中的人脸、车牌和文字，再用马赛克、模糊、实色遮挡、黑条或贴纸打码；支持先预览再按人物调整和修正结果，无需安装，不登录也能使用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ba2c7f46a80f14f4c57a9ff', 'en', 'DamaYa: Auto-Blur Faces, License Plates and Text in Images and Videos', 'DamaYa is a web app that auto-detects faces, license plates and text in photos and videos, then applies mosaic, blur, solid masks, eye bars or stickers. Review and adjust results per person before export. No install or login needed.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8f968f10dac44685ab872e73', 'zh-CN', 'PortuguesePal：免费葡萄牙语口语陪练', 'AI 实时分析并指导葡语发音与流利度，通过情景对话练习口语，并可获二维码语言等级证书', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8f968f10dac44685ab872e73', 'en', 'PortuguesePal - Free Portuguese Partner', 'PortuguesePal AI listens, analyzes, and coaches your pronunciation, fluency, and confidence in real time. Practice interviews, presentations, travel, work, and everyday Portuguese with real conversations, not scripts.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8673c35b99db9c273e544ef2', 'zh-CN', 'NonSoloRisparmio.it：家庭理财与生活指南', '意大利个人理财门户，提供家庭预算、环保生活与低成本旅行实用指南。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8673c35b99db9c273e544ef2', 'en', 'NonSoloRisparmio.it', 'NonSoloRisparmio.it is a premier Italian web portal founded by a freelance journalist. It focuses on practical personal finance, smart household management, eco-friendly lifestyle & sustainable habits, and low-cost travel strategies.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae08d982cd711d991cda10c7', 'zh-CN', 'Ringo', 'Ringo 在一个应用中提供多国真实本地手机号，支持通话、短信和验证码，适合跨境生活与工作人群。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ae08d982cd711d991cda10c7', 'en', 'Ringo', 'Ringo puts multiple real local mobile numbers from different countries on one plan, in one app. Built for people whose lives span borders: expats, cross-border families and international workers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c838b48b9d013e375708ebd5', 'zh-CN', 'GPS Map Camera: GeoStamp 照片地理水印', '为照片自动添加实时 GPS 位置、地图、地址和日期时间水印，适合工地记录、房产勘察与现场服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c838b48b9d013e375708ebd5', 'en', 'GPS Map Camera: GeoStamp', 'GPS Map Camera: GeoStamp automatically adds your location, map, address, date and time to every photo you take - captured live.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dd8807510b9b3393367c4bec', 'zh-CN', '写了个 Web 文件管理器：跨平台、单文件、Vue3 + Go，像资源管理器一样用', 'File Lite 是一个自托管的 Web 文件管理器：后端用 Go，前端用 Vue 3 并嵌入单个二进制文件，解压后双击即可运行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dd8807510b9b3393367c4bec', 'en', 'File Lite: Cross-Platform Single-Binary Web File Manager in Vue 3 + Go', 'Self-hosted web file manager: Go backend with embedded Vue 3 frontend in one ~10MB binary. Dual-pane drag-and-drop, SMB/NFS/WSL mounts, zip/7-Zip, media previews, encoding-safe editor, gallery, plugins, ticket login, HTTPS.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ecaf73924a23d1ac729d1b8e', 'zh-CN', 'GiNi 仓储人力管理平台', '实时追踪仓库收货、拣货、打包、行走与休息工时，对比产能目标，监控人力成本并优化排班。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ecaf73924a23d1ac729d1b8e', 'en', 'GiNi Labor Management', 'GiNi Labor Management captures warehouse activity second by second across receiving, picking, packing, travel, idle time, and breaks.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_00150d4b30f5bbd5f2fe8504', 'zh-CN', '【自荐】花花记账：越记越懂你的 iPhone 生活账本', '花花记账是一款 iPhone 记账应用：卡夹皮肤可自选并烫印，旅行时按城市解锁城市烫印；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_00150d4b30f5bbd5f2fe8504', 'en', 'Huahua Ledger: An iPhone Life Ledger That Learns Your Spending', 'Huahua Ledger is an iPhone bookkeeping app with customizable card-holder skins, travel city stamps, and an on-device AI that learns your spending rhythms to show habits and suggest next entries, plus map replay and monthly reviews.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_423683e7908474c7550764f7', 'zh-CN', 'Tuscany Bags：意大利皮具澳大利亚零售', '澳大利亚线上零售 Tuscany Leather 意大利皮包与配饰，澳元计价，全澳 5–8 天送达。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_423683e7908474c7550764f7', 'en', 'Tuscany Bags', 'Tuscany Bags is an authorised retailer of Tuscany Leather, delivering authentic Italian leather bags and accessories from Florence to customers across Australia.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_369d2cf0e7a29037dd9c8bb1', 'zh-CN', 'Stampr：现实探索数字印章护照', '把现实探索变成数字护照：发现地点、收集印章、解锁成就，与好友对比进度，数据存于本地。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_369d2cf0e7a29037dd9c8bb1', 'en', 'Stampr', 'Stampr turns real-world exploration into a digital passport! Discover places, collect digital stamps, unlock achievements and build your personal collection of adventures.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4c200c14219c10ecc1ea3f25', 'zh-CN', 'MakesYouFluent AI：AI 语言学习平台', 'MakesYouFluent 是 AI 语言学习平台，通过个性化课程和对话练习提升口语与发音。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4c200c14219c10ecc1ea3f25', 'en', 'MakesYouFluent AI', 'MakesYouFluent is an AI-powered language learning platform that helps you build confidence in a new language through personalized lessons and conversational practice.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_23545d577079275e9fda1551', 'zh-CN', 'PlayaRutas 本地公交行程规划应用', '整合普拉亚德尔卡曼与里维埃拉玛雅的零散公交、combi 与 colectivo 线路，用互动地图帮居民和游客规划平价出行', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_23545d577079275e9fda1551', 'en', 'PlayaRutas', 'PlayaRutas is a hyper-local transit app and trip planner for Playa del Carmen and the Riviera Maya.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ee1da2c78489cf8597af3de', 'zh-CN', 'Kitaphone：在浏览器中直接拨打手机与座机', '基于 Next.js 与 Twilio 的 Web 通话应用，无需安装其他 App、购买 SIM 卡或包月订阅，即可在浏览器拨打国际手机和座机。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ee1da2c78489cf8597af3de', 'en', 'Show HN: Kitaphone – Call mobile phones and landlines directly from the browser', 'Hi HN Folks, I have been building Kitaphone a web app that lets you call regular mobile and landline numbers directly from your browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
