DELETE FROM product_content WHERE product_id IN ('prd_67eb8eadb3a0fb7f7ac5248c','prd_5ed6826c8e2fb1eaeab3ec9b','prd_4cf3415feb794dfa124083b3','prd_694d4947164584944705e90e','prd_6bd2f251bdeec85c56b184a8','prd_9a29a1b3f4817ff6028e372a','prd_97e872c11a07bfe8f3cd5776','prd_a4dae6073c5c29377d009466','prd_b0168ebfe21fef70e1759099','prd_defb58b7969ccc0beaf0b850','prd_ac89c79bc691cd0dcff9dced','prd_d7f76134d84311fdc76da31a','prd_b291d1744668a9fd1db9c4bc','prd_ee02928abccf5de95e1120e5','prd_e3ef58d5eccc111ce91f6a2d','prd_f3ab6b1f53fdac66971aaead','prd_27641ca60f33d6a7b7155250','prd_f605b0acd626aace53491e00','prd_3677861eafa020d40a4a746e','prd_32eafb1100e81bc7cb663c13','prd_43138775d0b032ba9408e0f5','prd_120ff63e8e836a6d9b2b6cf4','prd_4f83e7b424bf0ace189f7700','prd_f5b6914d3c683f97d0ee2406','prd_6d04b575e84319d4949ed0f0') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_67eb8eadb3a0fb7f7ac5248c', 'zh-CN', 'AquaFlux 可重复使用智能水杯概念', 'AquaFlux 是一款现代可重复使用水杯概念，主打简约设计与饮水追踪提醒，适合健身、办公、校园和旅行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_67eb8eadb3a0fb7f7ac5248c', 'en', 'AquaFlux', 'Meet AquaFlux, a modern reusable water bottle concept designed to make everyday hydration easier.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5ed6826c8e2fb1eaeab3ec9b', 'zh-CN', 'Xploreum：户外探险 AI 行程规划助手', '用自然语言规划徒步、露营与公路旅行，生成含路线和营地的逐日行程并对话调整。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5ed6826c8e2fb1eaeab3ec9b', 'en', 'Xploreum', 'Meet Xavier, Xploreum''s AI companion for outdoor adventures. Describe your hiking, camping, backpacking, or road trip in plain language, and get a personalized, day-by-day Xpedition with mapped routes, trailheads, campsites, driving legs,…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4cf3415feb794dfa124083b3', 'zh-CN', 'Palm Beach 私人包船', 'Palm Beach 私人游艇包船，乘坐37英尺Axopar观光、看日落、游沙洲和用餐。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4cf3415feb794dfa124083b3', 'en', 'Best Private Charter in Palm Beach', 'Enjoy a private yacht or boat charter in Palm Beach, FL aboard a 37'' Axopar. Rent a private boat for sightseeing, sunsets, sandbars, dining, and more. Book now!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_694d4947164584944705e90e', 'zh-CN', '印度至克罗地亚航班完整指南', '对比航空公司与航线，查询票价并获取预订建议，帮助规划从印度到克罗地亚的行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_694d4947164584944705e90e', 'en', 'Croatia Flights From India A Complete', 'Explore Croatia Flights to compare airlines, discover convenient routes, check airfare options and plan your journey with essential booking tips for a smooth trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6bd2f251bdeec85c56b184a8', 'zh-CN', 'Tablamigo 独行旅友活动匹配', '为独自旅行者展示附近旅友的晚餐、酒局和一日游计划，可快速加入或自行发布。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6bd2f251bdeec85c56b184a8', 'en', 'Tablamigo', 'Traveling solo? Tablamigo shows plans from travelers near you, like dinner, drinks and day trips, so you can join in minutes or post your own.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a29a1b3f4817ff6028e372a', 'zh-CN', '协作式多币种记账工具，端到端加密并支持 MCP', '支持多币种钱包、未来支付规划、共享钱包协作、语义搜索、Passkey 登录、端到端加密及 MCP 的个人记账 Web 应用', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9a29a1b3f4817ff6028e372a', 'en', 'Show HN: Collaborative money tracker, E2E encryption, MCP', 'Hi HN, I&#x27;m Andrei. I built a money tracker for myself with everything I ever wanted from one.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_97e872c11a07bfe8f3cd5776', 'zh-CN', 'DineMidway：公平聚餐地点推荐', '输入成员位置，按距离、评分和筛选条件推荐对全组通勤公平的聚会餐厅，并可保存常约好友快速规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_97e872c11a07bfe8f3cd5776', 'en', 'DineMidway', 'Add everyone''s location and DineMidway suggests hangout spots that keep travel fair for the whole group, balancing distance, ratings and your filters. Save your regular crew once and plan your next outing in seconds.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a4dae6073c5c29377d009466', 'zh-CN', 'ChinaWander：AI 中国旅行规划器', '按天生成中国行程，含门票价格、营业时间、中文地址卡、高德导航与预约提醒，一次性付费19美元。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a4dae6073c5c29377d009466', 'en', 'ChinaWander: AI Trip Planner for China', 'Day-by-day China itineraries built to survive the actual trip: timed stops, real ticket prices and opening hours, a Chinese address card for every stop, one-tap Amap directions, and warnings for reservations you must book ahead.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b0168ebfe21fef70e1759099', 'zh-CN', 'TripZack 北阿坎德邦定制旅行', '提供北阿坎德邦定制旅游行程，覆盖德拉敦、穆索里、瑞诗凯诗、奈尼塔尔及四圣地朝圣等目的地。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b0168ebfe21fef70e1759099', 'en', 'TripZack', 'Uttarakhand is a beautiful destination known for its Himalayan landscapes, peaceful hill stations, spiritual destinations, wildlife, and adventure experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_defb58b7969ccc0beaf0b850', 'zh-CN', '喜马偕尔邦的雪景之美', '介绍喜马偕尔邦雪山、山谷与冬季旅行体验的内容', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_defb58b7969ccc0beaf0b850', 'en', 'the Snowy Beauty of Himachal Pradesh', 'Experience the peaceful charm of Himachal Pradesh with snow-covered mountains, beautiful valleys, scenic landscapes, and unforgettable winter travel experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac89c79bc691cd0dcff9dced', 'zh-CN', 'TempButton AI：医疗临时人员薪资与机构管理平台', '面向医疗临时人员（locums、旅行护士、CRNA）的工时、审批、薪资与开票平台，并为 staffing 机构提供 AI 后台与 CRM。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac89c79bc691cd0dcff9dced', 'en', 'TempButton AI', 'TempButton AI turns timesheets, approvals, payroll & invoicing into one simple flow — free for providers (locums, travel nurses, CRNAs), and a full AI back office + CRM for the agencies that staff them.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7f76134d84311fdc76da31a', 'zh-CN', '星际访客是外星探测器吗？', '模拟数百万条太阳系随机路径，评估三个星际天体接近行星或恒星的偶然性，检验其非自然起源假说。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d7f76134d84311fdc76da31a', 'en', 'Show HN: Are interstellar visitors alien probes?', 'There was a lot of debate about whether the 3 interstellar objects found might not be natural. Most of it cherry-picked a few oddities and claimed decisively, for or against. I don&#x27;t have a strong opinion, and don&#x27;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b291d1744668a9fd1db9c4bc', 'zh-CN', 'OneClick IT 咨询：AI 定制软件与自动化方案', '提供 AI 驱动的定制软件平台与智能自动化解决方案，专长旅游科技与企业级系统。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b291d1744668a9fd1db9c4bc', 'en', 'OneClick IT Consultancy', 'OneClick builds AI-powered software solutions and systems, from custom platforms to intelligent automation, that modernize how businesses run, with deep expertise in travel technology, custom software, and enterprise solutions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee02928abccf5de95e1120e5', 'zh-CN', 'Noma 旅行足迹与规划', '记录去过的地点并规划下一站，整理旅行历史、发现新目的地，支持 iPhone 与网页。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee02928abccf5de95e1120e5', 'en', 'Noma', 'Noma helps you keep track of the places you''ve visited and plan where you''re going next. Organize your travel history, discover new destinations, and keep your journeys in one place. Available for iPhone, with a web experience to explore.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e3ef58d5eccc111ce91f6a2d', 'zh-CN', 'TripEx - 旅行开销追踪 App', '面向 Android 的旅行费用追踪应用，支持结伴分账、语音记账与 PDF 导出。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e3ef58d5eccc111ce91f6a2d', 'en', 'TripEx - Travel expense tracker App', 'TripEx is a travel expense tracker for Android that makes managing trip budgets and splitting expenses with friends simple. Create groups, invite members using QR codes or joining codes, track shared expenses, and see who owes whom.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3ab6b1f53fdac66971aaead', 'zh-CN', '匈牙利旅行指南：布达佩斯与巴拉顿湖', '介绍匈牙利浴场文化，从布达佩斯历史浴场到乡间静修地，并提供2026年康养旅行规划建议。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3ab6b1f53fdac66971aaead', 'en', 'Hungary Travel Guide BudapesLake Balaton', 'Experience Hungary’s bathing culture, from historic Budapest bathhouses to peaceful countryside retreats, with practical tips to plan a refreshing wellness escape in 2026.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_27641ca60f33d6a7b7155250', 'zh-CN', 'ParikshaPath：印度住宿与出行服务平台', '印度住宿与出行服务市场，帮助用户查找酒店、旅馆、PG、青旅等住宿，房东可发布管理房源。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_27641ca60f33d6a7b7155250', 'en', 'ParikshaPath', 'ParikshaPath is a stay and travel services marketplace helping travellers discover hotels, guest houses, PGs, hostels and other services across India.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f605b0acd626aace53491e00', 'zh-CN', 'VoyaGo：旅行与城市探索平台', '一站式旅行与城市探索平台，支持照片发现地点、步行行程规划、多币种团体记账和地图导航。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f605b0acd626aace53491e00', 'en', 'VoyaGo', 'VoyaGo is an all-in-one travel and city exploration platform built independently for modern explorers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3677861eafa020d40a4a746e', 'zh-CN', 'PathChudo 行程规划工作台', '按天规划行程、管理预算与打包清单的旅行工作台，不提供预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3677861eafa020d40a4a746e', 'en', 'PathChudo', 'PathChudo is a trip workspace for day-by-day planning. Build itineraries with ordered stops, activities, and transfers; track budget vs actual spend; pack with a real checklist — one place before and during the trip. Not a booking site.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32eafb1100e81bc7cb663c13', 'zh-CN', 'Dayleaf 数字日记', '把手写文字与照片变成纸质质感的数字日记，支持多种版式、3D立体书、AI助写与导出分享', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_32eafb1100e81bc7cb663c13', 'en', 'Dayleaf', 'Dayleaf turns your words and photos into a digital journal that feels like paper. Write directly on the page, switch between daily, travel, collage and other layouts, and explore a 3D book with pop-up scenes and pull-tabs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_43138775d0b032ba9408e0f5', 'zh-CN', 'VANO MAPS 导航应用', '面向汽车与摩托车的浏览器导航应用，可比较路线、预估时间、路况与安全提示，并选择速度优先或平衡模式。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_43138775d0b032ba9408e0f5', 'en', 'VANO MAPS', 'VANO MAPS is a browser-based navigation app for cars and motorcycles. Compare routes using estimated travel times, traffic information, and available safety-related signals.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_120ff63e8e836a6d9b2b6cf4', 'zh-CN', 'PixSathi：免费在线照片与 PDF 工具', '提供护照照片制作、印度考试照片调整、PDF 与图片压缩及财务计算器等 40+ 免费在线工具，无需注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_120ff63e8e836a6d9b2b6cf4', 'en', 'PixSathi', 'Free online tools for everyone — Passport photo maker for US, UK, Canada & more, Indian exam photo resizer for SSC, IBPS, NEET, UPSC, PDF tools, image compressor, and 40+ finance calculators. 100% free, no signup.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4f83e7b424bf0ace189f7700', 'zh-CN', 'Tourist Score：城市旅行足迹评分', '在后台记录城市行程，生成个人地图与0–100游客路线契合度评分，发现途经地点并分享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4f83e7b424bf0ace189f7700', 'en', 'Tourist Score', 'Tourist Score records your city trip in the background, then reveals your personal map and a score from 0–100 showing how closely you followed the tourist trail. Discover places you passed and share your result.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f5b6914d3c683f97d0ee2406', 'zh-CN', 'FreeTools24x7：免注册无广告在线工具箱', 'FreeTools24x7 提供120+款无广告、免注册的浏览器工具，涵盖PDF、图片、二维码与计算器，文件不离开设备。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f5b6914d3c683f97d0ee2406', 'en', 'FreeTools24x7', 'Free online tools with zero ads and zero signup. 120+ tools: PDF merge/split/compress, image resize in KB, background remover, passport photo maker, UPI QR generator, GST calculator, JSON formatter and more.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6d04b575e84319d4949ed0f0', 'zh-CN', 'PamsBeyond', 'AI 旅行规划工作台，支持多城市路线规划、实时预算、签证规则查询与 PDF 行程导出', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6d04b575e84319d4949ed0f0', 'en', 'PamsBeyond', 'PamsBeyond is an all-in-one travel workspace combining AI guidance with practical trip planning. Map multi-city routes, track live budgets, check visa rules, auto-generate interactive charts, and export a complete PDF travel portfolio', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
