INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_520b79e06b42e06c1148f11b', 'zh-CN', 'EquiTrek：旅行行程与费用分摊助手', '一站式旅行伴侣：规划行程、共享账单公平分摊并简化还款，支持收据扫描、消费分析与旅行回忆。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_520b79e06b42e06c1148f11b', 'en', 'EquiTrek', 'Meet EquiTrek - your all-in-one travel companion! ✈️ Plan trips, organize itineraries, track shared expenses, split bills fairly, and simplify repayments — all in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc72c8f8e849f69391c7b286', 'zh-CN', 'PassportPhotoBox 护照签证照片制作', '浏览器端制作护照、签证及考试报名照片，支持人脸对齐、背景替换和打印排版，覆盖130多个国家。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dc72c8f8e849f69391c7b286', 'en', 'PassportPhotoBox', 'PassportPhotoBox is a privacy-first, client-side photo preparation and compliance platform for passport photos, travel visas, and government exam applications across 130+ countries.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb62b2a3a780b45bd82a5649', 'zh-CN', '【工具自荐】Travel Planning：用 Codex 把旅行需求变成可分享的水彩旅行手账', '大家好，自荐一个我持续开发的旅行规划 Skill / Codex 插件：Travel Planning。 它把旅行需求整理成一本有信息来源、可以在手机上阅读、分享和打印的水彩旅行手账。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb62b2a3a780b45bd82a5649', 'en', 'Travel Planning: A Codex Skill That Turns Trip Requirements into Shareable Watercolor Travel Journals', 'A Codex skill/plugin for trip planning that turns travel requirements into a watercolor-style travel journal with cited sources, readable on mobile and shareable or printable.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a056c24edf7309ec8a4fa4d', 'zh-CN', 'flightschange', '查询各航空公司改签政策、费用与票价规则，助你改签前了解适用条款', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0a056c24edf7309ec8a4fa4d', 'en', 'flightschange', 'Find airline flight change policies, fees, fare rules, and options. Understand what may apply before changing your flight or itinerary.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9637ce54f89606aaa13d7916', 'zh-CN', 'DueNest：跨境日期提醒工具', '面向跨境生活者的免费 Beta 提醒工具，可自行录入日期、选择时区与提醒间隔并查看日程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9637ce54f89606aaa13d7916', 'en', 'DueNest', 'DueNest is a free-beta reminder tool for people living across borders. Enter dates you have confirmed yourself, choose your timezone and reminder intervals, and review the schedule.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3d29bb40292ca0ef37240bb', 'zh-CN', 'Is This Legit? 可疑信息诈骗检测', '粘贴可疑邮件、短信或预订信息或上传截图，快速判断是否为诈骗，面向酒店、餐厅和租赁业主。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3d29bb40292ca0ef37240bb', 'en', 'Is This Legit?', 'Paste a suspicious email, text or booking message, or upload a screenshot, and get a plain-English verdict on whether it''s a scam.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f4efaa5bafe2380631db44a1', 'zh-CN', 'Tools for World：浏览器端免费文件工具集', '22 款浏览器端免费文件工具，支持 PDF 转换、按指定大小压缩、抠图、多语 OCR、护照照片等，文件不上传、无水印、无次数限制。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f4efaa5bafe2380631db44a1', 'en', 'Tools for World', '22 free tools for everyday files: PDF to Word, compress PDF or images to an exact size (100KB, 200KB…), background remover, OCR in 14 languages, passport photos for 7 countries, HEIC to JPG, QR codes and more.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1eed537a574cbede6756ee45', 'zh-CN', 'Yotemy：出发时间倒计时', '以出发时刻为准的倒计时应用：依据路程与准备时长倒推提醒，主屏小组件按紧迫程度变色，自动同步日历并支持共享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1eed537a574cbede6756ee45', 'en', 'Yotemy', 'Yotemy counts down to when you need to leave, not when your plan starts. It works backward from travel time and the prep time you set, and a home-screen widget changes color as it gets close: white when there''s plenty of time, green to get…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_074183be45346c441332204a', 'zh-CN', 'WedLoop：AI 婚礼短信礼宾', 'AI 短信礼宾自动回答婚礼宾客的问题，从婚礼网站提取答案并发送重要提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_074183be45346c441332204a', 'en', 'WedLoop', 'Your guests will forget everything. The website. The venue. The hotel block. The RSVP deadline. WedLoop is an AI-powered SMS concierge that answers their questions automatically so they text WedLoop, not you.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f71b8b390d191698cde14bd', 'zh-CN', 'Bharat Travels Chandigarh 昌迪加尔 Tempo Traveller 租赁', '昌迪加尔提供9至26座豪华Tempo Traveller出租，支持按公里或日租，覆盖马纳利、西姆拉及外地包车游。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f71b8b390d191698cde14bd', 'en', 'Bharat Travels Chandigarh', 'Looking for the best tempo traveller in Chandigarh? Book luxury tempo traveller hire & rent starting @ ₹25/km or ₹5,000/day. 9 to 26 seater & Urbania tempo traveller in Chandigarh to Manali, Shimla & outstation tours.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_30fee9c63df1ca8f61a1f91a', 'zh-CN', 'Agents4 Fitness：AI 私教定制健身计划', '115 位专业 AI 教练，按目标与身体情况生成训练营养计划并动态调整', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_30fee9c63df1ca8f61a1f91a', 'en', 'Agents4 Fitness', 'Pick from 115 specialist AI coaches (GLP-1 strength, postpartum, HYROX, menopause, CGM-guided and more), each built on a real coaching methodology.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_212f93f7da2ca2689f812354', 'zh-CN', 'Youtubers Map 视频地图', '在地图上探索 YouTuber 的视频，发现国家、城市与旅行统计。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_212f93f7da2ca2689f812354', 'en', 'Youtubers Map', 'Explore their videos on the map, discover countries, cities and travel stats', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a4502f99b87ac5b131b051b', 'zh-CN', 'TripPlano 旅行行程规划工具', '将目的地生成逐日行程，核验地点与营业时间，支持多城路线、调整顺序及导出 PDF。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6a4502f99b87ac5b131b051b', 'en', 'TripPlano', 'Meet the new TripPlano: turn a destination into a day-by-day itinerary with real places checked on Google Maps, opening hours for your travel dates, travel times and an interactive map.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_30002a38209ce6fd28620bab', 'zh-CN', 'Fortrip Desk：旅行工作台', '导入 WhatsApp 聊天，查看有据可查的客户偏好，并以任务看板配合顾问 Agent 处理每项请求。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_30002a38209ce6fd28620bab', 'en', 'Fortrip Desk — Your travel workspace', 'Import WhatsApp chats, review evidence-backed client preferences, and work each request as a board of tasks with an advisor agent.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34b7713fcc8da086a83208a7', 'zh-CN', 'TigerSight India 印度野生动物与金三角之旅', '规划印度野生动物与金三角私人虎猎游，串联德里、阿格拉和斋浦尔景点，可按兴趣定制行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34b7713fcc8da086a83208a7', 'en', 'tigersightindia', 'Plan an Indian wildlife and Golden Triangle tour combining private tiger safaris with Delhi, Agra and Jaipur’s iconic sights.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8d216312dd38320855d7ca86', 'zh-CN', 'Traserbas 巴塞尔机场出租车服务', 'Traserbas 提供巴塞尔机场至市区、酒店及瑞士各地的固定价格专车接送，含专业司机与门到门服务。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8d216312dd38320855d7ca86', 'en', 'Taxi Basel Airport Service', 'Traserbas offers reliable Taxi Basel Airport services for convenient transfers to and from EuroAirport Basel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7994b5077f5cab2bbe1b4aeb', 'zh-CN', 'GreedyArt AI 照片模板', 'GreedyArt 提供现成 AI 照片模板，选风格、传自拍，约一分钟生成新造型、头像或贴纸照片。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7994b5077f5cab2bbe1b4aeb', 'en', 'GreedyArt', 'GreedyArt is a catalog of ready-made AI photo templates. No prompts, no settings: choose a look (new outfit, another era, dating photos, anime avatar, travel shots, sticker packs), upload one selfie and get your photos in about a minute.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_46aabaab9a05d822fdc18c44', 'zh-CN', 'Trawex 观光活动 API', '面向旅游企业，连接观光供应商并接入景点游览与活动预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_46aabaab9a05d822fdc18c44', 'en', 'Trawex Sightseeing API', 'Trawex Sightseeing API helps travel businesses integrate sightseeing tours, tourist attractions, excursions, and activities into their online travel booking platforms.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9155119ceaa8523c6cb8910b', 'zh-CN', 'Atlas & Indus Linen 酒店纺织品供应', '面向酒店、度假村和传统庭院住宅供应床品、毛巾、浴袍等酒店布草，支持定制尺寸、刺绣与字母标识。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9155119ceaa8523c6cb8910b', 'en', 'ATLAS & INDUS LINEN CO.', 'Atlas & Indus Linen supplies hospitality textiles for hotels, resorts, and riads. Its range includes hotel bedding, fitted sheets, duvet covers, pillowcases, blankets, bath towels, bath mats, and bathrobes.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_aa80627ee4a5b67aa3320a03', 'zh-CN', 'CamStory：GPS 照片与笔记', 'GPS 相机与照片记录应用，可为照片添加位置、笔记、人物、日期时间和 GPS 信息，并支持地图浏览与 PDF 报告。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_aa80627ee4a5b67aa3320a03', 'en', 'CamStory: GPS Photo & Notes', 'CamStory is a GPS camera and photo documentation app that helps you capture photos with location, notes, people, memories, date, time, and GPS information.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b80ff14e33e2cfb77ff3c79f', 'zh-CN', 'GoSyria.net 旅行平台上线', 'GoSyria.net 提供航班搜索比价与旅行规划，帮助用户便捷探索和安排行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b80ff14e33e2cfb77ff3c79f', 'en', 'WE''RE LAUNCHING GOSYRIA.NET!', 'We’re excited to introduce **GoSyria.net** — a new travel platform built to make discovering and planning your next journey easier, simpler, and more convenient. ✈️ **Search and compare flights** from multiple travel providers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a9881db1d9b39ca2690f71c0', 'zh-CN', 'EtherPK 为 Markdown 笔记加入地点地图与 wikilink 可视化', 'EtherPK 是 Markdown 与 wikilink 驱动的 PKMS，新增地图功能，可把笔记中的地点按概念聚合，并支持手动、邮编或地名添加图钉与路线。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a9881db1d9b39ca2690f71c0', 'en', 'Show HN: Link and visualise places in your notes with Markdown and wikilinks', 'EtherPK (our markdown and wikilink based PKMS) now has maps. Lots of the concepts in a PKMS relate to places in the physical world, and for me that&#x27;s often trips and travel. For example, I keep a list of places I&#x27;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b1e7a970b2206dc1b3978b4e', 'zh-CN', '孟买至巴塞罗那航班指南', '查询孟买至巴塞罗那航班路线、票价、航司信息与旅行提示，轻松规划行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b1e7a970b2206dc1b3978b4e', 'en', 'Trip with the Best Mumbai to Barcelona', 'Find Mumbai to Barcelona Flights with route options, airfare insights, airline details, travel tips and essential information to plan your journey with ease.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c0c233f096cebcb25cd27a60', 'zh-CN', 'Pet Travel Planner：宠物出行规划', '汇总航空公司宠物政策、国家入境要求与可地图查看的酒店，并集中保存宠物档案和出行信息，支持 iPhone 和 iPad。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c0c233f096cebcb25cd27a60', 'en', 'Pet Travel Planner', 'Taking your dog or cat on a trip? Bring the planning into one place. Browse airline pet policies, check country entry requirements, search hotels with map results, and keep your pet’s profile and key travel details together.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c3249062831b51f16ef7c6d2', 'zh-CN', 'BeenThere：旅行安全指数 iOS 应用', '提供街区安全指数、实时安全提醒及独自与女性旅行者评分的 iOS 旅行安全应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c3249062831b51f16ef7c6d2', 'en', 'BeenThere', 'After finishing #15 on Product Hunt in May, we built the official BeenThere iOS app from scratch! Most travel apps tell you where to go, but never how safe the neighborhood is.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
