DELETE FROM product_content WHERE product_id IN ('prd_e0cbec954619c91038ba75a3','prd_e01e7cf80de456abbfd0680e','prd_05ab07249629c6eecccb5da6','prd_ec2afd07e07420afa00911c4','prd_0016cd529ae8696b01d76485','prd_1823d66f3ede338ad61c9eca','prd_52e442fcb5391e05305a347a','prd_4d4d560ce1b0771dfb1d8e1a','prd_686b94de261ac8ac7967adcf','prd_3d478b7a498666ce27d4dd87','prd_70a6b7c4092433e189bcee2e','prd_8127edc7847324e67222a617','prd_8a021e527d7c033cd7e1e7b6','prd_a7e5c083ea6f1e6790a014e4','prd_9152fc94e9d8cbe35f7aa9ec','prd_1e1169085d04a94ba0b085f8','prd_c63f5efaaf7a8f822097a18b','prd_e0a7e13f9392bd639a3c1bbe','prd_da267f11c0ac7ba06686d496','prd_bbc4bd66b0220338c0af27e8','prd_e82e54043cfa65182a3f9f6c','prd_012d92685063ca6887f8fc7a','prd_2f689c27e6f3e6eecc5fda81','prd_3e274de787c58cca45d6ec97','prd_2c1c3128197e59a9487e8df7') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_e0cbec954619c91038ba75a3', 'zh-CN', 'Lodge Deck 酒店管理平台', 'AI 驱动的酒店管理平台，整合预订、客房、前台、客房清洁、住客记录、账单与业绩分析。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e0cbec954619c91038ba75a3', 'en', 'Lodge Deck', 'Meet Lodge Deck, a smarter way to run hospitality. Lodge Deck is a modern, AI-powered hotel management platform designed to simplify operations and help hospitality teams deliver exceptional guest experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e01e7cf80de456abbfd0680e', 'zh-CN', 'SmartWanderTrip：AI 多国旅行规划工具', 'AI 辅助的多国旅行规划器，可比较航班酒店、协调接送与活动，灵活调整行程，并导出 PDF 和二维码分享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e01e7cf80de456abbfd0680e', 'en', 'SmartWanderTrip', 'SmartWanderTrip is an AI-assisted travel planner designed for complex, multi-country journeys. Explore up to four itinerary styles, compare real flight and hotel options, coordinate transfers and activities, and adjust stops or dates witho…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_05ab07249629c6eecccb5da6', 'zh-CN', 'Flagfolio：数字旅行护照', '免费数字旅行护照，标记到访国家、收集国旗并分享旅行足迹，无需注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_05ab07249629c6eecccb5da6', 'en', 'Flagfolio', 'Flagfolio is a free digital travel passport that turns your adventures into something you can collect and share. Add a flag for every country you''ve visited, celebrate your travel milestones, and create a visual record of your journey.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ec2afd07e07420afa00911c4', 'zh-CN', 'Serin：个人隐私雷达', '约60秒扫描出租屋或酒店房间，用蓝牙、Wi-Fi与红外检测隐藏摄像头、追踪器和智能眼镜，本地处理无需账号。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ec2afd07e07420afa00911c4', 'en', 'Serin: Personal Privacy Radar', 'Serin scans a rental or hotel room for hidden cameras, Bluetooth trackers and smart glasses in about 60 seconds, using Bluetooth, Wi-Fi and the infrared camera. On-device, no account. Free on iPhone and Android; Pro is $5.99 one-time.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0016cd529ae8696b01d76485', 'zh-CN', '希望找到志同道合的人', '一个个人交友页面，分享旅行、音乐与安静夜晚等兴趣，邀请有共鸣的人到网站打招呼。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0016cd529ae8696b01d76485', 'en', 'Hoping to Find Someone Who Shares My', 'I love travel, music, and quiet evenings (edit to match you). If you share any of that, come say hi on my website. Ads keep the site running, so allowing them is appreciated but never required.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1823d66f3ede338ad61c9eca', 'zh-CN', 'Merakk 油漱口旅行装', '便携油漱口旅行装，含10袋10ml植物精油混合，有薄荷、丁香、印楝等，用于日常口腔护理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1823d66f3ede338ad61c9eca', 'en', 'Merakk', 'Discover Merakk Oil Pulling Signature Collection – Daily Swish Travel Packets, a convenient oil-pulling blend for your daily oral care routine.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_52e442fcb5391e05305a347a', 'zh-CN', 'Cityhoppd：城市旅行日记', '记录去过的城市，添加评分与私密点评，地图随行程填充，可分享的免费网页应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_52e442fcb5391e05305a347a', 'en', 'Cityhoppd', 'A travel diary for the cities you''ve been to. Log a trip with just a city and a rating, and add the honest version if you feel like it. Your map fills in as you go. Trips and reviews stay private until you share them. Free, in the browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d4d560ce1b0771dfb1d8e1a', 'zh-CN', 'nexARound：AI 智能旅游伴侣', 'AI 智能旅游伴侣，支持实时 AR 地标识别、地点推荐与缓存，并配有个人 AI 旅行助手 Neva。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d4d560ce1b0771dfb1d8e1a', 'en', 'nexARound', 'nexARound is an AI-powered smart tourism companion featuring real-time AR landmark identification, a location recommendation engine, location caching, and Neva, your personal AI travel companion.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_686b94de261ac8ac7967adcf', 'zh-CN', 'Ai Global Explorer：AI 出游助手', '一款 AI 旅行与体验平台，首发实时 AI 出游助手，可按位置、天气和氛围推荐行程，并提供应用内导航、实时改道和可分享的出游故事卡片。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_686b94de261ac8ac7967adcf', 'en', 'Ai Global Explorer', 'Ai Global Explorer is an all-in-one AI travel and experience platform. This Launch Edition reveals our first feature: a real-time AI agent for spontaneous outings.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d478b7a498666ce27d4dd87', 'zh-CN', 'VisaPicGo：美国护照签证照片制作', '将手机自拍快速制作成符合美国护照、签证或绿卡要求的照片，承诺可受理，否则全额退款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d478b7a498666ce27d4dd87', 'en', 'VisaPicGo', 'Turn any phone selfie into a compliant US passport, visa, or Green Card photo in 2 minutes. Guaranteed acceptance or full refund.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_70a6b7c4092433e189bcee2e', 'zh-CN', 'NextStop.city：旋转地球探索城市街景', '旋转3D地球选点，观看街景视频并收听当地电台，提前感受城市氛围。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_70a6b7c4092433e189bcee2e', 'en', 'NextStop.city', 'I built nextstop.city to inspire people to travel and help them discover places they might never have considered. Just spin the 3D globe, pick a spot, and instantly drop into a POV street video synced with a live local radio station.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8127edc7847324e67222a617', 'zh-CN', 'MYUMRAH 2026年9月富尔达出发副朝之旅', 'MYUMRAH 提供2026年9月自富尔达出发的副朝套餐，含机票、签证、麦加与麦地那酒店、早餐、接送及5L Zamzam 水。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8127edc7847324e67222a617', 'en', 'Umrah September 2026 ab Fulda', 'Buchen Sie Ihre Umrah Reise September 2026 ab Fulda mit MYUMRAH UG. Flug, Visum, Hotel in Mekka & Medina, Frühstück, Transfer und 5L Zamzam inklusive. Jetzt Platz sichern!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8a021e527d7c033cd7e1e7b6', 'zh-CN', 'Go!ChouChou：宠物旅行社交平台', '连接带宠物旅行者的社交平台，可寻找同路人、交流攻略并分享旅程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8a021e527d7c033cd7e1e7b6', 'en', 'Go!ChouChou', 'Go!ChouChou connects pet owners planning local, intercity, and international adventures. Find others on the same route, exchange travel tips, and share your journey.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a7e5c083ea6f1e6790a014e4', 'zh-CN', 'VandraQuest：AI 旅行指挥中心', 'AI 旅行指挥中心：用自然语言描述即可生成行程，预订确认自动归档，航班实时提醒，可记录并分享行程故事卡。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a7e5c083ea6f1e6790a014e4', 'en', 'VandraQuest', 'VandraQuest is a travel command center. Describe a trip in plain English and an AI copilot builds the itinerary. Forward your booking confirmations and they file themselves into the right trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9152fc94e9d8cbe35f7aa9ec', 'zh-CN', 'SPOTIQ：地点发现与旅行行程规划', '发现附近及全球优质地点，查看天气、比较低价航班并生成逐日旅行行程，支持清单保存与分享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9152fc94e9d8cbe35f7aa9ec', 'en', 'SPOTIQ', 'SPOTIQ helps you find the best places near you or anywhere in the world, then turn them into a trip.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1e1169085d04a94ba0b085f8', 'zh-CN', 'OpenAI Codex 28 天重置挑战日历追踪器', '追踪 OpenAI Codex 28 天重置挑战的日历，实时更新每日改进或重置，回填 2025 年 4 月以来记录，并展示准时率图表及 ResetAlerts 提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1e1169085d04a94ba0b085f8', 'en', 'Show HN: A calendar tracker for OpenAI''s 28-day Codex reset challenge', 'OpenAI recently announced a 28-day reset challenge: each day, either a "clear improvement" or a usage reset. I built this calendar to track the challenge. It updates throughout the day as updates become available.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c63f5efaaf7a8f822097a18b', 'zh-CN', 'PixPassport 英国护照照片制作', '在线制作符合英国 GOV.UK 与 HMPO 要求的护照照片，上传手机照片即可检测并下载。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c63f5efaaf7a8f822097a18b', 'en', 'PixPassport', 'Make a UK passport photo online for GOV.UK applications and renewals. Upload a phone photo, check it against HMPO guidance and download', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e0a7e13f9392bd639a3c1bbe', 'zh-CN', 'Vrolu 实时航班追踪', '输入航班号、城市或航司即可实时追踪航班，无需账号，支持共享看板、浏览器实时链接与锁屏航班动态。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e0a7e13f9392bd639a3c1bbe', 'en', 'Vrolu - Live Flight Tracker', 'Powerful and simple: a serious flight tracker anyone can pick up in seconds. Type a flight number, a city or an airline into one field and you''re tracking, with no account needed.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_da267f11c0ac7ba06686d496', 'zh-CN', 'OneQR：AI 与手动旅行规划', '将 AI 智能体与手动旅行规划统一整理在一处。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_da267f11c0ac7ba06686d496', 'en', 'OneQR', 'AI agent and manual travel planning, unified and organized in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bbc4bd66b0220338c0af27e8', 'zh-CN', 'Lavvi：公共洗手间查找工具', 'Lavvi 帮你查找公共洗手间，并在前往前查看清洁度与可用性，让出行更省心。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bbc4bd66b0220338c0af27e8', 'en', 'Lavvi', 'Lavvi helps you find public washrooms and check their cleanliness and usability before you visit. Whether you''re travelling, exploring a new city, or out for the day, Lavvi makes it easier to find a washroom when you need one.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e82e54043cfa65182a3f9f6c', 'zh-CN', 'Focus Hotel：把专注时间变成像素旅馆', '把专注变成像素旅馆：开启专注会话即屏蔽干扰应用，坚持越久赚取 Focusines，兑换家具、服装与新房间，还能串门看别人的房间、Habbo 式边聊边专注。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e82e54043cfa65182a3f9f6c', 'en', 'Focus Hotel', 'Focus Hotel turns focus time into a place. Start a session, block distracting apps, and every minute you stay focused earns Focusines to spend on furniture, outfits and new rooms in your isometric pixel hotel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_012d92685063ca6887f8fc7a', 'zh-CN', 'thefreetools：浏览器免费计算与转换工具集', '浏览器内免费计算与转换工具：GPA、回历与公历日期、年龄、增值税、支票金额大写、护照照片制作，支持四种语言，免注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_012d92685063ca6887f8fc7a', 'en', 'thefreetools', 'Free calculators and converters that run in your browser: GPA, Hijri–Gregorian dates, age, VAT, number-to-words (cheques) and a passport photo maker. In English, Arabic, Spanish and French.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f689c27e6f3e6eecc5fda81', 'zh-CN', 'Web Rewinder：网页历史时间轴', '拖动时间轴查看任意网页在 Internet Archive 的存档版本，点击图标即可浏览该页面的历史快照。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2f689c27e6f3e6eecc5fda81', 'en', 'Web Rewinder', 'Travel through the history of any webpage. Drag a timeline to see its archived versions from the Internet Archive.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3e274de787c58cca45d6ec97', 'zh-CN', 'MyToolkitt：浏览器端免费小工具集', '免费浏览器小工具集，支持二维码、短链、图片压缩和PDF合并，文件全程本地处理不上传。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3e274de787c58cca45d6ec97', 'en', 'MyToolkitt', 'MyToolkitt is a growing set of free, browser-based tools for the small jobs that come up in a working day: making a QR code, shortening a link, compressing a photo under a size limit, merging a few PDFs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2c1c3128197e59a9487e8df7', 'zh-CN', 'Pizazoo 截图整理与文字搜索', '本地识别截图文字并自动分类为收据、聊天、代码、旅行等，支持关键词搜索、分享保存与隐私打码', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2c1c3128197e59a9487e8df7', 'en', 'Pizazoo for iPhone and iPad', 'Pizazoo started as a screenshot organizer for Mac. Now it is on iPhone and iPad. It reads the text in every screenshot and files each one into categories like Receipts, Chats, Code and Travel, all on your device.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
