INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_8d4e3a340782db138ad62dc8', 'zh-CN', 'ExplorersMap：终身旅行足迹地图', '终身旅行足迹记录地图，可标记国家、地区与地点，导入 Google Maps 时间线并生成旅行护照，还含地理游戏。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8d4e3a340782db138ad62dc8', 'en', 'ExplorersMap', 'ExplorersMap is a lifetime travel log that goes deeper than "countries visited": mark the 199 countries, 4,596 regions and 90,000+ places you have been, all on one map.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b493f1221326b13eca9012de', 'zh-CN', 'TripLala', '一站式旅行规划应用，整合行程、打包、心愿单、纪念品、花费与待办，支持多人协作编辑。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b493f1221326b13eca9012de', 'en', 'TripLala', 'TripLala grew from trips with my wife. Every "I wish it was all in one place" and "I wish it could do this" went in. Planning a trip is never just the itinerary.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8de46aca40849279aeeb49b0', 'zh-CN', 'Album Map：照片地图视频故事', '将照片、片段、留言和地点制作成动画地图视频故事，支持访客链接收集素材及邀请视频礼物。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8de46aca40849279aeeb49b0', 'en', 'Album Map', 'Album Map turns photos, clips, messages, and locations into video stories. Connect travel stops on animated maps, collect contributions through a guest link, or create an invitation and group video gift.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4306f34ee26f2ca6d6464342', 'zh-CN', 'Groundhopper：赛事记录与球场收集', '记录观赛、收集球场并扩展地图，生成旅行海报与社交视频，支持 AI 行程规划。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4306f34ee26f2ca6d6464342', 'en', 'Groundhopper', 'Log matches, collect stadiums, watch your map grow. Print-ready journey posters, social video export, AI trip planning — for football and every sport you travel for.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8b89e759a5f31d8ec61baeff', 'zh-CN', 'VolitionDrive：规划最省钱的加油停靠点', '根据车辆续航与实时油价，为公路旅行规划跨境的低成本加油停靠点，并可导出至地图导航。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8b89e759a5f31d8ec61baeff', 'en', 'VolitionDrive', 'Find the cheapest fuel nearby and plan cost-optimal refueling stops on any road trip. VolitionDrive uses a smart algorithm and real-time Open Data to calculate exactly where to stop based on your car''s specific range.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dac25cee7f53c9d22ec648c6', 'zh-CN', 'Firantey：数字游民旅行博客', '面向数字游民的位置旅行博客，分享真实地点体验并发现附近隐藏好去处。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dac25cee7f53c9d22ec648c6', 'en', 'Firantey', 'Firantey is a location-based travel blog for nomads. Share what a place is really like and help fellow travelers discover hidden gems nearby.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed32bae0a22f5e1e2f620742', 'zh-CN', 'Duo Cards: Crazy 8s & Mau Mau 数字卡牌', '免登录数字卡牌游戏，扫码即入私人房，支持8人局与离线AI对战', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed32bae0a22f5e1e2f620742', 'en', 'Duo Cards: Crazy 8s & Mau Mau', 'Most digital card games force slow logins, push pay-to-win microtransactions, and cap lobbies at 4 players.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2c71d1408697244c3fba03e', 'zh-CN', 'Camper Toolkit PRO 露营车工具包', '面向房车生活与DIY改装的离线工具，提供太阳能和电池计算、接线图、道路应急及旅行记录。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2c71d1408697244c3fba03e', 'en', 'Camper Toolkit PRO', 'Build and travel with confidence. Camper Toolkit Pro is the ultimate offline companion for vanlife and DIY builds. • Smart Calculators: Plan your solar MPPT setups, battery runtime & energy consumption.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2de5b335c544487c34aca6e7', 'zh-CN', 'Hackerrecon Toolkit & Terminal：安全侦察与实用工具套件', '39+ 款客户端工具套件，含网站安全评分、AI 内容检测及 22 款网络安全侦察工具。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2de5b335c544487c34aca6e7', 'en', 'Hackerrecon Toolkit & Terminal', 'Explore 39+ client-side tools: 17 Utilities (Website Security Scorecard, AI Content Detector, Salary Slips, Percentage, EMI, GST, Currency, Unit, Age, Time Zone, ID Card, Business Card, Passport Photo, Hotel Bill, Receipts, Quotations) alo…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_23c785c5c03c30a164125c5e', 'zh-CN', 'Focus Train 专注列车', '将番茄钟专注时间变成日本列车旅程，完成学习或工作任务推进路线，解锁城市明信片、收藏印章并记录旅行日志。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_23c785c5c03c30a164125c5e', 'en', 'Focus Train', 'Turn your focus into a journey across Japan. Focus Train is a gamified Pomodoro app where every study or work session moves your train toward a new destination.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_329638c1e196583bdde115bd', 'zh-CN', 'ZECOHO：印多尔独立酒店直订平台', 'ZECOHO汇集印多尔认证独立酒店，支持直接预订，可提前联系酒店，酒店无需支付每笔佣金。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_329638c1e196583bdde115bd', 'en', 'ZECOHO', 'ZECOHO lists verified independent hotels in Indore and lets you book them direct. Hotels pay ZECOHO no per-booking commission, so they can offer a lower room price.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6600c9fa502c3bfdd86293d4', 'zh-CN', 'Asfur 旅行应用', '整合旅行套餐、航班预订与阿联酋活动的旅行平台，提供 iOS 和 Android 应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6600c9fa502c3bfdd86293d4', 'en', 'Asfur APP', 'Asfur brings travel packages, flight booking and UAE activities into one travel platform, with mobile apps for iOS and Android. Explore destinations and travel offers, and contact the Asfur team for support.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_478ab1975838bd9c1b1144ad', 'zh-CN', 'HelloRoam 旅行 eSIM', '购买覆盖185+国家的预付费旅行eSIM，低至1.03美元，无漫游费，扫码即时激活。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_478ab1975838bd9c1b1144ad', 'en', 'HelloRoam', 'Official HelloRoam site. Buy prepaid travel eSIM plans for 185+ countries from $1.03. No roaming fees, instant QR activation.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_600e2e0aa6b33af264329878', 'zh-CN', 'Scappa：一站式旅行规划工具', 'Scappa 把住宿、活动、餐厅、打包清单和旅行证件集中到一处，帮助用户从最初想法规划到旅程结束。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_600e2e0aa6b33af264329878', 'en', 'Scappa', 'Planning a trip today means juggling ten different apps: one for where to stay, another for things to do, a notes file for restaurants, a packing list somewhere else, and screenshots of your travel documents buried in your camera roll.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a8ce77571f40cf8f4f2e5d59', 'zh-CN', 'Merakk 玫瑰补水口气喷雾（限量版）', '便携玫瑰味口气喷雾，10ml 小巧装，饭后、办公或旅行时随时清新口气', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a8ce77571f40cf8f4f2e5d59', 'en', 'Merakk', 'Enjoy a refreshing floral experience with Merakk Hydrating Breath Spray – Rose (Limited Edition).', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_95cfdd53e04698d1428d71b1', 'zh-CN', 'VerbX Travel 旅行翻译应用', '支持语音、拍照、文字与离线模式的旅行翻译应用，含目的地短语手册和文化提示。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_95cfdd53e04698d1428d71b1', 'en', 'VerbX Travel App', 'VerbX Travel helps travellers communicate across languages by voice, camera, text, and offline mode.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_68025d95e0eea51a15ccfae6', 'zh-CN', '酒店 AI 直连预订：无需 MCP 的实时房态', '让 AI 代理在开放网页上读取酒店实时房价与空房，并生成预订链接交给用户，无需 MCP 或连接器。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_68025d95e0eea51a15ccfae6', 'en', 'Show HN: This hotel is hella AI-ready. Book directly from AI without MCPs', 'Hey guys! Excited to show how we were able to get AI agents to read a hotel&#x27;s live price and availabilities and even create the booking link to hand-off to the user. Get this, all working WITHOUT MCPs or connectors.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2983b9423e84180cfa53249', 'zh-CN', 'KRAD Global：喜马拉雅徒步与全球旅行', '德哈拉登旅行公司，提供喜马拉雅徒步、国内假期和国际跟团游，配有认证向导。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e2983b9423e84180cfa53249', 'en', 'KRAD Global', 'KRAD Global is a leading travel company in Dehradun offering Himalayan treks, domestic holidays, and international tours with certified guides.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fdb50e6dacf68362601bf4e1', 'zh-CN', 'Route 66 旅行指南', '免费 Route 66 行程规划器，选两座城镇即可生成逐日路线与沿途景点，可收藏并导出 PDF。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fdb50e6dacf68362601bf4e1', 'en', 'Route 66 Trip Guide', 'Free Route 66 trip planner. Pick two towns and get a day-by-day plan with the best stops in between: neon motels, ghost towns, diners and roadside giants like Cadillac Ranch. 800+ stops in 8 states on one map, filtered by kind.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5bd1cd3eee8fae839e8a54c5', 'zh-CN', 'goholi.si：AI 逐日旅行行程规划', '输入住宿、日期、预算与出行偏好，即可生成逐日 AI 模拟行程，并支持社区分享、协作规划与本地向导升级。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5bd1cd3eee8fae839e8a54c5', 'en', 'goholi.si', 'Goholi.si lets you drop in your stay details—dates, mobility needs, budget, and travel style—and instantly receive a genuine, day-by-day AI-simulated itinerary for any destination on Earth.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5f803f9d82c352125fdd00c1', 'zh-CN', 'SkyyTrust：旅客评价与互助社区', '面向全球旅客的独立社区，分享真实航司评价、反馈航班问题并交流出行经验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5f803f9d82c352125fdd00c1', 'en', 'SkyyTrust', '✈️ Meet SkyyTrust a new independent community built for travelers. Share honest airline reviews, report flight problems, ask questions, and connect with fellow passengers worldwide.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_732d1f69e278b9b14e9a936d', 'zh-CN', 'TripsCircle 旅行发现与规划平台', 'TripsCircle 是可选 AI 的旅行发现与规划平台，帮助发现目的地、小众景点并生成个性化行程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_732d1f69e278b9b14e9a936d', 'en', 'TripsCircle', 'TripsCircle is an AI-optional travel discovery and planning platform that makes exploring the world easier.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_66747d562cf76d029a052d0a', 'zh-CN', 'B2B AI SOFT：AI 销售线索转化助手', '面向服务型企业的 AI 销售助手：全天候回复询盘、理解意图、按 HOT/WARM/LOW 分级线索，保留 CRM 上下文并自动跟进，将合格客户移交人工。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_66747d562cf76d029a052d0a', 'en', 'B2B AI SOFT', 'B2B AI SOFT turns incoming leads into qualified sales opportunities. It replies 24/7, understands intent, scores leads as HOT/WARM/LOW, keeps CRM context, follows up automatically, and hands qualified prospects to a manager.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a2ffdee104c720645e621ab', 'zh-CN', 'Merakk 玫瑰保湿口气喷雾', 'Merakk 玫瑰保湿口气喷雾，10ml 便携装，提供温和花香型日常口腔清新体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a2ffdee104c720645e621ab', 'en', 'Merakk', 'Enjoy a refreshing floral experience with Merakk Hydrating Breath Spray – Rose, a convenient oral care product designed for everyday freshness. Its compact 10ml bottle makes it easy to carry in your handbag, pocket or travel kit.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6ad6b7a69a11e493fd49df7d', 'zh-CN', 'Minetra：矿业劳务用工 AI 平台', '面向矿业与劳务用工的 AI 平台，覆盖人员匹配、排班、动员、合规、差旅、工时与薪资。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6ad6b7a69a11e493fd49df7d', 'en', 'Minetra', 'Minetra is the AI-powered workforce platform for mining and labour hire - from a client''s request to boots on site: AI matching, smart rostering, mobilisation, compliance, travel, timesheets and payroll in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
