DELETE FROM product_content WHERE product_id IN ('prd_8e4e9430f0ba4db4e36e28bb','prd_a0f5e31cc275dbaa72b11b64','prd_be3b07f34aa1ec313f37529a','prd_f066e8aa860658206588b67b','prd_004f878ea9b106da22685e95','prd_183ca949cd6c715638d39d54','prd_84d86e41de24fbaa212abfb4','prd_2ef81d0d5be91fdf60b17c78','prd_1c3965d722e6fbe1f634e31d','prd_34d0dac96fe27cb2c6bf627a','prd_df60c4884488f5d227834fa0','prd_5b52d12a4081a4b0e8a373e1','prd_3dc875ca427b1d0f82c3a5ab','prd_64838bc909cfb5635f409c58','prd_d1ad1a6d410150f477f637a4','prd_bde822adb1566a12b670e1c9','prd_7ee2baf68e6da5dee4cf6d6c','prd_7a65441f9032086ae6af5474','prd_54bc9adc323717d4a96ba4f7','prd_0dabbc7e48b2b59bdab6dbf0','prd_5bc87e4292cd624abc6c2e47','prd_1aa1ee3f7c8580a210fb1765','prd_25e129c4529595f672a84298','prd_7cdd807d9b796958c5db292f','prd_9472fe9263670d56417a7440') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_8e4e9430f0ba4db4e36e28bb', 'zh-CN', 'Infovion：印度学校一体化管理平台', '一站式印度学校管理平台，涵盖招生、收费、考勤、成绩单、校车追踪与门禁登记', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8e4e9430f0ba4db4e36e28bb', 'en', 'Infovion', 'Infovion runs an entire Indian school from one login: admissions, fee receipts, attendance, report cards, TC/LC in English, Marathi or Hindi, transport with live bus tracking, hostel and gate register. Portals for every role.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a0f5e31cc275dbaa72b11b64', 'zh-CN', 'Ranchi Portal 免费在线工具集', '面向印度政府考试考生的100+免费在线工具，含证件照调整、年龄放宽与资格计算。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a0f5e31cc275dbaa72b11b64', 'en', 'Ranchi Portal Free Tools', 'Ranchi Portal Free Tools is a collection of 100+ free online tools for Indian government job aspirants: Sarkari Photo Studio (passport photo resizer for SSC/UPSC specs), Age Relaxation Calculator, EWS/Domicile/Caste eligibility checkers, N…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_be3b07f34aa1ec313f37529a', 'zh-CN', 'Merakk 补水薄荷口气喷雾（限量版）', '便携薄荷口气喷雾，可放入口袋、手袋或旅行包，随时清新口气。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_be3b07f34aa1ec313f37529a', 'en', 'Merakk', 'Enjoy convenient freshness with Merakk Hydrating Breath Spray – Mint (Limited Edition). Designed for people who want a refreshing mint flavour on the go, this compact oral care spray fits easily into your pocket, handbag or travel kit.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f066e8aa860658206588b67b', 'zh-CN', 'Potato PDF：免费在线 PDF 工具箱', '免费在线 PDF 工具箱，支持合并、拆分、压缩、编辑、签名与格式转换，含 OCR、护照照片和图片工具，多数在浏览器本地处理。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f066e8aa860658206588b67b', 'en', 'Potato PDF', 'Potato PDF is a free online toolbox for everyday file tasks. Merge, split, compress, edit, sign and convert PDFs to and from Word, Excel, PowerPoint and images — plus OCR, a passport photo maker, image tools and AI writing tools.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_004f878ea9b106da22685e95', 'zh-CN', 'Mapicus：旅行足迹地图', '记录旅行足迹与去过的地方，将旅程回忆绘制成地图，并可关注其他旅行者、浏览他们的路线。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_004f878ea9b106da22685e95', 'en', 'Mapicus', 'Map your trips, save the places you''ve visited, and turn your travel memories into a map of your journey.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_183ca949cd6c715638d39d54', 'zh-CN', 'Digital Room Service 酒店客房服务与运营平台', '酒店客房扫码点餐与请求服务，后台统一管理订单、派单和账单', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_183ca949cd6c715638d39d54', 'en', 'Digital Room Service', 'Digital Room Service is a browser-based hotel guest-service and operations platform that lets guests scan a room QR to order food or request hotel services, while hotel teams manage room-service orders, staff assignments, service workflows…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_84d86e41de24fbaa212abfb4', 'zh-CN', 'Hut Engineering Solutions 免费在线工具集', '汇集 PDF 转换编辑、证件照制作与工程计算等 40+ 免费浏览器工具，无需注册，文件处理后删除。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_84d86e41de24fbaa212abfb4', 'en', 'Hut Engineering Solutions', '40+ free browser tools in one place: • PDF: to Word/Excel/PPT, compress, edit, OCR, merge, sign-check • Photo: passport & visa maker for 14 countries, resize to exact KB, background change, unblur, colourise • Engineering: beam SFD/BMD/def…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2ef81d0d5be91fdf60b17c78', 'zh-CN', 'Hostel Cloud', '集宿舍入住、房间、学生、费用与日常运营管理于一体，并支持学生查找申请宿舍。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2ef81d0d5be91fdf60b17c78', 'en', 'Hostel Cloud', 'Hostel Cloud modernizes hostel management by bringing admissions, rooms, students, fees, expenses, complaints, and daily operations into one platform.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c3965d722e6fbe1f634e31d', 'zh-CN', 'Hark Pro：替你办事的个人 AI 助理', '个人 AI 助理，用云端电脑跨网站代办日程、邮件、购物与旅行等事务', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c3965d722e6fbe1f634e31d', 'en', 'Hark', 'Hark Pro is a personal AI designed to take things off your plate, not add another chatbot to your day.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34d0dac96fe27cb2c6bf627a', 'zh-CN', 'Bonjour India Travel：印度定制旅行', '提供印度多地定制旅行，按兴趣、节奏与预算规划文化、自然、美食和本地体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34d0dac96fe27cb2c6bf627a', 'en', 'Bonjour India Travel', 'Découvrez l’Inde autrement avec Bonjour India Travel, votre spécialiste des voyages sur mesure. Nous créons des expériences uniques et personnalisées à travers le Rajasthan, Delhi, Agra, Varanasi, le Kerala, l’Inde du Sud et l’Himalaya.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df60c4884488f5d227834fa0', 'zh-CN', 'Trawex Hotel API', '将 Trawex Hotel API 接入网站，即可获取全球酒店实时房价、房态、设施与客房信息，并通过单一 API 获得协议价。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_df60c4884488f5d227834fa0', 'en', 'Trawex Hotel API', 'Integrating Trawex Hotel API into your website gives you access to a huge range of accommodations with real-time rates and availability, amenities, and important hotel-room information.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5b52d12a4081a4b0e8a373e1', 'zh-CN', 'MerchanSys 零售巡店外勤管理平台', '面向巴西零售巡店外勤团队的离线优先应用，支持 GPS 打卡、货架拍照、路线规划与管理者实时看板', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5b52d12a4081a4b0e8a373e1', 'en', 'MerchanSys', 'MerchanSys runs merchandising field teams in Brazil. Promoters use an offline-first app (iOS and Android) to follow the route of the day, check in at each store with GPS validation and photograph shelves, displays and prices.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3dc875ca427b1d0f82c3a5ab', 'zh-CN', 'RentaBuddy：印度本地陪伴与活动伙伴平台', '印度本地陪伴、向导与活动伙伴发现平台，覆盖多城市，提供城市游、活动、咖啡、旅行、游戏等安全纯社交体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3dc875ca427b1d0f82c3a5ab', 'en', 'RentaBuddy', 'RentaBuddy is India’s platform to discover verified local companions, guides and activity partners.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_64838bc909cfb5635f409c58', 'zh-CN', 'Staurax：网络安全与定制软件公司', '巴基斯坦网络安全与软件公司，提供安全数字产品、SaaS 平台及定制管理软件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_64838bc909cfb5635f409c58', 'en', 'Staurax Inc.', 'Staurax is a Pakistan-based cybersecurity and software company building secure digital products, SaaS platforms, and custom software for modern businesses.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d1ad1a6d410150f477f637a4', 'zh-CN', 'DEMON HAUS 设计资产商店', '由工作室打造的设计资产商店，提供网站模板、社交与 YouTube 素材包、专辑封面、海报菜单、纹理及原创阿拉伯字体，买断无订阅。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_d1ad1a6d410150f477f637a4', 'en', 'DEMON HAUS', 'DEMON HAUS is a design asset store built by a working studio. Website templates (portfolio, boutique hotel, restaurant), social and YouTube packs, album covers, posters and menus, grain, analog and photocopy textures, and original Arabic d…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bde822adb1566a12b670e1c9', 'zh-CN', 'CarFree 出行发现与规划', '在浏览器中选择覆盖城市，发现地点活动，规划出游并比较出行方式。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bde822adb1566a12b670e1c9', 'en', 'CarFree', 'Discover places, events and experiences, build an outing, and compare available ways to get there. Start in your browser, choose a covered city, and plan from your starting address.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7ee2baf68e6da5dee4cf6d6c', 'zh-CN', 'JobCova：接单决策平台', '帮助承包商与服务从业者判断接单是否值得，统一计算人工、差旅、里程、材料、成本、利润和实际时薪。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7ee2baf68e6da5dee4cf6d6c', 'en', 'JobCova — Job Decision Platform', 'JobCova helps contractors and service professionals decide whether a job is worth taking before they say yes. Calculate labor, travel, mileage, materials, other costs, profit, and effective hourly rate in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a65441f9032086ae6af5474', 'zh-CN', 'Mess Ledger 共享公寓膳食账务管理', '面向孟加拉共享公寓的免费记账 Web 应用：记录三餐、买菜、房租、水电和押金，按用餐数分摊，月底结算餐费与各自欠款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a65441f9032086ae6af5474', 'en', 'Mess Ledger', 'Mess Ledger is a free web app for running a mess, hostel or shared flat in Bangladesh. Log daily meals, bazar (groceries), rent, bills and deposits, and it works out the meal rate and who owes what at month''s end.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_54bc9adc323717d4a96ba4f7', 'zh-CN', 'Goskyscout：全球航班比价与航线指南', 'Goskyscout 提供全球航班比价与实用航线指南，帮助用户比较航班、了解机场、行李、转机及到达交通后再预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_54bc9adc323717d4a96ba4f7', 'en', 'Goskyscout', 'Goskyscout combines worldwide flight comparison with practical route guides. Compare current flight options and explore airports, baggage considerations, connections and arrival transport before booking with your chosen airline or travel a…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0dabbc7e48b2b59bdab6dbf0', 'zh-CN', 'BenchWork：学生运动员学业与训练日程管理', '帮助学生运动员导入课程大纲，统一管理作业截止日期、课程成绩与训练比赛日程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0dabbc7e48b2b59bdab6dbf0', 'en', 'BenchWork', 'BenchWork helps student-athletes organize school around their sport. Import a syllabus, review extracted assignments and dates, and see academic deadlines alongside practices, lifts, games and travel. Track classes and grades in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5bc87e4292cd624abc6c2e47', 'zh-CN', 'Veduta', 'AI 规划多城市行程，3D 俯瞰城市与景点，整合交通住宿门票信息', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5bc87e4292cd624abc6c2e47', 'en', 'Veduta', 'Fly over cities in photorealistic 3D, discover the places worth your time, and plan your trip day by day.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1aa1ee3f7c8580a210fb1765', 'zh-CN', 'v1prep：飞行员考试与求职备考平台', '面向飞行员的题库与备考工具，覆盖 PPL 至 ATPL、型别等级、面试准备、求职和简历制作。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1aa1ee3f7c8580a210fb1765', 'en', 'v1prep', 'From first lesson to airline job and beyond: 15,000+ sourced questions from PPL to ATPL and type ratings, interview prep, pilot jobs, a CV builder and tools.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_25e129c4529595f672a84298', 'zh-CN', 'U OK?：一键每日报平安', '面向独居者、独自出行者及其家属的一键每日签到工具，超时未签到会自动向其紧急联系人发送短信，不追踪位置，对方无需安装应用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_25e129c4529595f672a84298', 'en', 'U OK?', 'U OK? is a one-tap daily check-in for people who live alone, travel solo, or have family who worry. Miss a check-in and your grace period runs out, your emergency contact gets one SMS.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7cdd807d9b796958c5db292f', 'zh-CN', 'Roopkundheaven：花谷徒步新手实用指南', '面向新手的2026年花谷与Hemkund Sahib徒步攻略，含路线、费用和装备清单', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7cdd807d9b796958c5db292f', 'en', 'Roopkundheaven', 'Is the Valley of Flowers trek safe for beginners? Get the 2026 itinerary, breakdown of costs, and essential packing list for Hemkund Sahib.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9472fe9263670d56417a7440', 'zh-CN', 'QuoteSprout 清洁服务报价计算器', '面向独立住宅清洁商的报价计算器，发送前核算人工、交通、耗材、管理费、利润与折扣，免费浏览器使用无需账号。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9472fe9263670d56417a7440', 'en', 'QuoteSprout', 'QuoteSprout helps independent residential cleaners check labour, travel, supplies, overhead, profit margins and customer discounts before sending a quote. Use the free browser calculator without an account.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
