DELETE FROM product_content WHERE product_id IN ('prd_a268e5b776ec3cea84fbad90','prd_a966fda6df870b3147639e0f','prd_feb5eda9a47be546943834d2','prd_fad4c2963c252f79dee32b86','prd_ff630380590353969af33cb6','prd_f0c1d59e8d5fbb461181f8a5','prd_8be5a36ace0d70c2be893580','prd_2ade9487107c087c6b5e654a','prd_11576835e1916c69746de0d8','prd_306599f1581d2cd7b189cb1e','prd_35acd8bfcd51d48978b6f07a','prd_374e6e8f2e231d85f9aaff4f','prd_057a49d443b8f920286d0d58','prd_33f2bd4d8d0128b911112405','prd_535694fdbfcd3da23e497f29','prd_814c09f89c75bbecb02d3a82','prd_86883dad919112e46b1efa8c','prd_5ec9c72b3032c07efd6a72b9','prd_5397c7b4edcfc63d84c115d7','prd_a64ddbbb1555cca07297e700','prd_86efcd5d06313a53569a7057','prd_91011b873a8ec9d705d667b3','prd_e0e6dbb20b0c5e8c346181de','prd_eb20338032e232d68289e788','prd_f1340e4de350ba0769d2563d') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_a268e5b776ec3cea84fbad90', 'zh-CN', 'Vijayawada 留学咨询', '为海得拉巴与维杰亚瓦达学生提供留学选校、申请、奖学金及签证指导。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a268e5b776ec3cea84fbad90', 'en', 'Vijayawada', 'Best Study Abroad Consultants in Hyderabad & Vijayawada help students plan their international education journey with comprehensive guidance for university selection, course selection, admissions, scholarships, application documentation, a…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a966fda6df870b3147639e0f', 'zh-CN', 'Manus 2.0 视频编辑器', 'Manus 2.0 新增 AI 视频编辑器，可将想法与素材制作成专业成品视频。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a966fda6df870b3147639e0f', 'en', 'Introducing Video Editor in Manus 2.0', 'Manus 2.0 introduces Video Editor, making professional-looking video creation accessible to everyone.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_feb5eda9a47be546943834d2', 'zh-CN', 'Voyaij：把预订邮件转成离线行程时间线', '转发预订邮件即可生成离线逐日行程，标记冲突、缺失确认和城际交通，支持7种语言，Android与网页免费使用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_feb5eda9a47be546943834d2', 'en', 'Voyaij', 'Forward booking emails to import@myvoyaij.com and get one day-by-day trip timeline that opens offline. Every plan flags clashes, missing confirmations and missing travel between cities. No inbox access.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fad4c2963c252f79dee32b86', 'zh-CN', 'eSIMCard 全球旅行 eSIM', '面向旅行者的全球 eSIM 套餐，覆盖 200+ 目的地，可在线购买、安装和管理，免换实体卡。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fad4c2963c252f79dee32b86', 'en', 'esimcard', 'eSIMCard makes staying connected abroad simple with affordable local, regional, and global eSIM plans covering 200+ destinations. Travelers can buy, install, and manage their eSIM digitally without swapping physical SIM cards.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ff630380590353969af33cb6', 'zh-CN', 'Roamtell 旅行 eSIM', '面向日本、墨西哥、欧洲、美国等200多个目的地的旅行 eSIM，邮件即时发送二维码，可保留 WhatsApp。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ff630380590353969af33cb6', 'en', 'Roamtell', 'The travel eSIM for Japan, Mexico, Europe, the USA and 200+ destinations. A cheaper international SIM card: QR code by email instantly, keep your WhatsApp…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0c1d59e8d5fbb461181f8a5', 'zh-CN', 'Changer+ 稳定币自托管钱包', '以稳定币为核心的自托管钱包，支持多链管理 USDT/USDC，并提供 eSIM 与旅行券等使用场景。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f0c1d59e8d5fbb461181f8a5', 'en', 'Changer+', 'Changer+ is a stablecoin-first, self-custodial wallet built to make key stablecoins such as USDT and USDC easier to hold, move and use.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8be5a36ace0d70c2be893580', 'zh-CN', 'Trawex Flight API 航班预订接口', '面向旅游门户和应用的航班预订 API，可自动化出票流程，兼容多设备响应式布局。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8be5a36ace0d70c2be893580', 'en', 'Trawex Flight API', 'Trawex Flight API will help your business increase revenue while automating processing and reducing the time and effort required completing your airline ticket booking.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2ade9487107c087c6b5e654a', 'zh-CN', 'TripStow：邮件生成旅行日志', '转发预订邮件即可自动生成行程与旅行日志，并提供刮刮世界地图、航班统计、徽章和实时航班提醒。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2ade9487107c087c6b5e654a', 'en', 'TripStow', 'Forward your booking emails and TripStow builds your trips. A lifetime travel log, a scratch-off world map, flight stats, badges and live flight alerts.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_11576835e1916c69746de0d8', 'zh-CN', 'FareDraft 旅行行程报价工具', '面向旅行代理，将支持的 Amadeus 航班行程整理成客户报价，可补充价格与行李说明并通过邮件、WhatsApp 或 PDF 分享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_11576835e1916c69746de0d8', 'en', 'FareDraft', 'FareDraft helps travel agents turn supported Amadeus flight rows into client proposals. Review routes and dates, add your own price and baggage notes, then share by email, WhatsApp or PDF.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_306599f1581d2cd7b189cb1e', 'zh-CN', 'Grasp：按可用器械定制力量的训练计划', '根据健身房、家中或酒店的可用器械规划训练，按上次举重自动设定重量，含600+动画动作、动作替换、超级组建议与间歇计时。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_306599f1581d2cd7b189cb1e', 'en', 'Grasp', 'Grasp plans each workout around the equipment you have, at the gym, at home or in a hotel, and sets your weights from what you lifted last time.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_35acd8bfcd51d48978b6f07a', 'zh-CN', 'SpeakLoop：场景化英语口语练习', '按酒店、旅行、工作、面试等场景生成个性化英语口语练习，提升语法与词汇。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_35acd8bfcd51d48978b6f07a', 'en', 'SpeakLoop', 'SpeakLoop helps you practice English for situations you actually care about. Choose any scenario — hotel check-in, travel, work, restaurants, interviews, or everyday conversations — and SpeakLoop creates personalized English practice for y…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_374e6e8f2e231d85f9aaff4f', 'zh-CN', 'Dueply 航班延误赔偿申领', '免费查询欧盟、英国或土耳其航班延误或取消可获最高600欧元赔偿，并生成致航司索赔信，不收佣金。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_374e6e8f2e231d85f9aaff4f', 'en', 'Dueply', 'Check for free whether you may be owed up to €600 for a delayed or cancelled flight in the EU, UK or Turkey. Enter the flight number and date: Dueply drafts the letter to the airline, with no commission.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_057a49d443b8f920286d0d58', 'zh-CN', 'MiniToolbox：隐私优先的本地 Web 工具箱', '隐私优先的本地 Web 工具集：PDF 处理、图片压缩及申根/签证等旅行计算。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_057a49d443b8f920286d0d58', 'en', 'MiniToolbox', 'MiniToolbox is a suite of 8 free, privacy-first web utilities running 100% client-side via WebAssembly & Canvas. 🔒 Zero-Upload Privacy: - PDF Merge & Split: Process sensitive documents locally with zero remote uploads.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_33f2bd4d8d0128b911112405', 'zh-CN', 'Airside：航班延误与湍流追踪', '追踪已保存航班，提供机器学习延误预测、沿实际航线的湍流预报和实时 ADS-B 追踪。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_33f2bd4d8d0128b911112405', 'en', 'Airside', 'Airside watches the flights you save: machine-learning delay predictions that move before the airline posts anything, turbulence forecasts drawn along your actual route, and live ADS-B tracking with no added delay.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_535694fdbfcd3da23e497f29', 'zh-CN', 'TripTended：旅行顾问行程跟踪工具', '面向旅行顾问，跟踪行程变更、供应商确认、付款回执、缺失信息和出发前检查，由顾问逐项确认，不代订不退款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_535694fdbfcd3da23e497f29', 'en', 'TripTended', 'TripTended is for travel advisors. After a client agrees to a trip, it tracks itinerary changes, supplier confirmations, payment receipts, missing information, and pre-departure checks. The advisor confirms every change.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_814c09f89c75bbecb02d3a82', 'zh-CN', 'BALCO 货币转换器', 'Android 货币转换器，支持离线汇率、价格扫描、收藏、历史及 30 天汇率走势，适合旅行购物比价。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_814c09f89c75bbecb02d3a82', 'en', 'BALCO Converter', 'BALCO Converter is an Android currency converter for travel, shopping and everyday price checks. It offers updated reference rates, saved offline rates, a price scanner, favourites, history, 30-day pair charts, freshness status, sharing an…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86883dad919112e46b1efa8c', 'zh-CN', 'Hotelado：全球酒店搜索与预订', '汇总全球酒店搜索、地图、房型、点评与实时优惠，可对比餐食方案、总价与取消条款后预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86883dad919112e46b1efa8c', 'en', 'Hotelado', 'Find a hotel that fits your trip. Hotelado brings worldwide hotel search, maps, room details, guest reviews and live offers into one place. Compare meal plans, total stay prices and cancellation terms before booking.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5ec9c72b3032c07efd6a72b9', 'zh-CN', 'HotelKolay 酒店管理平台', '一体化酒店管理平台，提供 PMS、预订管理、宾客服务、二维码请求、在线聊天、接送及 AI 运营。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5ec9c72b3032c07efd6a72b9', 'en', 'HotelKolay', 'HotelKolay is an all-in-one hotel management platform with PMS, booking management, guest services, QR-based requests, live chat, transfers, and AI-powered hotel operations.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5397c7b4edcfc63d84c115d7', 'zh-CN', 'LensUp：免注册的浏览器表单文件工具箱', '在浏览器中免费完成扫描、证件照制作、文件压缩与 PDF 编辑签名，无需注册。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5397c7b4edcfc63d84c115d7', 'en', 'LensUp', 'Every online form has rules: a scanned PDF, a 35×45 mm photo, a file under 200 KB, a filled-in and signed PDF. LensUp does all of it free, without sign-up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a64ddbbb1555cca07297e700', 'zh-CN', 'Streakly：免联网 Android 习惯追踪器', '无需联网权限的 Android 习惯追踪应用，支持按周计目标、冻结日、计数习惯、热力图、桌面小组件与本地健康数据。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a64ddbbb1555cca07297e700', 'en', 'Streakly', 'Streakly is a free Android habit tracker with no INTERNET permission — it physically can''t send your data anywhere. No account, no ads, no trackers, no paywall. Weekly goals count weeks, not days, so a rest day never breaks your streak.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86efcd5d06313a53569a7057', 'zh-CN', 'PetnTrip：宠物友好酒店政策与评价聚合', '按城市汇总酒店宠物政策、费用、体重与品种限制及真实住客评价，帮你订前确认是否真正宠物友好。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_86efcd5d06313a53569a7057', 'en', 'petntrip', 'Most hotel booking sites just show a generic "pet friendly" tag — no details on fees, weight/breed limits, or whether it''s actually enforced at check-in.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_91011b873a8ec9d705d667b3', 'zh-CN', 'TUlon：多人旅行规划与开销分摊', '一站式多人旅行规划工具，共享行程、预算与多币种开销，自动分摊并结算欠款。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_91011b873a8ec9d705d667b3', 'en', 'TUlon', 'TUlon is an all-in-one group travel planner that keeps the whole trip in one place. Build shared itineraries, manage a group budget, track expenses in multiple currencies, split costs between travelers, and automatically see who owes whom.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e0e6dbb20b0c5e8c346181de', 'zh-CN', '[开源推荐] Chinese Literature — 四大名著英文检索站', '四大名著英文检索站：水浒108星座次与结局、西游记妖怪与法宝索引、红楼梦贾氏系谱与金陵十二钗判词、三国群雄与战役年表；附141张原创水墨人物册页，逐条回目引证，纯静态零依赖，中英日三语。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e0e6dbb20b0c5e8c346181de', 'en', 'Chinese Literature — English Reference Site for the Four Great Classical Novels', 'Static trilingual site indexing the Four Classic Novels: Water Margin''s 108 stars and fates, Journey to the West demons and artifacts, Jia genealogy and verdicts, Three Kingdoms timeline, with 141 original ink portraits and cited sources.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb20338032e232d68289e788', 'zh-CN', 'The Atlas：177 个值得旅行的地方', '精选 177 个值得前往的旅行目的地，可一站式浏览并规划下一趟旅程。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb20338032e232d68289e788', 'en', 'The Atlas 177 places worth travelling to', 'The Atlas is a curated guide to 177 places worth travelling to. Browse the destinations in one place and find your next trip. Built as a personal project and published with Netlify. Feedback welcome!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f1340e4de350ba0769d2563d', 'zh-CN', 'TripClear 旅行分账工具', '为团体旅行记录并分摊多币种开销，支持拍收据、邀请同行、查看谁欠谁及导出 CSV。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f1340e4de350ba0769d2563d', 'en', 'tripclear', 'Group trips shouldn''t end with a pile of receipts and a complicated spreadsheet. TripClear makes it easy to track and split travel expenses, even across multiple currencies.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
