DELETE FROM product_content WHERE product_id IN ('prd_f90507851d6f1e9b0d1c66e2','prd_586585c499f29a8353e22ae7','prd_e9b66363f12d26765e63830a','prd_2c71b0ed190b97a63ab7dcc9','prd_ed91b9551703a2f587090ce6','prd_ed8bc3882efe62c7eb2a53ce','prd_0b4e06402142161b81f2469b','prd_95fb9243c44c8c616584c450','prd_7e3e53a3bc3b87356d921ff4','prd_fe20aa6736388ad0dc92e53d','prd_4bb890b5b05a5c72a66cb943','prd_29b7032364bddb0f58aee2a8','prd_216567e630f75e2b273c3f17','prd_314a56bd659d78c7aacb8ac3','prd_abdf28ccea40c85072c87ff5','prd_16b8f4e292698292152e8ed7','prd_e54380bb8c557e8b6a2b99fd','prd_a386566c3c2422a7517ed024','prd_448ca66ac16598cb12631166','prd_4d9088294d339234db93e9ff','prd_19c5b709c6395676c4f51b9c','prd_e81ae685e7e0a9536f472fbb','prd_ebe91acc8f83987fc50192a7','prd_94927a18e725e11c2205b21b','prd_7be7bb1364b6527245422b14') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_f90507851d6f1e9b0d1c66e2', 'zh-CN', 'VICATOO：AI 礼宾酒店预订', '通过语音或文字描述住宿需求，AI 礼宾实时搜索酒店库存、比较房型并说明匹配理由。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f90507851d6f1e9b0d1c66e2', 'en', 'VICATOO', 'Hotel booking with a live AI concierge. Describe the stay you want by voice or text, and VICATOO searches live hotel inventory, compares rooms and explains why each one fits. Selected hotels have room videos filmed by our team.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_586585c499f29a8353e22ae7', 'zh-CN', '日常便携 USB 搅拌机', '便携 USB 搅拌机，让你在家、办公室、健身房或旅途中轻松制作果昔与新鲜饮品。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_586585c499f29a8353e22ae7', 'en', 'USB Blenders For Everyday Use.', 'Portable USB blenders make smoothies and fresh drinks easier at home, work, the gym, or while traveling.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e9b66363f12d26765e63830a', 'zh-CN', 'GPSNote', '为照片添加时间戳、实时GPS、地图叠加和语音备注，适合实地勘察、测量、旅行与徒步记录。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e9b66363f12d26765e63830a', 'en', 'GPSNote', 'GPSNote is timestamps, and annotates photos with live GPS data, map overlays, and South Indian voice notes. Ideal for site inspections, surveying, travel diaries, and hiking logs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2c71b0ed190b97a63ab7dcc9', 'zh-CN', 'StampCam 水印相机', '为 iPhone 和 Android 的照片与视频添加时间、地址、GPS 和备注水印，支持离线记录现场与巡检。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2c71b0ed190b97a63ab7dcc9', 'en', 'StampCam Watermark Camera', 'StampCam adds timestamps, addresses, GPS coordinates and notes to photos and videos on iPhone and Android. Keep site visits, inspections and travel logs in context.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed91b9551703a2f587090ce6', 'zh-CN', 'Agra Trends：阿格拉本地新闻与资讯', '汇集阿格拉本地新闻、活动、文化、美食与旅游资讯的一站式信息平台', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed91b9551703a2f587090ce6', 'en', 'Agra News, Latest Updates, Agra Trends', 'Agra Trends brings you the latest Agra news, local updates, events, culture, food, tourism and things to do in Agra. Get the latest news and updates from Agra in one place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed8bc3882efe62c7eb2a53ce', 'zh-CN', 'The Butler：人工礼宾代办服务', '用自然语言描述需求，AI 整理后由真人联系商家，代办订餐、找牙医与出行协调。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed8bc3882efe62c7eb2a53ce', 'en', 'The Butler', 'I built a concierge web app that sits in the gap between "book it yourself" and "hire a personal assistant.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b4e06402142161b81f2469b', 'zh-CN', 'Pariotics：酒店客房语音触控礼宾', '面向酒店客房的语音与触控礼宾服务，客人可语音或点击提出送水、叫醒等需求，无需应用、电话或等待。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b4e06402142161b81f2469b', 'en', 'Pariotics', 'Pariotics is a voice-and-touch concierge for hotel rooms. Guests speak or tap for anything from water to a wake-up call — no app, no calls, no waiting.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_95fb9243c44c8c616584c450', 'zh-CN', 'HEROZ 背包', 'HEROZ 实用背包，含带电脑隔层的通勤包与旅行背包', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_95fb9243c44c8c616584c450', 'en', 'HEROZ', 'Looking for the best laptop backpack? Explore HEROZ office laptop bags with padded sleeves, rain cover & anti-HEROZ creates practical backpacks designed for work, travel, study and everyday use.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e3e53a3bc3b87356d921ff4', 'zh-CN', 'Wet Bulb Tracker：湿球温度健康预警 App', '湿球温度追踪 App，按五级风险推送高温高湿预警，含逐小时时间轴、降温指引与 6 天预报。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7e3e53a3bc3b87356d921ff4', 'en', 'Show HN: Wet Bulb Tracker Tracker – sends you humid-heat alerts and forecasts', 'HN users may mostly know Wet Bulb Temperatures through Chapter 1 of &#x27;Ministry for the Future&#x27; set in India. Well, the topic was close to home, so I built something for myself.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fe20aa6736388ad0dc92e53d', 'zh-CN', 'Mehal Singh RCIC 加拿大移民顾问服务', '加拿大持牌移民顾问服务，覆盖快速通道、省提名、PR、工签学签、家庭担保与商业移民等申请咨询。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fe20aa6736388ad0dc92e53d', 'en', 'Mehal Singh RCIC', 'Mehal Singh RCIC at Solex Immigration helps individuals, families, students, and professionals understand their Canadian immigration options.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4bb890b5b05a5c72a66cb943', 'zh-CN', 'Arcadia：30 个问题帮你找到理想定居地', '通过 30 道问题对比全球 3582 个城镇与岛屿，帮你找到适合定居的地方。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4bb890b5b05a5c72a66cb943', 'en', 'Arcadia', 'Seven years to decide where to live: spreadsheets, Notion tables, tabs never closed. Every "best places" list gave me the same thirty cities, none an answer to my life. Traveling taught me each place brings out a different version of you.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_29b7032364bddb0f58aee2a8', 'zh-CN', '移民数据', '开源移民数据：每月官方公告发布后逐格对比美国绿卡 15 类排期较上月的前进或倒退，收录加拿大 EE 447 轮抽签记录、美国审理时间、23 国政策库，并提供 6 国积分自测器；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_29b7032364bddb0f58aee2a8', 'en', 'Immigration Data: US Green Card Priority Dates & Canada EE Draws', 'Open-source JSON dataset tracking monthly US green card priority dates across 15 categories, 447 Canadian Express Entry draws, US processing times, policies for 23 countries, and points calculators for 6 countries. Free and ad-free.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_216567e630f75e2b273c3f17', 'zh-CN', 'Venice Echoes 威尼斯回响', '收录1730至1920年威尼斯画作与老照片，可离线查看图像、元数据与地图的旅行导览。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_216567e630f75e2b273c3f17', 'en', 'Venice Echoes', 'Step across centuries and explore Venice through the eyes of master painters and vintage photographers who documented the floating city between 1730 and 1920. 100% Offline-Ready: Designed for travel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_314a56bd659d78c7aacb8ac3', 'zh-CN', 'DishRoam 露营车抽屉式洗碗机', '一款可装入露营车抽屉的紧凑洗碗机，驻车即可日常洗碗，省下时间多去旅行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_314a56bd659d78c7aacb8ac3', 'en', 'DishRoam', 'DishRoam is a compact dishwasher for your campervan drawer. Enjoy everyday dishwashing convenience wherever you park. More travelling, less washing up.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_abdf28ccea40c85072c87ff5', 'zh-CN', 'TrailMov：GPX/FIT 轨迹 3D 动画视频编辑器', '将 GPX/FIT 轨迹与照片制作成 3D 动画旅行视频，并可视化距离、海拔、坡度、配速、心率等活动数据。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_abdf28ccea40c85072c87ff5', 'en', 'TrailMov', 'GPX/fit 3D viewer and outdoor activity track animation video editor. Generate travel vlog video effects. Add a few photos to a route to create an animated video showcasing your travel memories.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_16b8f4e292698292152e8ed7', 'zh-CN', 'Nelos：LoRa 离线群组通信', '基于 LoRa 的离线群组通信工具，扫码组队后可聊天、共享定位、发送求助并使用离线地图，需 MeshCore 硬件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_16b8f4e292698292152e8ed7', 'en', 'Nelos', 'Nelos is a simple way for groups to stay connected when there’s no mobile coverage. Create a team, let others join with a QR code, then use group chat, direct messages, location sharing, waypoints, help alerts, tracking and offline maps ov…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e54380bb8c557e8b6a2b99fd', 'zh-CN', '个性化儿童背包', '为儿童设计的趣味彩色舒适背包，款式时尚耐用，适合上学、出行和日常探险。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e54380bb8c557e8b6a2b99fd', 'en', 'PERSONALISED BACKPACKS', 'Fun,colorful,and comfortable backpacks for kids!Choose from stylish durable designs perfect for scholl travel,and everyday adventures.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a386566c3c2422a7517ed024', 'zh-CN', 'AI Translator：多模态 AI 翻译应用', '支持文本、语音、照片、屏幕与离线翻译，含翻译历史和 AI 语言导师。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a386566c3c2422a7517ed024', 'en', 'AI Translator', 'AI Translator makes communication across languages simple. Translate text, voice, photos, camera scans, and your screen with AI-powered translations.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_448ca66ac16598cb12631166', 'zh-CN', 'LiveWorld：可旋转的全球直播摄像头地球仪', '可旋转地球仪，汇集1000多个24小时YouTube直播摄像头，点击标记即可观看并与其他观众聊天。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_448ca66ac16598cb12631166', 'en', 'LiveWorld', 'LiveWorld is a spinnable globe of 1000+ 24/7 YouTube live cameras. Beaches in Ibiza, aurora in Iceland, Tokyo crossings, Katmai bear cams, LAX runways. Tap a marker to watch inline and chat with everyone else watching the same view.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d9088294d339234db93e9ff', 'zh-CN', 'Artwork List：身边艺术作品地图', 'Artwork List 可在缩放地图上发现附近或旅行途中的艺术作品与收藏，并创建、追踪想看清单。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_4d9088294d339234db93e9ff', 'en', 'Show HN: Artwork List – map of artworks near you', 'I want more art in my life. So I needed a way to find new art, and track the art I want to see. I built ArtworkList.com for that - it lets you make lists of art, and also find art nearby Use the "nearby" feature here: https:&#x2F;&#x2F;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19c5b709c6395676c4f51b9c', 'zh-CN', 'ThietBiXe 汽车服务与充电站导航', '查找附近汽车修理厂、年检、救援和充电站，提供快速导航与口碑评价，覆盖34个省市。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19c5b709c6395676c4f51b9c', 'en', 'ThietBiXe', 'Địa điểm garage ô tô, đăng kiểm, cứu hộ & trạm sạc gần đây, chỉ đường nhanh chóng, đánh giá uy tín 34 tỉnh thành – đồng hành trên mọi chặng đường !', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e81ae685e7e0a9536f472fbb', 'zh-CN', 'LivaSub AI 实时字幕与翻译', '在设备端将实时语音转为字幕并翻译，支持离线使用，适用于会议、旅行、课堂和多语言对话。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e81ae685e7e0a9536f472fbb', 'en', 'LivaSub AI Live Captions', 'LivaSub turns live speech into real-time captions and translations directly on your device. It automatically detects speech, displays floating subtitles, and can keep conversations private without requiring an internet connection.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ebe91acc8f83987fc50192a7', 'zh-CN', 'Avsha', '把任意街道、地标或街区即时生成为你所用语言的语音故事，90秒内完成', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ebe91acc8f83987fc50192a7', 'en', 'Avsha', 'Avsha turns any street, landmark or neighborhood into a narrated audio story — generated on the spot, in your language, in 90 seconds. Not a fixed catalog of a few famous stops. Any place, on Earth. Free to start.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_94927a18e725e11c2205b21b', 'zh-CN', 'TimArt Line B2B 跨境员工运输管理平台', '面向人力派遣与 HR 机构的波德跨境员工运输平台，含实时 GPS 追踪、路线优化、乘客名单与 B2B 发票管理', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_94927a18e725e11c2205b21b', 'en', 'TimArt Line B2B', 'TimArt Line is an all-in-one B2B logistics solution that automates international employee transport between Poland and Germany.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7be7bb1364b6527245422b14', 'zh-CN', 'Bien.uy：乌拉圭生活成本与办事顺序指南', '清晰呈现乌拉圭生活各项开支、可剩金额及手续办理先后顺序。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7be7bb1364b6527245422b14', 'en', 'Bien.uy', 'Los números claros para vivir en Uruguay: qué cuesta todo, cuánto te queda en el bolsillo y qué trámite va primero.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
