INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_c77d5c4b9ea919853929d3b7', 'zh-CN', 'FuelWide：把油价变成真实出行成本', '规划路线并计算燃油或充电成本，查看地区油价、路费与更便宜的加油点，数据附来源与日期。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c77d5c4b9ea919853929d3b7', 'en', 'FuelWide', 'FuelWide turns fuel prices into something useful: the real cost of a trip. Plan a route and see fuel or charging costs, regional prices, verified road fees, and cheaper refuelling stops.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49feffe9b2c487ca60ad1266', 'zh-CN', 'KeepFamilySafe 家庭安全', '提供私密位置共享、SOS 警报、安全区域与行程追踪的家庭安全与协作应用', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49feffe9b2c487ca60ad1266', 'en', 'KeepFamilySafe Family Safety', 'KeepFamilySafe helps families stay connected with private location sharing, SOS alerts, safe zones, trip tracking and family coordination.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5e9373a07b2bcf204b7125da', 'zh-CN', 'YouCity', '以驾车、骑行、步行、海滩漫步和无人机视角沉浸式探索全球228座城市，并收听当地电台。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5e9373a07b2bcf204b7125da', 'en', 'YouCity', 'Explore 228 cities around the world through immersive Drive, Bike, Walk, Beach Walk, and Drone rides with local radio.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_685d800015db691f71bed4c0', 'zh-CN', 'Car Check Report：英国车辆历史检查', 'AI辅助的英国车辆检查服务，可即时查询完整车辆历史、报废与损坏记录、未结金融、MOT及50多项数据。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_685d800015db691f71bed4c0', 'en', 'Car Check Report', 'AI-assisted vehicle check service in the UK. Get instant FULL vehicle history, write-off records, damages, outstanding finance, MOT, and 50+ data points. £10000 data guarantee included!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_78e7179fce9d7eea47993690', 'zh-CN', 'DriveSight 行车记录仪应用', 'Android 行车记录仪应用，支持实时警方位置、恶劣天气与测速摄像头提醒、物体检测、停车模式和现代界面。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_78e7179fce9d7eea47993690', 'en', 'DriveSight dash cam app', 'Android dash cam app with live police alerts with locations, severe weather alerts, object detection, speed camera alerts with a location map, parking mode and a modern interface.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d588118130d88db4e53bb01', 'zh-CN', 'tank.cash 加油返现', '加油返现服务：每次加油返现12%，持有$TANK可达30%。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3d588118130d88db4e53bb01', 'en', 'tank.cash', 'Gas is up 30%+. tank.cash pays you back: 12% on every tank, 30% when you hold $TANK. Coming soon.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_77ad39c0eeff63213a943293', 'zh-CN', 'RK Méta IA 智能翻译眼镜', '内置AI实时翻译47种语言的智能眼镜，支持4K第一视角拍摄、空间音频、28g钛合金机身、IPX5与24小时续航，iOS/Android通用，无需订阅。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_77ad39c0eeff63213a943293', 'en', 'RK Méta IA', 'RK Méta IA réinvente les lunettes connectées : une IA embarquée traduit vos conversations en direct dans 47 langues, sans sortir votre téléphone.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_787ddef0c3173c5b6de82d6f', 'zh-CN', 'AdventureFuel 礼品卡', '面向热爱探索者的100美元数字礼品卡，可自选探险计划与目的地。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_787ddef0c3173c5b6de82d6f', 'en', 'AdventureFuel Gift Card', '🏕️ What if your next gift could help start their next adventure? Meet the **AdventureFuel Gift Card** — a $100 digital gift card for people who would rather explore than stay still.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9fe926164b1947ee9b62f6df', 'zh-CN', 'DriversMap：驾驶社交与实时车队导航', '面向 iPhone 的驾驶社交应用，提供逐向导航、实时车队同行、车队与领地互动，以及真实驾驶动态。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9fe926164b1947ee9b62f6df', 'en', 'DriversMap', 'Crews, convoys, territory, and a feed made of real drives. The social layer for driving — turn-by-turn navigation with live group driving, on iPhone.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bb3abcda3655b5de7f1a9dde', 'zh-CN', 'Flyover Country：AR 飞机舷窗观景指南', '免费离线的飞行舷窗观景应用，用 AR 在相机画面上叠加地图与兴趣点，另有 3D 舷窗视角，可提前加载航班。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bb3abcda3655b5de7f1a9dde', 'en', 'Show HN: Flyover Country – guide to the window seat with AR', 'Just released a ground-up rebuild of our long abandoned app Flyover Country. Its whole thing is to tell you fun things about what you&#x27;re flying over. I&#x27;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_982ad6c4ed276ceb781da265', 'zh-CN', 'BMS Monitor 电池监控', '通过蓝牙监控兼容的 JK BMS 电池，在仪表盘中查看电量、电芯电压、电流、温度和告警，适用于房车与 DIY 太阳能系统。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_982ad6c4ed276ceb781da265', 'en', 'BMS Monitor', 'Monitor compatible JK BMS batteries over Bluetooth. Check charge level, cell voltages, current, temperatures and alarms in one clear dashboard. Built for campervans, RVs and DIY solar setups, with local history while connected.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e004055f7a0b18c95b5e1ee9', 'zh-CN', 'BubbleSpots：亲子好去处地图', '家长共建的亲子好去处地图，查找并分享游乐场、博物馆、泳池和家庭活动。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e004055f7a0b18c95b5e1ee9', 'en', 'BubbleSpots', 'BubbleSpots helps you discover fun places for kids, from playgrounds and museums to swimming spots and family activities. Explore trusted locations shared by other parents, wherever you are. Community driven, map focused.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f5d0390a754a31c52456a308', 'zh-CN', 'Wanderly Escape Card 数字礼品卡', 'Wanderly Escape Card 是一款 75 美元数字礼品卡，让收礼者自由选择新体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f5d0390a754a31c52456a308', 'en', 'Wanderly Escape Card', '✈️ What if your next gift became a memory they’ll actually remember? Meet the **Wanderly Escape Card** — a $75 digital gift card made for people who love discovering new experiences.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_11b6e0165d8862476f682e98', 'zh-CN', 'LiveWorld：一球浏览全球 YouTube 24/7 直播摄像头', '在 3D 地球上浏览全球 24/7 YouTube 直播摄像头，并可与同视角观众聊天。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_11b6e0165d8862476f682e98', 'en', 'Show HN: LiveWorld – Every 24/7 YouTube live camera on one globe', 'Teleport around the world through live YouTube cameras. Chat with people watching the same view.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_18a204427b94ab2f99607126', 'zh-CN', 'Bir Billing 滑翔伞体验', '在印度喜马偕尔邦 Bir Billing 体验滑翔伞，欣赏壮丽景色，并由专业教练指导飞行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_18a204427b94ab2f99607126', 'en', 'Bir Billing Paragliding', 'Experience the best paragliding in India at Bir Billing, Himachal Pradesh — stunning views, expert guidance, unforgettable flight', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_133c7a72368b94c52df55483', 'zh-CN', 'Tokyo Yamathon 2026 徒步赞助', '2026年10月17日徒步东京山手线30站、全程42公里，为Tokyo Yamathon募资，赞助可将Logo印在T恤上。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_133c7a72368b94c52df55483', 'en', 'Tokyo Yamathon 2026', 'I''m walking 42 km through Tokyo, visiting all 30 Yamanote stations, for Tokyo Yamathon on Sat Oct 17, 2026. Put your logo on the T-shirt I wear.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd44886f7daf5d519af3315c', 'zh-CN', 'EAutoKompass：德国电动车实用计算器', '为德国电动车买家提供免费计算器，估算真实续航、租赁与充电成本、补贴及家用充电桩选择。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_fd44886f7daf5d519af3315c', 'en', 'EAutoKompass', 'EAutoKompass helps German EV buyers and drivers turn headline specs into practical decisions. Free calculators estimate realistic range using weather, speed, load and charging windows; compare leasing and charging costs; check funding;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5aea27e19c25ac91b06d7fd6', 'zh-CN', 'Telvio', '无需注册或订阅的国际通话应用，可直接拨打200多国固话与手机，按秒计费，分钟包永久有效', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5aea27e19c25ac91b06d7fd6', 'en', 'Telvio', 'Telvio is a calling app for real phone numbers, landlines and mobiles in 200+ countries. No registration and no subscription. You install it and you can call right away, and you get one free minute to check the quality first.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9840a7d7ee23c85b4bd44cca', 'zh-CN', '东京 Yamathon：42 公里徒步穿行 30 站挑战网站', '为东京 Yamathon 2026 挑战搭建的网站，记录 42 公里徒步穿越 30 座车站，可认领参赛 T 恤位置印上自己的 logo。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9840a7d7ee23c85b4bd44cca', 'en', 'Show HN: I built a site for my 42 km walk across 30 Tokyo stations', 'I’m walking 42 km across Tokyo and visiting 30 stations in under 12 hours for Tokyo Yamathon 2026. I built a small site around the challenge, you can claim a spot on my race T-shirt and get your logo printed on it. https:&#x2F;&#x2F;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8abea225a22e32c2d0881e77', 'zh-CN', '学历、英语、存款、工作经验：你离新加坡到底还有多远？', '「坡漂结局」是一个无需注册的趣味测试，结合学历、英语、职业背景、存款、所在地及与新加坡的关联，推演继续当前路径可能走向的结局。适合考虑留学、求职或已在新加坡生活的人；', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8abea225a22e32c2d0881e77', 'en', 'How Far Are You From Singapore? A Relocation Readiness Quiz', 'A no-signup quiz weighing education, English, work history, savings, location and Singapore ties to project relocation outcomes. For people considering study, work or life there;', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_73cc3ed9680b30970b2362f6', 'zh-CN', 'KarmAI：AI 汽车诊断助手', 'AI 汽车专家，用摄像头识别零部件、听声诊断故障，并提供保养建议与零件问答。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_73cc3ed9680b30970b2362f6', 'en', 'KarmAI', 'KarmAI is an AI-powered car expert that helps you understand your vehicle. Point your camera to identify car parts, diagnose problems by sound, get maintenance tips, and ask questions about any car component.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac7c7dbfd699870151912b70', 'zh-CN', 'RideTogether', '摩托车骑手社区平台，可管理车辆、规划路线并组队骑行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ac7c7dbfd699870151912b70', 'en', 'RideTogether', 'RideTogether – die Community-Plattform für Motorradfahrer. Motorräder verwalten, Touren planen, gemeinsam fahren.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8783db669e7614c01b7a456f', 'zh-CN', 'Valuuttamuunnin 货币转换器', 'Valuuttamuunnin 是快速清晰的货币转换工具，便于旅行、跨境购物和查看汇率。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8783db669e7614c01b7a456f', 'en', 'Valuuttamuunnin', 'Valuuttamuunnin on helppokäyttöinen valuuttamuunnin, jonka avulla voit tarkistaa eri valuuttojen välisiä arvoja nopeasti ja selkeästi.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a5c16495285b29b9dab2a07a', 'zh-CN', 'GPXTool：隐私优先的 GPS 路线工具箱', '隐私优先的 iPhone/iPad GPX 工具箱，支持 2D/3D 路线查看、GPS 异常识别、海拔修正、轨迹合并拆分及导出干净文件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a5c16495285b29b9dab2a07a', 'en', 'GPXTool', 'A privacy-first iPhone and iPad toolbox to visualize routes in 2D or 3D, spot GPS anomalies, correct elevation, merge or split tracks, and export clean GPX, KML or CSV files.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_aced50cafa0928e765e86ff8', 'zh-CN', 'HomeBase Advocate：车辆维修或更换决策助手', '独立评估车辆该维修还是更换的决策支持工具，现已公测。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_aced50cafa0928e765e86ff8', 'en', 'HomeBase Advocate', 'Independent vehicle repair-or-replace decision support, now in public beta.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
