DELETE FROM product_content WHERE product_id IN ('prd_53b52783a3f5256c7d6cf602','prd_b8f4083de71c112ba6a90bc4','prd_17d7104d70dcac91e319023a','prd_b508db829742154c792e3425','prd_6542230de037e2d2fb476dae','prd_809f4e4b3ee7703c0a9f6458','prd_0ba44ecf465d32b6fedc8e75','prd_bed9c7783b418533f989d86b','prd_061075b31cb154aeb72bf666','prd_a45e4ba614f825f690ad17b8','prd_19583b9677e2abe7078952bc','prd_6052abe7acbd6297140bc2b3','prd_1412d282c80e0a1598333c22','prd_7554ff5216388a21c70682f7','prd_66478e5277e23ce1b7482991','prd_7a3ee066e5f1fc939b27261b','prd_7f0a637e0d36466b69fc4e6a','prd_74aff22cab1d3787da90f63a','prd_994931b51af708152493dd13','prd_a17f2feff4ad9fd717927379','prd_e3dc0494104fd064ec2e1503','prd_cdb1498b584c33fd163ac11c','prd_c779f7003559867648df1c64','prd_34840151bcc41afe35d6f125','prd_422390b84901496891217f8f') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_53b52783a3f5256c7d6cf602', 'zh-CN', 'RadarGO：实时测速摄像头预警', 'iOS 测速摄像头实时预警应用，支持语音、CarPlay 和社区上报。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_53b52783a3f5256c7d6cf602', 'en', 'RadarGO', 'Launching RadarGO on the App Store: live speed-camera alerts (fixed + mobile + corridors), voice, CarPlay, community reports. Built for daily drivers who are done with surprise tickets. iOS first.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b8f4083de71c112ba6a90bc4', 'zh-CN', 'CarAI 智能选车问答推荐', '通过 11 个生活场景问题推荐合适车型，并附 AI 推荐理由、用车成本、三年持有成本与实时车源链接', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b8f4083de71c112ba6a90bc4', 'en', 'CarAI', 'Every car buying tool starts with "what''s your budget?" - backwards, since you don''t know what you need until someone asks the right questions.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_17d7104d70dcac91e319023a', 'zh-CN', 'TurtleWiz PackCheck 拍照核对随身物品', '用 iPhone 拍照核对出行物品，可从照片、图片或文本创建清单，端侧 AI 识别，减少遗漏。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_17d7104d70dcac91e319023a', 'en', 'TurtleWiz PackCheck', 'TurtleWiz PackCheck helps you check the actual items you’re taking with you using your iPhone camera. Create lists from photos, printouts, saved images, or text, then show items one by one or check several together in one photo.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b508db829742154c792e3425', 'zh-CN', 'cMe：隐私优先的位置共享应用', '面向家人朋友的隐私定位共享应用，支持实时位置、历史轨迹与群组管理，覆盖 iOS、Android 和 Web。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b508db829742154c792e3425', 'en', 'cMe', 'cMe is a privacy-focused location sharing app for families, friends, trips, events, and outdoor groups. Share live GPS locations, view location history, and manage groups across iPhone, Android, and the web.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6542230de037e2d2fb476dae', 'zh-CN', 'Backyard：把散步变成街区历史故事', '将散步变成故事，沿途讲解所在街区真实且经过核实的历史。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6542230de037e2d2fb476dae', 'en', 'Backyard', 'Backyard turns any walk into a story, narrating real, fact-checked history about the exact block you''re standing on as you walk.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_809f4e4b3ee7703c0a9f6458', 'zh-CN', 'MoverMath：美国州县数据对比', '免费浏览并对比美国各州县的住房、税收、就业、学校等近300项来源数据，可自建排名并分享。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_809f4e4b3ee7703c0a9f6458', 'en', 'MoverMath', 'MoverMath makes every U.S. state and county easy to explore and compare. Browse nearly 300 sourced measures covering housing, taxes, income, jobs, schools, healthcare, crime, weather, transportation, natural hazards, recreation, and more.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ba44ecf465d32b6fedc8e75', 'zh-CN', 'BSCOBBER OmniPump-1 便携多功能充气泵', '紧凑型多功能充气泵，适用于骑行、户外和日常充气，配备110W无刷电机、25L/min风量，最高120 PSI。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0ba44ecf465d32b6fedc8e75', 'en', 'BSCOBBER OmniPump-1', 'OmniPump-1 is a compact multi-use inflator designed for cycling, outdoor adventures, and everyday inflation needs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bed9c7783b418533f989d86b', 'zh-CN', 'WanderHue：步行探索地图', '记录真实步行轨迹，用战争迷雾地图解锁探索区域，完全离线且无需账号。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_bed9c7783b418533f989d86b', 'en', 'WanderHue', 'WanderHue turns every walk into discovery. Track your real-world journeys and watch a fog-of-war map uncover as you explore — fully offline, no account needed.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_061075b31cb154aeb72bf666', 'zh-CN', 'SofiLingo：拍照即译的多语言翻译', '在 iPhone 上拍照、语音或输入，即可翻译 58 种语言；翻译在本机完成，无需注册账号。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_061075b31cb154aeb72bf666', 'en', 'SofiLingo', 'Point your camera at it, read it in your language. Scan, speak or type in 58 languages on iPhone. Translation runs on your phone, and there is no account to make.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a45e4ba614f825f690ad17b8', 'zh-CN', 'YardAtlas：卡车场站到达地图', '为卡车司机标注场站出入口、进场路线、收货月台、停车和注意事项的地图，支持搜索与贡献点位。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a45e4ba614f825f690ad17b8', 'en', 'YardAtlas', 'Most maps stop at the street address. YardAtlas maps the last block: truck entrances and exits, approach paths, receiving docks, check-in points, parking, cautions, and driver notes.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19583b9677e2abe7078952bc', 'zh-CN', 'Polaris：Polestar 菜单栏应用', 'macOS 菜单栏应用，显示 Polestar 电量、续航、充电状态与充满时间，并提供充电通知和桌面小组件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_19583b9677e2abe7078952bc', 'en', 'Polaris', 'Polaris is a tiny native macOS menu bar app for your Polestar: battery, range, charging status and time-to-full, refreshed every five minutes and every minute while charging.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6052abe7acbd6297140bc2b3', 'zh-CN', 'FuelFalcon 燃油价格查询与比较', '查找并比较澳大利亚和英国的燃油价格，支持按地区或邮编搜索、地图查看、价格历史和关注列表。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_6052abe7acbd6297140bc2b3', 'en', 'FuelFalcon', 'Find and compare fuel prices in Australia and the UK. Search by area or postcode, explore stations on a map, view price history and save stations to your Fuel Watchlist.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1412d282c80e0a1598333c22', 'zh-CN', 'Oil & Miles：独立汽车维修与购车指南', '独立汽车维修费用、机油规格与二手车购买指南，数据均可追溯至原始文件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1412d282c80e0a1598333c22', 'en', 'Oil & Miles', 'Independent car repair costs, oil specifications and used-car buying guides. No dealer, no manufacturer, no press cars. Every figure is traced to a document you can open yourself.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7554ff5216388a21c70682f7', 'zh-CN', 'Fortune Home Saket 公寓出租', 'Fortune Home 在新德里 Saket 地铁站附近提供适合家庭和上班族的 2BHK 出租公寓。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7554ff5216388a21c70682f7', 'en', '3bhk Service Apartment in Saket', 'Looking for a 2 BHK flat for rent near Saket Metro Station? Fortune Home offers comfortable and well-maintained residential accommodation in and around Saket, New Delhi, suitable for families, working professionals, and those looking for c…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_66478e5277e23ce1b7482991', 'zh-CN', 'DaySetGo：亲子本地一日游规划', '根据孩子年龄、兴趣、预算和时间生成可执行的本地亲子一日计划，家长可比较、调整并确认。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_66478e5277e23ce1b7482991', 'en', 'DaySetGo', 'DaySetGo turns children''s age ranges, interests, budget, timing, and travel preferences into a few workable local day plans.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a3ee066e5f1fc939b27261b', 'zh-CN', 'Aloha Adventures：探索夏威夷', '按地点发现夏威夷美食、徒步、商店、集市与活动，可标记地点、规划行程并分享好去处。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7a3ee066e5f1fc939b27261b', 'en', 'Aloha Adventures — Explore Hawaii', 'Aloha Adventures is a location-based activity discovery app for food, hikes, shops, markets, and events across the Hawaiian Islands. Create markers, schedule your trip, and share your favorite spots.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7f0a637e0d36466b69fc4e6a', 'zh-CN', 'MyMotor：印度车主车辆管理应用', '面向印度车主的一站式车辆管理应用，可查罚单、RC、保险、PUC、FASTag', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7f0a637e0d36466b69fc4e6a', 'en', 'MyMotor', 'MyMotor is a vehicle ownership app designed to make everyday vehicle management seamless for Indian vehicle owners. Use MyMotor for a quick challan checks, view e-Challan details, pending fines, offence information.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_74aff22cab1d3787da90f63a', 'zh-CN', 'Wagglewhere：狗狗友好地点探索', '带狗探索五座城市的25个精选狗狗友好地点，查看入场规则、收藏去处并留存照片回忆。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_74aff22cab1d3787da90f63a', 'en', 'Wagglewhere', 'Explore 25 researched places across five cities with your dog. Check source-linked access rules, save places to go together, and keep a local photo memory or download a keepsake card.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_994931b51af708152493dd13', 'zh-CN', 'ConnecTMee', '面向南非的安全社交平台，支持动态、短视频、语音、空间、机会与住宿发布。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_994931b51af708152493dd13', 'en', 'ConnecTMee', 'ConnecTMee - Secure social, posts, short videos, voice messages, spaces, opportunities and stay listings. South Africa.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a17f2feff4ad9fd717927379', 'zh-CN', 'Windy Gap 徒步跑步路线生成', '根据距离、坡度与地形等需求搜索地图，生成徒步和跑步路线。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a17f2feff4ad9fd717927379', 'en', 'Windy Gap', 'Windy Gap generates hiking and running routes based on what you ask for. There are potential routes all around us and it finds them. Ask for a route: distance, hills, terrain and more, and it searches the map for the best options.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e3dc0494104fd064ec2e1503', 'zh-CN', 'ChatTranslate：手机上可离线使用的双向语音翻译', '手机端离线双向语音翻译，支持100+语言；轻触屏幕上下即可收听对方语音、自动朗读译文，无需注册也无广告。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e3dc0494104fd064ec2e1503', 'en', 'ChatTranslate', 'ChatTranslate Turn your phone into a private two-way voice translator: tap the top of the screen to hear the other person’s language, tap the bottom to hear your own. Speak and it translates on the fly, then reads it aloud automatically.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cdb1498b584c33fd163ac11c', 'zh-CN', 'Dashoo：把手机变成 4K 行车记录仪', '将 iOS/Android 手机变成 4K 行车记录仪，支持循环录制、GPS 测速叠层、G 力记录和一键事故保护，视频本地私密保存。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cdb1498b584c33fd163ac11c', 'en', 'Dashoo', 'Dashoo transforms your iOS or Android device into a professional-grade 4K dashcam for free. Why buy extra hardware?', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c779f7003559867648df1c64', 'zh-CN', 'Gravton Quanta 电动摩托车', '印度制造电动摩托车，LMFP电池续航最高165公里，BLDC轮毂电机功率4kW、轮上扭矩172Nm，极速75km/h，支持三种骑行模式与CBS双碟刹。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c779f7003559867648df1c64', 'en', 'Gravton Motors', 'Gravton Quanta is a Made-in-India electric motorcycle featuring an advanced LMFP battery, up to 165 km range, and a powerful BLDC hub motor delivering up to 4 kW power and 172 Nm wheel torque.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34840151bcc41afe35d6f125', 'zh-CN', 'TheGlobeScore：交互地图对比全球国家与城市', '交互地图探索各国与城市，按 12 项标准对比社区评价，并可查看 HDI、预期寿命等官方指标。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34840151bcc41afe35d6f125', 'en', 'TheGlobeScore', 'Explore countries, regions and cities on an interactive map. Compare community reviews across 12 criteria, or switch to official indicators such as HDI and life expectancy.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_422390b84901496891217f8f', 'zh-CN', 'Dr. Raynald Torres 解析菲律宾眼睑手术费用', '介绍菲律宾眼睑整形手术的平均费用、影响价格的因素，以及医疗旅游选择当地的原因', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_422390b84901496891217f8f', 'en', 'Dr. Raynald Torres', 'Thinking about getting eyelid surgery (blepharoplasty) in the Philippines? 🇵🇭 In this video, Dr.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
