DELETE FROM product_content WHERE product_id IN ('prd_93f86eb1dde86542745b4011','prd_8776b76c8c76385b815db70b','prd_b29cb8334e1ca957a824e115','prd_a1811da9436317460314c3bd','prd_dceaec369026279712c84642','prd_e745e2d50ddf08de22661f7c','prd_076d65a854f0d776d56c22f6','prd_0185ad8e6c81eaa567bca16e','prd_094e74b9fc83cc686cc77f73','prd_0caa367d8b20656e2ea95b85','prd_5d869d5cdc45ba56bbd451c9','prd_ee142914467c90d64bbf85d0','prd_c66fe1ae174f90f5a1e1e62c','prd_f974bd19d0301f6f46d8d71f','prd_1c513ea8c6738bce4276e9c3','prd_34bea42db97339147097ed21','prd_a55a5428bb89d86f10c9aa05','prd_80e972fa382eab856873e9bf','prd_a8de8e20117299ebc725527f','prd_9fd511a923178174c6cd6191','prd_73516b6e1b56ca47f993228d','prd_74a342dfbf84fbea20904c09','prd_8535e7270de4dd64d0a07ff4','prd_cd626c05cb3ab8fd44ee7e38','prd_460673e46f010b57f4f20c9f') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_93f86eb1dde86542745b4011', 'zh-CN', '有没有喜欢徒步的 v 友？', '步停是一款 iOS 徒步记录 App，核心功能包括 KML 路线导入与导出、偏航语音提醒、离线地图、实时轨迹（距离、速度、海拔、累计爬升与下降）、海拔曲线、途中标注和整公里播报，也支持无路线的自由徒…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_93f86eb1dde86542745b4011', 'en', 'Buting: A Minimal iOS Hiking Recorder', 'Buting is an iOS hiking app that records each outing: KML route import/export, off-route voice alerts, offline maps, real-time distance, speed, elevation and ascent/descent tracking, elevation profiles, waypoint notes, and per-kilometer an…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8776b76c8c76385b815db70b', 'zh-CN', 'SafeWalk Mirror：低头看手机也能看路', '悬浮于任意应用上的实时摄像头窗口，让你低头看手机时也能看到前方路面，并在物体靠近时通过声音和震动预警。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8776b76c8c76385b815db70b', 'en', 'SafeWalk Mirror', 'A live camera window floats over any app, showing the path in front of you while you look down at your phone. On-device detection warns you with escalating sound and vibration when something gets close.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b29cb8334e1ca957a824e115', 'zh-CN', 'ROVA — 摩托车骑行追踪 App', '面向 Android 的摩托车遥测与骑行追踪应用，记录每次骑行的 GPS 轨迹、速度、海拔并生成 ROVA 评分', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b29cb8334e1ca957a824e115', 'en', 'ROVA — Ride tracking App', 'ROVA is a motorcycle telemetry and ride-tracking app for Android. Track GPS, speed, elevation and ROVA Score for every ride. Free beta APK.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a1811da9436317460314c3bd', 'zh-CN', 'Blinkey Smart Drive：AI 车辆健康助手', 'AI 车辆养护应用，解析 OBD2 数据，监测车况与行程，解读故障码并估算维修费用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a1811da9436317460314c3bd', 'en', 'Blinkey Smart Drive', 'Blinkey is an AI-powered smart vehicle care app that turns OBD2 data into useful insights. Check vehicle health, monitor live driving data, understand DTC error codes with AI, manage maintenance, review trip history, check recalls, and est…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dceaec369026279712c84642', 'zh-CN', 'Alvenea：把到访地点变成收藏卡', '将到访地点变成可收藏卡牌，探索、收集并记录熟悉度，沿途解锁印章。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_dceaec369026279712c84642', 'en', 'Alvenea', 'Exploring is more fun when every place becomes something worth collecting. Inspired by collecting trading cards, Alvenea turns the places you visit into cards for your collection.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e745e2d50ddf08de22661f7c', 'zh-CN', 'Parson Inn：查尔斯顿静谧旅馆', '位于查尔斯顿的精品旅馆，提供六间套房、现代舒适设施，毗邻历史景点，可预订。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e745e2d50ddf08de22661f7c', 'en', 'Parson Inn | Charleston, SC', 'Discover a peaceful retreat in Charleston’s Holy City. Parson Inn offers six curated suites, modern comforts, and prime access to historic sights. Reserve now.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_076d65a854f0d776d56c22f6', 'zh-CN', 'TickYourList：新加坡环球影城门票预订', '在线购买新加坡环球影城门票，比较各类主题乐园项目、演出与游玩体验选项。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_076d65a854f0d776d56c22f6', 'en', 'TickYourList', 'Grab Universal Studios Singapore tickets today for world‑class theme park rides, entertaining shows and memorable experiences. Compare options.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0185ad8e6c81eaa567bca16e', 'zh-CN', 'Cartaveo：围绕主题共建共享地图', '围绕一个主题创建地图，添加带照片的熟悉地点并分享，让社区共同维护地图。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0185ad8e6c81eaa567bca16e', 'en', 'Cartaveo', 'Build a map around one idea, add the places you know with photos, and share it with anyone. Cartaveo is where communities keep their maps alive.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_094e74b9fc83cc686cc77f73', 'zh-CN', 'Amperlo：电动车用车成本账本', '记录电动车充电、里程与票据，算出每英里真实用车成本并与燃油车对比', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_094e74b9fc83cc686cc77f73', 'en', 'Amperlo', 'Amperlo is a mobile-first logbook for EV running costs — charges, miles and receipts into real cost-per-mile and savings vs petrol. Free for one vehicle; no card required.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0caa367d8b20656e2ea95b85', 'zh-CN', 'CalisthenicsLiveMap：全球户外健身公园地图', '全球2.9万个免费户外健身公园地图，按GPS排序并标注器械，支持9种语言，有iOS应用', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0caa367d8b20656e2ea95b85', 'en', 'Calisthenicslivemap', 'CalisthenicsLiveMap helps you find free outdoor workout parks anywhere in the world: 29,486 spots in 107 countries, GPS-sorted, equipment per spot, 9 languages, iOS app (Android beta). New: contribute without a video.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d869d5cdc45ba56bbd451c9', 'zh-CN', 'CineMap 2.0', '查询影视剧流媒体播放平台与真实拍摄地的免费网站', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_5d869d5cdc45ba56bbd451c9', 'en', 'CineMap 2.0', 'CineMap answers two questions about any film or show: where you can stream it, and where it was actually filmed. The first version did availability only - search a title, see which platforms carry it across 8 countries. New in 2.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee142914467c90d64bbf85d0', 'zh-CN', 'Destino Docente：教师目的地与职位查询', '帮助教师搜索教育中心、比较通勤时间并整理目的地，查看职位空缺、拼车、住宿、招聘考试与岗位互换信息。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee142914467c90d64bbf85d0', 'en', 'Destino Docente', 'Busca centros educativos, compara tiempos de viaje y organiza tus destinos. Consulta vacantes docentes, coche compartido, alojamiento, oposiciones y permutas docentes.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c66fe1ae174f90f5a1e1e62c', 'zh-CN', 'EV Car Expert：二手电动车购买助手', '帮助二手电动车买家搜索车源、查看交易评分、比价、核查召回与风险，并用 AI 分析照片，提供议价建议和报告。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c66fe1ae174f90f5a1e1e62c', 'en', 'EV Car Expert', 'EV Car Expert helps used-EV buyers make smarter decisions before spending tens of thousands of dollars.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f974bd19d0301f6f46d8d71f', 'zh-CN', 'FxPeek 网页外币价格换算', '在浏览网页时悬停或选中外币价格即可换算，无需新开标签页，本地处理不上传网址；支持实时汇率、走势图与多币种等付费功能。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f974bd19d0301f6f46d8d71f', 'en', 'FxPeek', 'FxPeek converts foreign prices on the page you’re already on: shops, SaaS, gigs, news. No new tab. We don’t send page URLs to a server. Hover to peek the live rate; highlight a number to convert.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c513ea8c6738bce4276e9c3', 'zh-CN', 'SceneSeal 租车拍照存证', '拍摄租车取车照片并按原图整理，还车时对照查看，可导出 PDF。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_1c513ea8c6738bce4276e9c3', 'en', 'SceneSeal', 'Photograph your rental car at pickup, then use those views as a guide at return. SceneSeal keeps the photos organised and exports a PDF with the original files. Capture is free; export is a one-time purchase. No account or subscription.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34bea42db97339147097ed21', 'zh-CN', 'Hop Déménagement 搬家服务平台', '连接专业搬家公司，提交搬家需求并比较报价与服务，简化搬家安排。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_34bea42db97339147097ed21', 'en', 'Hop Déménagement', 'HOP Déménagement is a digital platform that simplifies the moving process. Users submit their moving details and can connect with professional movers to compare quotes and services.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a55a5428bb89d86f10c9aa05', 'zh-CN', 'PowerMatchLab：便携电站选型计算器', '免费便携电源选型平台，按设备计算容量、输出与启动功率，对比49款机型，并提供房车、冰箱、CPAP等场景计算器。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a55a5428bb89d86f10c9aa05', 'en', 'PowerMatchLab', 'PowerMatchLab is a free decision-support platform for portable power stations. Enter the devices you need to run and it calculates required capacity, continuous output and startup surge.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_80e972fa382eab856873e9bf', 'zh-CN', 'True Haven：欧洲迁居目的地匹配与清单', 'AI 问卷根据生活方式、预算、家庭与目标推荐欧洲迁居地，并生成清单与本地服务商 RFP。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_80e972fa382eab856873e9bf', 'en', 'True Haven', 'An AI-powered intake wizard that asks you 12 focused questions about your lifestyle, budget, family, and goals — then recommends the right European destination for *you*, not just the most popular one.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a8de8e20117299ebc725527f', 'zh-CN', 'Japan Walk Nomad：日本步行之旅', '一款 Android 步行应用，把每日步数变成穿越日本的旅程，可游览真实地标、赢取徽章并获得伙伴 Arukyun 的本地 AI 点评。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_a8de8e20117299ebc725527f', 'en', 'Japan Walk Nomad', 'Japan Walk Nomad is an Android walking app that turns your daily steps into a journey across Japan, from Cape Soya to Shuri Castle. Visit real landmarks, earn badges, and get local AI comments from your companion Arukyun.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9fd511a923178174c6cd6191', 'zh-CN', '阿布扎比 Movers & Packers 搬家服务', '阿布扎比专业搬家打包服务，覆盖住宅、办公室和国际搬迁。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9fd511a923178174c6cd6191', 'en', 'Movers & Packers Abu Dhabi', 'Trusted movers and packers in Abu Dhabi, WeMovers offers professional home, office and international moving services. Enjoy expert packing, secure handling and a smooth relocation from start to finish.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_73516b6e1b56ca47f993228d', 'zh-CN', 'Trail & Tide 礼品卡', '面值 50 美元的 Trail & Tide 礼品卡，让户外爱好者自选想要的装备与旅行用品。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_73516b6e1b56ca47f993228d', 'en', 'Trail & Tide Gift Card', '🏕️ Their next adventure starts with a choice. Give outdoor lovers a Trail & Tide $50 Gift Card and let them choose the gear and travel essentials they actually want. 🥾🌲 🎁 Give the gift of adventure', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_74a342dfbf84fbea20904c09', 'zh-CN', '【网站自荐】PicLocation：AI 照片地理定位网站，不依赖 EXIF 的纯视觉定位', '上传照片后，AI 通过地标、建筑风格、植被、路牌文字、地形等视觉线索推测拍摄地点，在交互地图上返回 GPS 坐标、城市、国家和置信度，不依赖 EXIF/GPS 元数据。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_74a342dfbf84fbea20904c09', 'en', 'PicLocation: AI Photo Geolocation Without EXIF', 'Upload a photo and the AI infers where it was taken from visual clues such as landmarks, architecture, vegetation, signage and terrain, returning GPS coordinates, city, country and a confidence score on an interactive map without relying o…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8535e7270de4dd64d0a07ff4', 'zh-CN', 'HowMuchFx：离线零输入汇率速查表', '专为海外旅行设计的离线汇率速查工具，无需手动输入即可快速换算货币。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8535e7270de4dd64d0a07ff4', 'en', 'HowMuchFx', 'I got tired of typing into calculator apps while traveling overseas, so I built HowMuchFx — a zero-typing currency cheat sheet that works 100% offline. Would love your feedback!', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cd626c05cb3ab8fd44ee7e38', 'zh-CN', 'RefundFlightWiFi 航班WiFi退款代办', '上传机上WiFi收据和断网证明，代办向航司或WiFi服务商申请退款，成功才收费。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_cd626c05cb3ab8fd44ee7e38', 'en', 'RefundFlightWiFi', 'Paid for airplane WiFi that didn''t work? Upload your receipt and proof of the outage. RefundFlightWiFi reviews your claim, submits the refund request, and deals with the airline or WiFi provider for you.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_460673e46f010b57f4f20c9f', 'zh-CN', 'Free Moving Cost Calculator 英国搬家预算计算器', '免费估算英国搬家预算，涵盖搬运、打包、清洁、仓储、出行、押金等易漏费用。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_460673e46f010b57f4f20c9f', 'en', 'Free Moving Cost Calculator', 'Use this free Moving Budget Calculator UK to estimate removals, packing, cleaning, storage, travel, deposits and easily missed moving costs.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
