DELETE FROM product_content WHERE product_id IN ('prd_3011fcf85d17ea44e1d6915e','prd_9b675f25bd28ba9e6e3f8eee','prd_f3c54133c1ba7d41cce54111','prd_c25b703fe3e461d0f4fc83a9','prd_81f4f62404a2c3dbf2cf1a08','prd_c8ea3ec4d14ae9754186fda7','prd_53c3f6ad1d7c87ece0764259','prd_7123df5e44abcc1ad5af52a7','prd_870ed3b6048977eb7edd7988','prd_ed0491ee05d6274a6feef922','prd_997ee7b08ba29e1ce12ef0ae','prd_7bb586180b54be6b447047d2','prd_f86226a68d0c8f754952a62a','prd_2b0221827b5baca246ff04ff','prd_51adddb2651918c01bcbd8fa','prd_432adb32229835d6b40015ea','prd_864e9884cc9b0749f401c202','prd_87023abae615345ee60f0461','prd_eb8937fe63c64a6cdcfcdebe','prd_b54772b0a87904421190e806','prd_2b5c069a21eb56c29fa56ea3','prd_49d07bc85df5036f3bce8c92','prd_48cc568e82babcee30d89846','prd_e685426fc1bdc168a9315da0','prd_82ca3a897a699f95a3720d18') AND content_source='llm:travel-localize-v1' AND is_current=0;
INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_3011fcf85d17ea44e1d6915e', 'zh-CN', 'AQIWatcher 全球空气质量追踪', '提供全球城市实时 AQI、健康建议与 7 天预报，可追踪多种污染物并对比城市、查看排名和规划出行。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_3011fcf85d17ea44e1d6915e', 'en', 'AQIWatcher', 'Free real-time air quality index (AQI), health guidance, and 7-day forecasts for any city worldwide. Track PM2.5, PM10, ozone, NO2 and more. Compare cities, view rankings, plan travel.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9b675f25bd28ba9e6e3f8eee', 'zh-CN', 'Performing Arts Atlas：表演艺术地图', '旅行时按地点和日期发现附近的歌剧、芭蕾、古典乐与戏剧演出并查询购票。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_9b675f25bd28ba9e6e3f8eee', 'en', 'Performing Arts Atlas', 'A map for discovering opera, ballet, classical music, theatre and other performing arts while traveling. Pick a place and date, see what''s playing nearby, and find tickets.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3c54133c1ba7d41cce54111', 'zh-CN', '英国 ILR 计算器', '免费浏览器端英国永居规划工具，可选择路径、推算资格期、记录旅行并查看假设，无需账户，数据留在浏览器。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f3c54133c1ba7d41cce54111', 'en', 'ILR Calculator UK', 'Free browser-based planning for UK indefinite leave to remain. Choose a route, map a possible qualifying period, record travel and review assumptions. No account; calculator inputs stay in your browser.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c25b703fe3e461d0f4fc83a9', 'zh-CN', 'Scratchy Us — 两人共享世界刮刮地图', '情侣专属世界刮刮地图：各自在手机上刮国家，双方都刮过才点亮，并可保存照片、视频和语音。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c25b703fe3e461d0f4fc83a9', 'en', 'Scratchy Us — A world map for two', 'Most travel scratch maps are for one person. Scratchy Us is a private world map for two. Scratch the countries you''ve visited on your own phone. You don''t have to do it at the same time.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_81f4f62404a2c3dbf2cf1a08', 'zh-CN', 'DaysHere：旅行停留天数追踪', '按国家统计旅行停留天数并计算剩余天数，支持申根90/180、年度上限及自定义规则，记录出入境并提醒截止日，含日历、历史与主屏幕小组件，数据仅存设备。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_81f4f62404a2c3dbf2cf1a08', 'en', 'DaysHere', 'DaysHere counts your travel days country by country and shows how many are left: Schengen 90/180, calendar-year caps, days-per-entry limits, or a rule you define.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c8ea3ec4d14ae9754186fda7', 'zh-CN', 'Evaporate：匿名临时聊天', '无需注册或下载，扫码或打开链接即可匿名临时聊天，支持17种语言实时翻译，聊天结束即消失。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_c8ea3ec4d14ae9754186fda7', 'en', 'Evaporate', 'Evaporate is temporary, anonymous chat with almost no setup. Show someone a QR code or share a link and start chatting. No account, download, usernames or phone numbers.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_53c3f6ad1d7c87ece0764259', 'zh-CN', 'JetLag 旅行天气与本地时间', '在 Android 手机和 Wear OS 手表查看旅行地天气与当地时间，支持多城市管理和设备同步。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_53c3f6ad1d7c87ece0764259', 'en', 'JetLag', 'JetLag puts travel weather and local time on both your Android phone and Wear OS watch. Save cities manually without location permission, check current conditions and forecast previews, sync between devices, and glance at your default city…', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7123df5e44abcc1ad5af52a7', 'zh-CN', 'The Naori Udaipur 酒店', '乌代浦尔家庭友好酒店，提供宽敞客房、现代设施、餐饮与个性化服务，营造宁静舒适的入住体验。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7123df5e44abcc1ad5af52a7', 'en', 'The Naori Udaipur', 'The Naori delivers exceptional hospitality with spacious accommodations, modern amenities, and personalized services for every guest.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_870ed3b6048977eb7edd7988', 'zh-CN', 'Speakly Translate：随身实时翻译', '一款集语音、文字、照片与双向对话翻译于一体的应用，支持离线语言包，出行时也能随时翻译。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_870ed3b6048977eb7edd7988', 'en', 'Speakly - Translate', 'Speakly makes real-world translation simple. Translate live speech, typed text, photos, and two-way conversations in one app.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed0491ee05d6274a6feef922', 'zh-CN', 'PIKU：旅行、音乐与故事创意空间', '融合旅行、音乐与故事的创意探索平台，可发现新地点、探索音乐、沉浸故事。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ed0491ee05d6274a6feef922', 'en', 'PIKU', 'Piku is a creative space where travel, music, and stories come together. 🌍🎵📚 Discover new places, explore music, and get lost in stories—all in one simple and engaging platform.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_997ee7b08ba29e1ce12ef0ae', 'zh-CN', '证件照大师', '基于AI的在线证件照制作工具，可一键抠图、更换红白蓝底色或正装，并按一寸、二寸、国考、社保及各国签证规格排版，支持免费高清打印。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_997ee7b08ba29e1ce12ef0ae', 'en', 'ID Photo Master', 'AI-powered online ID photo maker that removes backgrounds, swaps colors or formal attire, and formats photos to official one-inch, two-inch, exam, social security, and visa specs for free high-resolution printing.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7bb586180b54be6b447047d2', 'zh-CN', 'CheckPassportPhoto 美国护照照片合规检查', '打印前检查美国护照或证件照的构图、头部尺寸、眼睛位置、背景、表情与眼镜，浏览器内免费完成，照片不离开设备；付费可下载无水印 2x2 英寸打印文件。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7bb586180b54be6b447047d2', 'en', 'CheckPassportPhoto', 'Check a US passport or ID photo against official framing rules before you print it. CheckPassportPhoto measures head size and eye position, checks the background and expression, and flags glasses.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f86226a68d0c8f754952a62a', 'zh-CN', 'Bora Praia', '结合潮汐、气温、风力、日照与出行时长，推荐最佳海滩出游时段并提示出发时间。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_f86226a68d0c8f754952a62a', 'en', 'Bora Praia', 'Choose a place, set the tide, temperature and wind you prefer, then add travel time and stay length. Bora Praia combines the forecast with daylight to recommend your best outing window—and tells you when to leave. Free on iOS and Android.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2b0221827b5baca246ff04ff', 'zh-CN', 'SyncDialect 离线实时语音翻译器', '面向旅行的 Android 端实时语音翻译器，设置后完全离线运行，无需上传云端，支持自然对话。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2b0221827b5baca246ff04ff', 'en', 'SyncDialect', 'SyncDialect is a real-time voice translator built to work entirely on your Android device after setup. Unlike cloud-based translators, conversations don''t need to be sent to a remote server.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_51adddb2651918c01bcbd8fa', 'zh-CN', 'TempoAI GPS 水印相机', '集 GPS 位置水印、地址天气与时间戳、AI 人像抠图和滤镜的旅行拍照相机', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_51adddb2651918c01bcbd8fa', 'en', 'TempoAI GPS Watermark Camera', 'TempoAI Camera combines GPS travel stamping, AI portrait cutout, creative editing and cinematic LUTs in one camera.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_432adb32229835d6b40015ea', 'zh-CN', 'Timeline Visualizer：地图时间线转旅行视频', '在浏览器中将 Google 地图导出的 Timeline.json 转为带动画、音乐和路线标记的旅行视频，数据不上传。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_432adb32229835d6b40015ea', 'en', 'Timeline Visualizer', 'Timeline Visualizer turns the Timeline.json you export from Google Maps into an animated travel video — right in your browser, nothing is uploaded.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_864e9884cc9b0749f401c202', 'zh-CN', 'Timeline Visualizer：旅行时间线视频生成器', '将导出的 Google Maps Timeline.json 在浏览器中生成可分享的动画旅行回顾 MP4。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_864e9884cc9b0749f401c202', 'en', 'Timeline Visualizer', 'Google moved Timeline to on-device storage and removed the web viewer — but millions of people still want to see and share where they''ve been. Timeline Visualizer turns your exported Google Maps Timeline.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_87023abae615345ee60f0461', 'zh-CN', 'Time Now Live 世界时钟', '免费在线世界时钟与时区工具，查询各地当前时间并比较时区，方便安排会议、通话与远程协作。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_87023abae615345ee60f0461', 'en', 'Time Now Live', 'Time Now Live is a free online world clock and time zone tool that helps you find the current time in cities and locations around the world.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb8937fe63c64a6cdcfcdebe', 'zh-CN', 'Agadir Weather：阿加迪尔天气指南', '提供阿加迪尔实时天气、逐小时与15天预报、月度气候、海滩状况及旅行建议。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_eb8937fe63c64a6cdcfcdebe', 'en', 'Agadir Weather', 'Weather Agadir: accurate current weather, hourly forecasts, 15-day trends, monthly climate guides, beach conditions, and travel advice for Agadir, Morocco.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b54772b0a87904421190e806', 'zh-CN', 'Google Timeline 旅行可视化工具', '用 Google 位置记录（Timeline）数据可视化你一年的旅行足迹。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_b54772b0a87904421190e806', 'en', 'mahlernim / google-timeline-visualizer', 'Visualize your year in travel using your Google Location History (Timeline) data', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2b5c069a21eb56c29fa56ea3', 'zh-CN', 'AtmosVPN：安全 VPN', '集加密、无日志与断网保护于一体的 VPN，附数据泄露监测、链接扫描、骚扰拦截及居家 IP 浏览模式。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_2b5c069a21eb56c29fa56ea3', 'en', 'AtmosVPN: Secure VPN', 'AtmosVPN goes beyond encryption. Alongside AES-256, a no-logs policy, and a real kill switch, it bundles tools most VPNs sell separately: a Data Breach Monitor, Link & Content Scanner, and Spam Call/SMS Blocker.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49d07bc85df5036f3bce8c92', 'zh-CN', 'Appricio', '根据位置、时间、天气和口味推荐当地人会选的地点，附推荐理由和备选方案，无广告。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_49d07bc85df5036f3bce8c92', 'en', 'Appricio', 'Most travel apps rank what''s popular. Appricio knows what fits — a few places a local would actually choose, given where you are, the time, the weather and your taste. With a reason, and a Plan B if you''ve seen it. No ads, no endless lists.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_48cc568e82babcee30d89846', 'zh-CN', 'Where is Paul? 个人经历空间记录', '开源的个人经历与旅行记录工具，以地球和时间轴呈现，可生成漫画式片段，跨移动端、桌面及AR/VR。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_48cc568e82babcee30d89846', 'en', 'Where is Paul?', 'Most life-story and travel tools are built for a single screen size or format. Where is Paul? is designed to work the same way on mobile, desktop, and in augmented or virtual reality.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e685426fc1bdc168a9315da0', 'zh-CN', '男士真皮笔记本电脑包', '面向男士通勤与商务出行的全粒面真皮笔记本电脑包及办公包，内置合理收纳，兼顾品质与风格。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_e685426fc1bdc168a9315da0', 'en', 'Leather Laptop Bag for Men for Work', 'Explore full grain leather laptop bags & office bags for men. Built for daily commutes and business travel with smart organization. Premium quality & style.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82ca3a897a699f95a3720d18', 'zh-CN', 'heere：脚下的历史故事', '根据实时定位自动讲述你所处地点的历史，让旅行与了解地方历史更有趣。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_82ca3a897a699f95a3720d18', 'en', 'heere - Stories Underfoot', 'The idea started pretty simply. I kept feeling that with AI now in the picture, there should be a more interesting way to travel and learn the history of any given place.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
