INSERT INTO product_content (product_id, locale, title, summary, content_source, enrichment_run_id, is_current) VALUES ('prd_0b65fb436ec8e8e6b8ba65e2', 'zh-CN', 'WanderDays 旅行天数追踪', '记录各国停留天数与逐日旅行历史，支持申根90/180计算、自动或手动记录、提醒、小组件和数据导出。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_0b65fb436ec8e8e6b8ba65e2', 'en', 'WanderDays', 'WanderDays helps users count how many days they spend in each country and keep a complete day-by-day travel history.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ad2651260117fa5001392c2', 'zh-CN', 'MaxPoints：信用卡奖励与旅行积分管理', '追踪信用卡奖励、权益和旅行积分，提升每张卡的价值。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_8ad2651260117fa5001392c2', 'en', 'MaxPoints', 'Track credit card rewards, benefits, and travel credits so you can get more value from every card.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee5ccd118cbe82f26c27f419', 'zh-CN', 'Zak Mobile Tyres Glasgow：格拉斯哥上门轮胎服务', '格拉斯哥本地移动轮胎服务，为车主提供上门换胎与轮胎援助，免去前往修理厂。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee5ccd118cbe82f26c27f419', 'en', 'Zak Mobile Tyres Glasgow', 'Zak Mobile Tyres Glasgow is a local mobile tyre service created to make tyre fitting more convenient for drivers across Glasgow. Instead of travelling to a garage, customers can arrange tyre assistance at a location that suits them.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee3f61ccf06914bbdc48e63b', 'zh-CN', 'Journeylore：日本旅行探索指南', '日本地图旅行探索指南，提供地点历史故事与隐藏景点发现，核心功能免费免登录。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_ee3f61ccf06914bbdc48e63b', 'en', 'Journeylore', 'Every place holds the history and stories of its people. Journeylore is a travel and exploration guide app that helps you discover these captivating narratives.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7efc11dfd7a52e3d89921c65', 'zh-CN', 'UNSEEN：探索风景与摄影地点', '面向摄影与旅行爱好者的地点发现和内容分享应用，可在地图探索摄影点、发布作品并参与社区互动。', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0),('prd_7efc11dfd7a52e3d89921c65', 'en', 'Unseen-Exploring Scenic Beauty', 'UNSEEN is a location discovery and content-sharing app designed for photography and travel enthusiasts.', 'llm:travel-localize-v1', 'enr_42e598705df39a84ee3a8086', 0);
